insert into corpus_findings
  (area, topic, claim, basis, confidence, sport, quantities, source)
values
('tempo', 'eccentric control and pause in the stretch position', 'For exercises like bench press, squat, and RDL, recommends slowing/controlling the lowering (eccentric) phase to reach a deeper stretch and even pausing briefly in the lengthened position before exploding out of it, rather than the common pattern of resting at the top and rushing through the bottom/stretch position.', 'opinion', 'weak', NULL, '{"note": "pause briefly in lengthened position, then explode out of the stretch"}'::jsonb, 'Built With Science (Ethier) — How to Build Muscle 2x Faster (Genius Strategy)'),
('strength-accessories', 'exercise selection to increase muscle stretch', 'Recommends choosing exercise variations that increase the stretch on the target muscle beyond what a barbell allows: dumbbell bench press or deficit push-ups (unrestricted by ground/torso contact) over barbell bench for a deeper pec stretch, and generally favors dumbbell flyes (chest), overhead triceps extensions, reverse cable flyes (rear delts), and behind-the-body lateral raises with the cable at wrist height (shoulders) because these load the muscle hardest at end-range stretch.', 'opinion', 'weak', NULL, '{"examples": ["dumbbell bench/deficit push-up over barbell bench", "dumbbell flyes for chest", "overhead extensions for triceps", "reverse cable flyes for rear delts", "behind-the-body lateral raises for shoulders"]}'::jsonb, 'Built With Science (Ethier) — How to Build Muscle 2x Faster (Genius Strategy)'),
('strength-accessories', 'loaded stretch beats maximal stretch alone', 'When choosing between two exercises with different stretch profiles, prioritizes the one that keeps resistance high AT the stretched position (e.g., preacher curl, hardest near the bottom) over one with a larger stretch that is easiest at end-range (e.g., incline curl, hardest mid-range) — states he''d pick resistance-in-the-stretch over maximizing stretch alone.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Build Muscle 2x Faster (Genius Strategy)'),
('volume-per-muscle', 'lengthened partial reps as a growth/extension technique', 'For exercises hardest in the fully contracted position (most back exercises, lat pulldowns/rows, calf raises, chest flyes, reverse flyes, dumbbell lateral raises, leg extensions), presents replacing some full-ROM reps with half reps confined to the stretched half of the range as a way to boost growth, and recommends continuing with stretch-position half reps after reaching failure on full-ROM reps as a way to extend a set past failure.', 'opinion', 'weak', NULL, '{"note": "lengthened partial reps performed in the stretched half of ROM; also used post-failure as a burnout extension"}'::jsonb, 'Built With Science (Ethier) — How to Build Muscle 2x Faster (Genius Strategy)'),
('tempo', 'personal use of stretch-focused technique', 'States that shifting his own training toward the stretch position (deeper ROM, stretch-biased exercise selection, lengthened partial reps) has personally produced faster muscle growth for him than any other technique he has tried.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Build Muscle 2x Faster (Genius Strategy)'),
('periodization', 'personal training split', 'Currently follows a 5-day Upper/Lower/Push/Pull/Legs hybrid split himself, choosing it because it fits in more weekly volume than a 4-day upper/lower split without the full time commitment of a 6-day push/pull/legs split.', 'practice', 'weak', NULL, '{"days_per_week": 5, "split": "Upper/Lower/Push/Pull/Legs hybrid"}'::jsonb, 'Built With Science (Ethier) — I Tested EVERY Workout Split (Using Science)'),
('periodization', 'chooses time-efficiency over the theoretically best split', 'Despite ranking a 5-day full-body split (each muscle trained 5x/week) as producing the greatest muscle growth in his own scoring model, personally chooses not to use it because full-body sessions require warming up the whole body every session, adding time; instead favors a 4-day upper/lower split, stating it delivers roughly 85% of the top split''s gains for about 30% less weekly training time.', 'practice', 'weak', NULL, '{"gains_pct_of_best_split": 85, "time_savings_pct": 30, "preferred_split": "4-day upper/lower"}'::jsonb, 'Built With Science (Ethier) — I Tested EVERY Workout Split (Using Science)'),
('periodization', 'beginner frequency recommendation', 'Recommends a 3-day/week full-body split for beginners specifically so they can focus on mastering and progressing their main compound lifts, citing a meta-analysis (attributed to Josh Pelland) that training a muscle 3x/week can raise strength gains by around 50% versus 1x/week at equal weekly volume, while noting the effect on hypertrophy specifically is described as smaller.', 'opinion', 'weak', NULL, '{"frequency_per_week": 3, "strength_gain_pct": 50, "note": "frequency effect on hypertrophy is described as smaller than on strength"}'::jsonb, 'Built With Science (Ethier) — I Tested EVERY Workout Split (Using Science)'),
('guideline', 'possible ''junk volume'' late in single-muscle bro-split sessions', 'Suggests that in a bro-split (one muscle trained per day across many sets), performance drops considerably by the 3rd-4th exercise for that muscle, raising the possibility that late-session sets become low-value ''junk volume'' better moved to another day — but explicitly flags this as unconfirmed and needing more research.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Tested EVERY Workout Split (Using Science)'),
('periodization', 'deloads are a sign of overtraining, not a routine requirement', 'Argues a scheduled deload is a sign the training program was too aggressive — most lifters training and eating appropriately don''t need a deload at all; only the most intense trainers (his estimate: roughly the top 5%) need to schedule them regularly.', 'opinion', 'weak', NULL, '{"population_needing_deload_pct": 5}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Using Deloads To Maximize Muscle Growth'),
('periodization', 'shorter-than-a-week deloads', 'Argues the conventional 1-week deload length is arbitrary and often excessive; recommends much shorter deloads instead — as little as a single day, or one full rotation through a training split (e.g., 3 days for a 3-day split) — rather than a full week off or of easy training.', 'practice', 'weak', NULL, '{"deload_options": ["1 day", "1 full training-split rotation"], "conventional_length_note": "1 week is considered excessive"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Using Deloads To Maximize Muscle Growth'),
('periodization', 'in-gym deload protocols', 'Describes concrete deload protocols for lifters who still want to train through it: (a) half the usual set volume at the same intensity/effort, (b) the same volume but roughly 3 reps short of failure (no failure work), or (c) about 3/4 volume combined with 3/4 intensity — any of which shortens session length and lowers recovery cost versus a full week off.', 'practice', 'weak', NULL, '{"option_a_volume_pct": 50, "option_c_volume_pct": 75, "option_c_intensity_pct": 75, "option_b_reps_short_of_failure": 3}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Using Deloads To Maximize Muscle Growth'),
('periodization', 'localized deloads for fatigue from outside the gym', 'When soreness/fatigue comes from an activity outside the gym (e.g., skiing, running, a sport), recommends only deloading the affected body part/training day rather than taking a whole week off from all training.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Using Deloads To Maximize Muscle Growth'),
('periodization', 'deload frequency for those who need one', 'For lifters intense enough to actually need scheduled deloads, suggests roughly every 8-12 weeks rather than the common convention of every 4 weeks.', 'opinion', 'weak', NULL, '{"frequency_weeks_low": 8, "frequency_weeks_high": 12, "common_convention_weeks": 4}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Using Deloads To Maximize Muscle Growth'),
('tempo', 'using deload periods to reset technique', 'Recommends using a deload period to deliberately vary training — lighter loads, different rep ranges/exercises, or a circuit/agonist-antagonist format — with slow, controlled reps to rebuild mind-muscle connection and reset form, framed as protection against progressive ''ego lifting'' form breakdown from constantly adding weight.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Using Deloads To Maximize Muscle Growth'),
('volume-per-muscle', 'competing weekly set recommendations across coaches', 'States his own recommendation (which he says he shares with Dr. Mike Israetel) is roughly 10-20 sets per muscle per week, versus a broader 8-32 set range he attributes to Jeff Cavaliere, who suggests starting at 15-18 sets.', 'opinion', 'weak', NULL, '{"doucette_range_low": 10, "doucette_range_high": 20, "cited_other_range_low": 8, "cited_other_range_high": 32, "cited_other_start": "15-18"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('volume-per-muscle', 'sets per week by experience level', 'Recommends roughly 10 sets/muscle/week for beginners, 15 for intermediates, and 20 for advanced lifters, based on his own progression across a multi-decade training career.', 'practice', 'weak', NULL, '{"beginner": 10, "intermediate": 15, "advanced": 20, "unit": "sets/week"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('volume', 'training goal changes the volume/intensity trade-off', 'States that across his own career as both a competitive powerlifter and bodybuilder, he used fewer sets with heavier loads/lower reps for powerlifting-focused training, and deliberately used more sets with lighter loads for bodybuilding — specifically avoiding max-effort low-rep work (e.g., 5x5) as a bodybuilder to reduce injury risk, even though he acknowledges heavier low-rep work would still build muscle.', 'practice', 'weak', NULL, '{"powerlifting_style": "fewer sets, heavier loads, lower reps", "bodybuilding_style": "more sets, lighter loads"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('volume-per-muscle', 'volume needed is inversely related to per-set effort', 'States that the amount of volume needed for growth is inversely related to how close to failure each set is taken: near-failure/high-effort sets need less total volume but longer rest (his own example: around 5 minutes'' rest after an all-out leg press taken to and beyond failure), while lower-effort sets (short 30s-1min rests) require more total sets to compensate for reduced per-set stimulus. This converges with a separate, independent practitioner claim in this same batch (a natural bodybuilder''s account, relayed by Built With Science, of cutting volume while raising per-set effort and seeing more growth).', 'practice', 'moderate', NULL, '{"high_effort_rest_minutes": 5, "low_effort_rest_range": "30s-1min"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('strength-accessories', 'compound vs. isolation exercises need different volume', 'Argues exercises with greater systemic stress (compound multi-joint lifts like squats, bench press, deadlifts) warrant fewer weekly sets than single-joint/isolation exercises, which impose less fatigue per set and can tolerate or require more total volume.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('progression', 'progression without adding weight', 'Defines his ''harder than last time'' progression cue as not requiring more weight or more sets every session — instead recommends making a given weight feel harder via technique (slowing the eccentric, pausing under load, improving mind-muscle connection), specifically as a way to keep progressing while reducing injury risk versus constantly adding load.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('guideline', 'recovery status should override the programmed volume target', 'States that regardless of what a volume range (e.g., 8-32 sets) recommends, if a lifter is sore and not recovered from the prior session that''s a sign the current volume/intensity is too much and should be reduced (even down to one set); if not sore and not progressing, volume or intensity should increase instead. Also recommends starting any new volume prescription at the low end of the range (not the middle) and adjusting up from there based on recovery.', 'opinion', 'weak', NULL, '{"note": "recovery/soreness status, not the prescribed number, should govern next-session dosing; start at the low end of any range"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('masters', 'reducing volume with age and joint wear', 'Describes shifting from extremely high training volumes as a teenager (escalating rep-matched-to-load sets up to 90 reps at 90 lb, roughly 10 sets of 10 for chest daily for months) to much lower volume later in his career due to accumulated joint damage, and recommends older or injured lifters deliberately reduce sets/volume.', 'practice', 'weak', NULL, '{"youth_example": "~10 sets of 10 daily for chest, sustained for months"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('volume-per-muscle', 'concurrent cardio reduces the lifting volume needed', 'Recommends lowering resistance-training set volume for muscle groups also stressed by significant concurrent cardio training (e.g., less leg volume for cyclists, less back/shoulder volume for swimmers) to manage total recovery demand.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('guideline', 'circuit/agonist-antagonist training to fit more volume into less time', 'Personally uses agonist-antagonist circuit-style training — alternating sets between opposing or unrelated muscle groups (e.g., chest/back, or a rotating circuit of shoulders/biceps/calves/abductors/adductors) — to fit more total volume and exercises into a session by resting one muscle group while training another, instead of resting idle between straight sets.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('periodization', 'beginner frequency and volume progression', 'Recommends beginners start with full-body training 3x/week, splitting a low total weekly volume across those sessions (e.g., 9 weekly chest sets as 3 sets x 3 days), then let soreness/recovery guide progression toward higher per-session volume and fewer weekly sessions over time.', 'opinion', 'weak', NULL, '{"frequency_per_week": 3, "example_split": "9 sets/week as 3x3"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does The "X" Stand for WRONG? Athlean-X || Chest Training Volume'),
('strength-accessories', 'rest-pause protocol for time-efficient bicep training', 'Describes a rest-pause protocol: pick a load allowing about 6-8 reps, perform to failure, rest only about 20 seconds, then repeat mini-sets (typically 4-5 rounds) until reaching a target total rep count (e.g., 20 total reps) — presented as producing similar size/strength gains to traditional straight sets (3x6 with 90s rest) in roughly half the time.', 'opinion', 'weak', NULL, '{"initial_load_reps": "6-8", "rest_between_mini_sets_sec": 20, "target_total_reps": 20, "typical_mini_sets": "4-5"}'::jsonb, 'Built With Science (Ethier) — How To Grow Your Biceps In 10 Minutes (Using Science)'),
('strength-accessories', 'bicep curl technique cues', 'Coaching cues for curls: keep the elbow locked at the side with minimal forward swing (excess swing shifts tension to the front delts), and keep the wrist neutral without excessive curling at the top of the rep (prevents the forearm from taking over) — both aimed at maximizing tension on the biceps.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How To Grow Your Biceps In 10 Minutes (Using Science)'),
('strength-accessories', 'exercise pairing to bias biceps heads', 'States that curls with the arm in front of the body (standard curl position) bias the short/inner biceps head, while curls with the arm behind the body (e.g., incline curl on a bench set to about 30 degrees, arms hanging behind the torso) bias the long/outer head, and recommends pairing one of each back-to-back as a compound set to hit both heads in one time-efficient block.', 'opinion', 'weak', NULL, '{"bench_angle_degrees": 30, "reps_per_exercise": "8-12"}'::jsonb, 'Built With Science (Ethier) — How To Grow Your Biceps In 10 Minutes (Using Science)'),
('strength-accessories', 'keep the upper arm perpendicular during curls', 'Cue for both front and behind-body curls: keep the upper arm perpendicular to the ground throughout the rep, resisting the elbow drifting backward (on front curls) or drifting up toward the torso (on behind-body curls), to keep tension on the biceps rather than letting the shoulder take over.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How To Grow Your Biceps In 10 Minutes (Using Science)'),
('strength-accessories', 'hammer curl drop sets for the brachialis', 'Recommends targeting the brachialis (which sits under the biceps and can visually push the biceps up) with neutral-grip hammer curls performed as drop sets: initial set to failure at a load allowing about 15-20 reps, then immediately dropping to the next lightest dumbbells and continuing to failure, for 5 total drop sets — presented as producing gains similar to traditional sets in under a third of the time.', 'opinion', 'weak', NULL, '{"initial_reps": "15-20", "total_drop_sets": 5}'::jsonb, 'Built With Science (Ethier) — How To Grow Your Biceps In 10 Minutes (Using Science)'),
('volume-per-muscle', 'minimal-effective volume vs. a time-efficient sweet spot', 'Recommends roughly 3 sets/muscle/week as enough to maintain gains (and, per cited research, still build a little muscle even in some trained lifters), with 4-7 sets/muscle/week presented as the time-efficient ''sweet spot'' — versus 10+ sets/week needed to chase maximum possible growth.', 'opinion', 'weak', NULL, '{"maintenance_sets_per_week": 3, "sweet_spot_low": 4, "sweet_spot_high": 7, "max_gains_sets_per_week": 10}'::jsonb, 'Built With Science (Ethier) — How to Get MORE Growth In Less Time (3 Gym Hacks)'),
('progression', 'compensate low volume with proximity to failure', 'When training with minimal weekly volume, recommends pushing every set to within 1-2 reps of failure (going all the way to failure on exercises where it''s safe) to preserve growth despite the reduced set count.', 'opinion', 'weak', NULL, '{"reps_in_reserve": "1-2"}'::jsonb, 'Built With Science (Ethier) — How to Get MORE Growth In Less Time (3 Gym Hacks)'),
('strength-accessories', 'antagonist supersets with short transitions', 'Recommends antagonist supersets (pairing exercises for opposing/unrelated muscles back-to-back, e.g., bench press + calf raises, chest flyes + lateral raises, leg extensions/curls + an upper-body exercise) to cut workout time roughly in half, and recommends keeping the transition between the paired exercises under about 1 minute — citing a study where subjects completed more reps with short transitions than with longer rest or straight sets — provided each exercise is still taken close to failure.', 'opinion', 'weak', NULL, '{"transition_max_sec": 60}'::jsonb, 'Built With Science (Ethier) — How to Get MORE Growth In Less Time (3 Gym Hacks)'),
('strength-accessories', 'which exercises suit drop sets', 'Recommends drop sets only on exercises that are safe to take to true failure and quick to strip weight from (lateral raises, arm exercises, dumbbell chest presses, calf raises, many machines), explicitly advising against drop sets on squats and deadlifts, and only doing them on bench press with a spotter present.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Get MORE Growth In Less Time (3 Gym Hacks)'),
('volume', 'drop-set dosing protocol', 'Describes a drop-set protocol: after an initial set to failure, reduce the load by about 20% per drop and continue to failure for 2-4 total drop sets, aiming to match the total number of effective sets (normal set plus drops) against the straight-set count it''s replacing.', 'opinion', 'weak', NULL, '{"load_reduction_pct": 20, "drop_sets_low": 2, "drop_sets_high": 4}'::jsonb, 'Built With Science (Ethier) — How to Get MORE Growth In Less Time (3 Gym Hacks)'),
('volume-per-muscle', '10-20 sets/week sweet spot, with a triceps exception', 'Cites a follow-up meta-analysis (after the widely-cited 2017 Schoenfeld analysis favoring 10+ sets/week) finding no significant hypertrophy difference between moderate (12-20 sets/week) and high (20+ sets/week) volumes for most muscles — suggesting an upper limit past which more volume stops helping and may even hinder growth via recovery cost — with the triceps as the one muscle that kept responding better to 20+ sets/week.', 'opinion', 'weak', NULL, '{"sweet_spot_low": 10, "sweet_spot_high": 20, "triceps_exception": true}'::jsonb, 'Built With Science (Ethier) — How Many Sets Do You Really Need to Build Muscle?'),
('volume-per-muscle', 'individual variability in optimal volume', 'Cites a unilateral-limb study (one leg trained at 6-9 sets/week, the other at 15 sets/week, within the same person) where roughly a third of participants grew better from the lower-volume leg, a third from the higher-volume leg, and a third responded similarly in both — used as evidence that optimal weekly volume is highly individual and not fully predictable from population averages.', 'opinion', 'weak', NULL, '{"low_volume_sets_per_week": "6-9", "high_volume_sets_per_week": 15, "responder_split": "roughly one-third each"}'::jsonb, 'Built With Science (Ethier) — How Many Sets Do You Really Need to Build Muscle?'),
('volume-per-muscle', 'cutting volume while raising effort increased growth (practitioner case)', 'A natural bodybuilder interviewed in the video describes cutting his weekly volume from an estimated 30-40 sloppy, non-failure sets per muscle group down to 7-12 sets per muscle group, while training much closer to true failure with strict form and longer rest between sets, and reports this produced the best muscle growth of his training career after high-volume training alone had stalled his progress for months. This converges with a separate, independent claim in this batch (Greg Doucette''s account that volume needed is inversely related to per-set effort).', 'practice', 'moderate', NULL, '{"before_sets_per_week": "30-40", "after_sets_per_week": "7-12"}'::jsonb, 'Built With Science (Ethier) — How Many Sets Do You Really Need to Build Muscle?'),
('volume-per-muscle', 'indirect set-counting inflates apparent volume needs for secondary movers', 'Notes that most volume research counts a muscle''s indirect involvement in a compound lift as a full set for that muscle (e.g., a bench press set counted as one set each for chest AND triceps) — implying muscles that are frequently secondary movers in pressing/pulling (triceps, front/rear delts, biceps) likely need fewer direct/isolation sets than the raw weekly set-count guidelines suggest, since much of their volume already comes indirectly.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How Many Sets Do You Really Need to Build Muscle?'),
('progression', 'rest period length affects sets needed', 'Recommends resting at least about 2 minutes between most sets, noting that shorter rest periods (under 2 minutes) appear to require more total sets to achieve the same growth as longer rest, since the underlying volume research mixed both short- and long-rest protocols.', 'opinion', 'weak', NULL, '{"min_rest_minutes": 2}'::jsonb, 'Built With Science (Ethier) — How Many Sets Do You Really Need to Build Muscle?'),
('strength-accessories', 'a single all-out HIT set framed as equivalent to multiple sets', 'References Dorian Yates-style high-intensity training (HIT) — a single all-out set extended past failure with forced reps, rest-pause reps, or drop-set reps — and reasons that one such set may deliver similar total time-under-tension/stimulus to 2-3 conventional sets, offered as an explanation for why very-low-set-count HIT approaches can still work despite conflicting with the typical 10-20 weekly set guidance.', 'opinion', 'weak', NULL, '{"claimed_equivalent_normal_sets": "2-3"}'::jsonb, 'Built With Science (Ethier) — How Many Sets Do You Really Need to Build Muscle?'),
('progression', 'start low, don''t chase the theoretically optimal volume', 'Recommends beginners start at the low end of the 10-20 weekly set range, and argues that because returns diminish within that range (10 sets isn''t double the growth of 5 sets; 5-9 sets already yields about 80% of maximum growth per the cited meta-analysis), most lifters — especially those struggling with consistency — should not chase the theoretically optimal volume and can get strong results from far less.', 'opinion', 'weak', NULL, '{"beginner_start": "low end of the 10-20 sets/week range", "pct_of_max_growth_from_5to9_sets": 80}'::jsonb, 'Built With Science (Ethier) — How Many Sets Do You Really Need to Build Muscle?'),
('progression', 'consistent exercise selection + logged progression', 'Coach requires clients to stick with the same exercises for several weeks (framing constant-switching as ''HADD'') and to log exercise, sets, reps, weight, and effort every session so each workout has a specific target to beat; treats this logging discipline as the main lever most lifters are missing, not exercise choice itself.', 'practice', 'weak', NULL, '{"note": "recommends sticking with an exercise at least 2-3 weeks before switching"}'::jsonb, 'Built With Science (Ethier) — The 3 WORST Workout Routine Mistakes (GAIN KILLERS!)'),
('volume-per-muscle', 'per-session set ceiling and splitting volume across sessions', 'Programs cap productive sets at roughly 10 sets per muscle group within a single session (near/to failure); volume beyond that is treated as ''junk'' that adds fatigue without added growth, so weekly volume is deliberately split across 2-3 sessions per muscle per week rather than done in one workout.', 'practice', 'weak', NULL, '{"sets_per_muscle_per_session_ceiling": 10}'::jsonb, 'Built With Science (Ethier) — The 3 WORST Workout Routine Mistakes (GAIN KILLERS!)'),
('strength-accessories', 'avoiding redundant exercise selection within a session', 'When choosing which exercises fill a muscle''s working sets, deliberately avoids picking near-duplicate movements (e.g., barbell bench + flat dumbbell press + flat machine press, or standing barbell/dumbbell/cable curls) because they hit the same angle and provide largely overlapping stimulus; instead pairs biomechanically distinct variations (e.g., incline dumbbell press + flat bench + cable fly, or preacher + incline + hammer curl) so the same number of sets covers more of the muscle.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The 3 WORST Workout Routine Mistakes (GAIN KILLERS!)'),
('progression', 'double progression scheme', 'Primary progression system taught in these programs is double progression: pick a rep range (e.g., 8-12) and a starting weight, add one rep per set each week until every set hits the top of the range, then add weight and drop back to the bottom of the range and repeat.', 'practice', 'weak', NULL, '{"note": "example range 8-12 reps per set"}'::jsonb, 'Built With Science (Ethier) — How To FORCE Muscle Growth (5 Science-Based Methods)'),
('periodization', 'volume ramp-and-deload rule', 'When load/rep progression stalls, adds volume as the next lever, but caps weekly volume increases at roughly 10-20% per week and deliberately cycles back down to the original (lower) volume once weekly sets reach the 20-30 sets/muscle range or fatigue becomes high, rather than continuing to add sets indefinitely.', 'practice', 'weak', NULL, '{"max_weekly_volume_increase_pct": "10-20", "cycle_down_threshold_sets_per_muscle_per_week": "20-30"}'::jsonb, 'Built With Science (Ethier) — How To FORCE Muscle Growth (5 Science-Based Methods)'),
('tempo', 'slow-tempo overload for small/bodyweight movements', 'For exercises where adding weight is impractical (lateral raises, push-ups, pull-ups), uses tempo as the overload variable instead: slows the rep by about 1 second per week on both the concentric and eccentric until reaching roughly 3 seconds up / 3 seconds down (about 6 seconds total), then switches back to a load- or rep-based method because going slower than that is considered counterproductive.', 'practice', 'weak', NULL, '{"max_total_tempo_seconds": 6, "increment_seconds_per_week": 1}'::jsonb, 'Built With Science (Ethier) — How To FORCE Muscle Growth (5 Science-Based Methods)'),
('progression', 'form-quality as a progression axis', 'Treats cleaning up execution — less momentum, more control, more target-muscle activation — as a legitimate form of progression on its own, independent of adding weight, reps, or sets; says even advanced lifters on their coaching staff continue to spend time tightening form rather than assuming it''s already optimal.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How To FORCE Muscle Growth (5 Science-Based Methods)'),
('strength-accessories', 'contradiction: resistance-profile (stretch- vs squeeze-biased loading) and hypertrophy', 'Self-funded within-subject MRI study (n=20, 10 weeks, custom adjustable-resistance-profile machines) found identical growth in chest, side delts, rear delts, and glutes whether an exercise was set up to be hardest in the stretched position or hardest in the squeezed position, provided full range of motion and continuous tension were maintained in both. This conflicts with the common ''science-based lifting'' claim that biasing an exercise''s loading toward the stretched position (e.g., preferring incline curl over preacher curl, or overhead extension over pushdown) produces superior hypertrophy — that claim held in prior single-joint research but did not generalize across these four muscle groups in this test.', 'opinion', 'weak', NULL, '{"n": 20, "duration_weeks": 10, "design": "within-subject, split-body"}'::jsonb, 'Built With Science (Ethier) — The Muscle Building Myth Everyone Fell For (NEW Study)'),
('strength-accessories', 'biarticulate muscles as the exception to the stretch-null finding', 'Argues the stretch-doesn''t-matter finding above does not apply to biarticulate muscles that cross two joints (hamstrings, quads, calves, triceps) — these still show a real advantage from exercises that achieve a deeper stretch, per prior literature; calves specifically respond so strongly to the stretched position that one cited study found partial reps at the bottom outgrew full-range-of-motion reps.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Muscle Building Myth Everyone Fell For (NEW Study)'),
('tempo', 'range of motion still limits growth regardless of resistance profile', 'Regardless of where an exercise is hardest, cutting the range of motion short (not reaching the stretched end-range) is still treated as a real limiter of growth — the null result on resistance profile only held when both stretch- and squeeze-biased versions used a full range of motion with at least some tension at the stretched end.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Muscle Building Myth Everyone Fell For (NEW Study)'),
('strength-accessories', 'self-test to individualize incline angle for upper chest', 'Uses a self-test to set incline degree per individual: lie on a flat bench and place a phone flat on the chest — if it tilts downward toward the feet, the lifter has a steep sternum and needs a steeper incline to bias the upper chest; if the phone stays roughly flat, the lifter has a flat sternum and only a slight incline (one or two notches) is needed.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('strength-accessories', 'squat stance driven by limb proportions', 'Squat setup is individualized by anthropometry: shorter femurs and better ankle mobility allow an upright, deep squat; longer femurs and less ankle mobility require more forward lean and hip-hinge and less depth without rounding the lower back — both are treated as correct technique for that body, not a fault to be coached out. For lifters who can''t squat deep while staying upright, elevating the heels is used as a fix to shift more emphasis onto the quads.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('strength-accessories', 'leg curl variation and form', 'Prefers seated leg curl over lying leg curl when available, citing a study showing significantly greater hamstring growth from the deeper stretch achieved in the seated version (though calls lying leg curl ''a fantastic option'' on its own); on either variation, stops just short of full knee extension at the bottom of each rep rather than fully straightening the leg, because the first ~15 degrees of knee extension is calf-dominated rather than hamstring-dominated.', 'opinion', 'weak', NULL, '{"knee_extension_degrees_dominated_by_calf": 15}'::jsonb, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('strength-accessories', 'direct arm isolation despite compound back/press work', 'Includes direct biceps curls and overhead triceps extensions in a full-body routine despite already programming rows and presses, reasoning that rows are a weak biceps stimulus (cites a study finding curls produced roughly double the biceps growth of rows) and that pressing movements barely grow the triceps long head because it''s in a mechanically disadvantaged position during pressing — the long head is instead trained through exercises with the arm overhead.', 'practice', 'weak', NULL, '{"note": "cited study: curls ~2x biceps growth of rows"}'::jsonb, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('tempo', 'lengthened partial reps appended after failure', 'Standard technique across this routine: once a set reaches failure on full-range reps, immediately continues with 3-5 additional half reps in the bottom/stretched position (applied to rows, pulldowns, leg extensions performed leaning back, chest flies, and rear delt flies) to add extra stimulus from the stretched portion of the movement after full-ROM capacity is exhausted.', 'practice', 'weak', NULL, '{"bonus_half_reps": "3-5"}'::jsonb, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('strength-accessories', 'standing calf raise over seated for total calf development', 'Prefers standing calf raise (leg press, Smith machine, or single-leg dumbbell, any variation keeping the leg straight) over seated calf raise, citing research that standing calf raises match seated calf raises on the muscle seated raises are traditionally believed to target while growing the other calf muscle significantly more — pauses at the bottom of each rep for a deep stretch, called one of the most important growth drivers for calves specifically.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('periodization', 'deliberate exercise rotation across a 3-day full-body split', 'Uses three different full-body workouts per week (not the same six exercises repeated three times) that hit the same muscle groups through different exercises workout to workout, reasoning this produces more balanced regional muscle development, lowers overuse-injury risk from repeating identical movement patterns, and improves adherence/motivation compared to repeating one fixed workout three times a week.', 'practice', 'weak', NULL, '{"sessions_per_week": 3, "exercises_per_session": 6}'::jsonb, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('guideline', 'ramping warm-up protocol before heavy compound lifts', 'Warms up heavy compound lifts with a 3-set ramp: one light set of 8-10 reps, then a heavier set of 3-5 reps, then a near-max set of 1-2 reps, before starting working sets — done to prepare joints/muscles without draining energy for the working sets.', 'practice', 'weak', NULL, '{"warmup_sets": [{"reps": "8-10", "load": "light"}, {"reps": "3-5", "load": "moderate"}, {"reps": "1-2", "load": "heavy"}]}'::jsonb, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('strength-accessories', 'hip thrust as a glute accessory alongside squats', 'Programs hip thrusts alongside squats rather than relying on squats alone for glute development, citing a study where adding hip thrusts to an existing leg workout nearly doubled glute growth compared to the leg workout by itself; flags it as especially useful for people who sit most of the day.', 'practice', 'weak', NULL, '{"note": "cited study: hip thrust added to leg day ~2x glute growth vs leg day alone"}'::jsonb, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat'),
('tempo', 'personal rep tempo and rep-range sweet spot', 'Measured his own average rep speed at roughly 3 seconds per rep (about 1.5s eccentric with a slight pause at the bottom, fast concentric) and uses that to justify an 8-12 rep working range as the time-efficient sweet spot for most exercises in a time-constrained program, extending to about 15 reps for lower-fatigue-cost muscles like calves and arms where the extra time under tension is cheap.', 'practice', 'weak', NULL, '{"avg_seconds_per_rep": 3, "eccentric_seconds": 1.5, "rep_range_default": "8-12", "rep_range_low_fatigue_muscles": "up to 15"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('guideline', 'decreasing rest periods to fit more volume into limited time', 'Programs incrementally decreasing rest periods across a session (starting near 2 minutes and stepping down toward roughly 30 seconds) rather than a fixed rest interval, in order to fit more total sets into a time-capped workout; also notes smaller muscle groups (e.g., biceps) tolerate and need shorter rest between sets than larger muscle groups.', 'practice', 'weak', NULL, '{"rest_start_seconds": 120, "rest_end_seconds": 30}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('volume', 'superset pairing to add volume density', 'Structures time-limited workouts around supersets throughout, either antagonist pairs (biceps/triceps, quads/hamstrings) or same-muscle compound sets (e.g., chest immediately followed by chest again), moving with minimal rest between the two exercises in the pair to preserve the extra-rep benefit of supersetting.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('volume', 'drop sets and rest-pause sets as routine volume-density tools', 'Uses drop sets and rest-pause sets as standard tools for adding effective volume within a short workout, treating them as a viable (if not fully proven equivalent) substitute for extra straight sets when time is the binding constraint.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('volume', 'contradiction: what counts as a cluster set', 'Rejects the textbook definition of cluster sets used in the research he cites (e.g., splitting a set of 8 into 4+4 with intra-set rest, deliberately stopping short of failure) as pointless, and says that''s why meta-analyses find cluster sets underperform other density techniques. His own practice under the same name is different: 1-2 breaths of rest between clusters, pushed to failure 4 times consecutively — which he argues the literature hasn''t actually tested.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('tempo', 'loaded end-of-set stretch hold', 'On the last working set of the last exercise for a given muscle (used for dumbbell chest work and calves specifically), holds a deep loaded stretch for 20-30 seconds immediately after the final eccentric rep; restricts this to one exercise per muscle group because of how fatiguing/taxing it is.', 'practice', 'weak', NULL, '{"stretch_hold_seconds": "20-30"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('volume-per-muscle', 'practical minimum weekly volume for time-constrained training', 'Treats roughly 5 sets per muscle per week as the practical floor for eliciting growth in a time-constrained program (citing the largest marginal gains occurring in the 1-5 set range with a plateau around 15-16 sets/muscle/week), and treats each head of a multi-part muscle like the delts as needing its own set allotment — noting that fully covering all three delt heads alone can require around 15 sets.', 'opinion', 'weak', NULL, '{"min_sets_per_muscle_per_week": 5, "plateau_sets_per_muscle_per_week": "15-16", "delt_heads_total_sets_example": 15}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('periodization', '4-day split chosen for a time-capped program', 'Builds the time-efficient (30-min session) program as a 4-day split rather than 3-day, judging that 3 days can''t cover every muscle group effectively when each session is capped at 30 minutes.', 'practice', 'weak', NULL, '{"days_per_week": 4}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('volume-per-muscle', 'convergent volume dose-response shape across independent channels', 'Two independent channels in this batch (Built With Science/Ethier and Ryan Humiston) both describe a hypertrophy volume dose-response curve with strong early returns and a clear ceiling in the high-teens of sets per muscle per week, despite citing different meta-analyses and different exact numbers: Ethier cites roughly a doubling of gains going from 5 to 10 sets/week with a plateau around 20-30 sets; Humiston cites most of the benefit occurring in the 1-5 set range with a plateau around 15-16 sets/week. The specific numbers differ but the general shape (fast early gains, clear mid-teens-to-twenties ceiling) is consistent between them.', 'opinion', 'moderate', NULL, NULL, 'Built With Science (Ethier) — How To FORCE Muscle Growth (5 Science-Based Methods); Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('tempo', 'convergent use of supplemental stretch-position work at the end of a set', 'Two independent channels in this batch (Built With Science/Ethier and Ryan Humiston) independently append extra time in the stretched position onto the end of a working set as a supplemental growth technique — Ethier as 3-5 lengthened partial reps after failure, Humiston as a 20-30 second loaded stretch hold after the final rep — both applying it selectively (last exercise or last set only) because of how fatiguing it is.', 'practice', 'moderate', NULL, NULL, 'Built With Science (Ethier) — The #1 Full Body Routine to Build Muscle & Lose Fat; Ryan Humiston (physique, exercise selection) — Build MORE Muscle in HALF THE TIME! (Science Backed 30 Min Workout)'),
('strength-accessories', 'grip selection', 'Uses a double-overhand grip with lifting straps for deadlifts (avoiding an alternating/mixed grip) to prevent grip strength from being the limiting factor and to avoid the muscular imbalances that can develop from always pulling with one arm supinated and one pronated; suggests alternating which side is over/under if a mixed grip is used.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Tips || How To - Perfect Your DEADLIFT || Proper Form and Common Mistakes'),
('strength-accessories', 'sumo deadlift setup cue', 'Sumo deadlift setup cue: get the hips as close to the bar as possible with tibias touching the bar, using a wide stance with feet turned out roughly 45 degrees and knees pushed out — describes the pull as a hybrid of a squat and deadlift that leans more on legs/hips/glutes than a conventional pull.', 'practice', 'weak', NULL, '{"foot_turnout_deg": 45}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Tips || How To - Perfect Your DEADLIFT || Proper Form and Common Mistakes'),
('clinical', 'sumo deadlift for back issues', 'Switched to pulling sumo instead of conventional specifically because of chronic L4/L5 herniated discs — sumo''s more upright torso reduces lower-back stress relative to conventional''s greater forward lean, and is recommended as the better stance choice for lifters managing lower-back issues.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Tips || How To - Perfect Your DEADLIFT || Proper Form and Common Mistakes'),
('strength-accessories', 'bar path contact', 'Cues keeping the bar in contact with the legs (shins then thighs) for the entire pull, not just off the floor — if the bar drifts away from the body past the knees, torso lean increases, more load shifts to the lower back, and less weight can be lifted.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Tips || How To - Perfect Your DEADLIFT || Proper Form and Common Mistakes'),
('volume-per-muscle', 'deadlift sets per session', 'Treats the deadlift as too taxing to accumulate normal hypertrophy-style set volume in one session — typically only 1-2 hard/near-failure sets per workout, stopping once bar speed/output has dropped more than about 10% from the first rep.', 'practice', 'weak', NULL, '{"hard_sets_per_session": "1-2", "stop_threshold_pct_output_loss": 10}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Tips || How To - Perfect Your DEADLIFT || Proper Form and Common Mistakes'),
('periodization', 'rep scheme progression toward a meet', 'Coaches deadlift progression by starting a training block with high reps (10+ per set) to build muscle/base strength, then lowering reps and increasing weight as a powerlifting meet approaches to peak 1RM strength; cites a longtime client who reached an 800 lb deadlift for 2 reps after years of base work with sets of 10 at 700+ lb.', 'practice', 'weak', NULL, '{"base_phase_reps": "10+", "example_client_peak_lb_x2": 800, "example_client_base_10rm_lb": 700, "coaching_duration_years": 5}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Tips || How To - Perfect Your DEADLIFT || Proper Form and Common Mistakes'),
('tempo', 'touch-and-go vs reset reps', 'For hypertrophy-focused deadlift sets, prefers touch-and-go reps (bar barely touches the floor and immediately reverses) over resetting/pausing each rep, to keep continuous tension and time under tension on the target muscles; for a strength/technique focus (e.g. powerlifting), recommends pausing at lockout and resetting each rep instead.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Tips || How To - Perfect Your DEADLIFT || Proper Form and Common Mistakes'),
('guideline', 'rest period by movement taxation', 'Sets rest periods based on how taxing the movement pattern is rather than a fixed time — a lighter, single-limb exercise (e.g. one-arm row) gets roughly 60-90 seconds between sides, while heavier bilateral compound movements get more; also rests longer after sets taken to absolute failure/beyond than after sets stopped with reps in reserve.', 'practice', 'weak', NULL, '{"unilateral_rest_sec": "60-90"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Ultimate Back And Chest Training For Growth'),
('tempo', 'strict-to-fast tempo shift within a set', 'Runs back/chest sets with strict, controlled form for the bulk of the reps, then shifts into a burst of quicker-tempo reps at the very end of the same set once form starts to break down, treating the tempo change as a deliberate way to extend a set for growth rather than a form failure.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Ultimate Back And Chest Training For Growth'),
('strength-accessories', 'chest press seat/machine setup', 'On chest press machines, sets seat height so the shoulders do not shrug/elevate at the bottom of the rep (flagged as a common setup mistake); to bias upper chest, cues driving the elbows toward each other at the top of the rep rather than changing seat height.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Ultimate Back And Chest Training For Growth'),
('tempo', 'range of motion vs load on machines', 'On chest-press-style machines, chooses a lighter load with a longer range of motion over a heavier load with a short, fast range, reasoning that short-range explosive reps put more stress on the shoulder/elbow joints for a similar training effect.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Ultimate Back And Chest Training For Growth'),
('masters', 'maintenance volume after decades of training', 'After training hard since childhood and now at 47 years old, reports needing noticeably less volume/effort to maintain built muscle than was originally required to build it.', 'opinion', 'weak', NULL, '{"age_years": 47, "training_since_age": 10}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Ultimate Back And Chest Training For Growth'),
('guideline', 'avoid ego-lifting culture', 'Advises against loading up weight to match or impress other lifters in the gym (''gym ego culture'') when the goal is hypertrophy — frames staying within a controlled, appropriately-loaded modality as what allows consistent training without extended injury layoffs.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Ultimate Back And Chest Training For Growth'),
('strength-accessories', 'incline press bench angle for chest emphasis', 'Sets incline dumbbell press at roughly 30 degrees for chest emphasis; demonstrates that raising the incline to roughly 60 degrees shifts the exercise to be much more front-delt/shoulder dominant and pulls it away from chest.', 'practice', 'weak', NULL, '{"chest_bias_incline_deg": 30, "shoulder_bias_incline_deg": 60}'::jsonb, 'Noel Deyzel (physique, technique cues) — 18 Years of Lifting IN 1 CHEST DAY'),
('strength-accessories', 'avoid locking out on presses', 'Cues keeping a slight bend in the elbows at the top of presses (dumbbell and machine) rather than locking out, to keep constant tension on the chest instead of letting the joint/skeleton momentarily take the load.', 'practice', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — 18 Years of Lifting IN 1 CHEST DAY'),
('equipment', 'safely lowering heavy dumbbells after a set', 'For safely finishing a set with heavy dumbbells, brings the dumbbells in to the chest first, then uses a spotter''s gentle assistance to sit up and lower to the knees before setting the weights down, rather than dropping or twisting to place dumbbells on the floor, to reduce risk of dropping them on feet or ankles.', 'practice', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — 18 Years of Lifting IN 1 CHEST DAY'),
('strength-accessories', 'chest press machine dead-zone fix', 'A common chest-press-machine mistake demonstrated: backrest/handle position set so the bottom of the rep has no tension (the lifter ''stops too soon''); the fix is adjusting backrest and handle position so the lifter''s shoulder aligns with the machine and tension stays applied through the full range, with the bar path passing at mid-chest.', 'practice', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — 18 Years of Lifting IN 1 CHEST DAY'),
('volume-per-muscle', 'chest press rep range', 'Programs machine chest press for 8-12 reps per set across 3 sets as the target hypertrophy range, explicitly not failing on every single set within that range, and adjusts weight selection to keep it that way.', 'practice', 'weak', NULL, '{"sets": 3, "reps_low": 8, "reps_high": 12}'::jsonb, 'Noel Deyzel (physique, technique cues) — 18 Years of Lifting IN 1 CHEST DAY'),
('strength-accessories', 'cable fly technique vs turning it into a press', 'Flags a common cable-fly mistake: bending the elbows and pressing instead of arcing (elbows nearly straight, wrists back, chest out); cues an arcing path with hands meeting at mid-chest, and notes raising the hand-meeting point shifts emphasis toward the upper chest.', 'practice', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — 18 Years of Lifting IN 1 CHEST DAY'),
('strength-accessories', 'deficit push-up finisher', 'Uses deficit push-ups (hands elevated on raised dumbbells for extra bottom-range stretch) as an advanced 1-2 set failure finisher; turning the hands to a 45 degree angle on the dumbbells forces the elbows inward and changes the emphasis; explicitly flags this as not appropriate for beginners.', 'practice', 'weak', NULL, '{"finisher_sets": "1-2", "hand_angle_deg": 45}'::jsonb, 'Noel Deyzel (physique, technique cues) — 18 Years of Lifting IN 1 CHEST DAY'),
('tempo', 'contradiction: squat depth and muscle tension', 'Cues stopping squat depth where the thighs are roughly perpendicular to the floor rather than going ''ass to grass,'' reasoning that going below that point lets the lifter rest at the bottom and takes tension off the target muscles. This conflicts with current range-of-motion hypertrophy research, which generally finds deeper squats (below parallel) produce equal or greater quad/glute growth than shallower ones rather than less — a case where an elite practitioner''s cue diverges from the stronger evidence on ROM and hypertrophy.', 'opinion', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — Beginner''s guide to leg day (with exercises)'),
('strength-accessories', 'leg press foot placement', 'On leg press, pushing through the heel emphasizes hamstrings/glutes while pushing through the ball of the foot emphasizes quads; foot placement and angle on the platform is used deliberately to shift where tension is felt.', 'practice', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — Beginner''s guide to leg day (with exercises)'),
('guideline', 'leg day exercise ordering', 'Recommends structuring a beginner leg day in four blocks in this order: heaviest/most technical compound first (e.g. squat), then supported/machine compounds (leg press, hack squat), then isolation work (leg extension, hamstring curl), then calves last.', 'opinion', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — Beginner''s guide to leg day (with exercises)'),
('tempo', 'pause-and-slow-negative for mind-muscle connection', 'For hamstring curls and leg extensions specifically (muscles beginners often struggle to feel), cues a pause at peak contraction plus a slow eccentric, lightening the weight if needed, to build the mind-muscle connection before adding load back.', 'practice', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — Beginner''s guide to leg day (with exercises)'),
('strength-accessories', 'calf raise range of motion over load', 'For calf raises, prioritizes full range of motion over adding weight, flagging cutting ROM short to load more weight as a common mistake; recommends pausing at both the stretch and the contraction and lowering the weight if needed to keep full ROM.', 'practice', 'weak', NULL, NULL, 'Noel Deyzel (physique, technique cues) — Beginner''s guide to leg day (with exercises)'),
('guideline', 'leg day warm-up structure', 'Warm-up structure for leg day: roughly 5-10 minutes of light cardio (stationary bike) to prime the nervous system and blood flow, then roughly 5-10 minutes of dynamic (not static) stretching, then 3-4 warm-up sets of a light compound movement (e.g. squat) for 15-20 reps before working sets.', 'practice', 'weak', NULL, '{"cardio_min": "5-10", "dynamic_stretch_min": "5-10", "warmup_sets": "3-4", "warmup_reps": "15-20"}'::jsonb, 'Noel Deyzel (physique, technique cues) — Beginner''s guide to leg day (with exercises)'),
('volume-per-muscle', 'dedicated arm day for lagging arms', 'For lifters whose arms are a weak point rather than a genetic strength, recommends giving biceps/triceps their own dedicated training day rather than a few sets tacked onto the end of another workout, framing this as necessary to accumulate enough volume to grow them.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow 19in ARMS (Sets & Reps!)'),
('strength-accessories', 'mind-muscle connection as primary set goal', 'Treats mind-muscle connection as the primary determinant of whether an arm set ''counts,'' not exercise choice — will shorten range of motion (full reps to partials), reduce the weight, or change tempo (faster or slower) specifically to improve the felt contraction in biceps/triceps.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow 19in ARMS (Sets & Reps!)'),
('guideline', 'short rest between arm sets', 'Uses minimal rest between arm sets, explicitly shorter than the rest used for back or leg training, reasoning that isolated arm work is less systemically taxing and recovers faster between sets.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow 19in ARMS (Sets & Reps!)'),
('volume-per-muscle', 'high-rep superset arm specialization block', 'Arm specialization structure: pairs exercises as supersets, uses sets of at least 20 reps per exercise (continuing past 20 if still possible), and takes every set to failure, arguing that overtraining the arms this way is hard to actually achieve.', 'opinion', 'weak', NULL, '{"reps_per_set_min": 20}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Grow 19in ARMS (Sets & Reps!)'),
('equipment', 'machines over free-weight big-3 for high-frequency training', 'Replaced squat, bench press, and deadlift with machine equivalents (leg press/extension/curl, chest press, etc.) specifically because training every muscle group to failure 3x/week is too fatiguing to sustain on the free-weight ''big three''; also notes machines make drop sets and partial reps mechanically faster and easier (e.g. pulling a pin vs. stripping plates), which he says matters for training to failure and beyond on a tight schedule.', 'practice', 'weak', NULL, '{"training_frequency_per_muscle_per_week": 3}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Squats Bench And Deadlift Are Killing Your Gains'),
('clinical', 'free-weight big-3 injury risk vs machines', 'Argues squat/bench/deadlift carry materially higher injury risk than machine equivalents, especially when trained to failure or with ego-driven loading; attributes his own current knee, hip, shoulder, and lower-back issues partly to decades of heavy free-weight lifting with imperfect technique (e.g. bouncing the bar off the chest, poor deadlift form in his youth), and has now dropped the big three specifically to preserve long-term training consistency.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Squats Bench And Deadlift Are Killing Your Gains'),
('guideline', 'agonist-antagonist circuit vs long rest between straight sets', 'Switched from resting 5-8 minutes between straight sets (as during his competitive powerlifting years) to agonist-antagonist/circuit-style pairing, so one muscle group recovers while the opposing one is trained, cutting total session time without shortening true per-muscle rest.', 'practice', 'weak', NULL, '{"old_rest_min": "5-8"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Squats Bench And Deadlift Are Killing Your Gains'),
('periodization', 'sequencing cardio before lifting when cardio is the priority', 'When a competing performance goal exists (competitive cycling), does cardio before lifting weights on training days — the reverse of his usual hypertrophy-first advice to lift before cardio — reasoning that maximal effort cannot be brought to both a to-failure compound-lift session and a hard competitive cardio effort on overlapping days, so one goal has to be named the priority for that training block.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Squats Bench And Deadlift Are Killing Your Gains'),
('volume-per-muscle', 'fatigue cost caps big-3 frequency', 'States that the fatigue cost of training squat/bench/deadlift to failure caps how often they can be trained; once his target frequency per muscle rose to 3x/week, this fatigue cost was his stated reason for moving off the free-weight big three entirely rather than just capping their frequency.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Squats Bench And Deadlift Are Killing Your Gains'),
('strength-accessories', 'incline cable curl with partial-rep extension', 'Uses an incline-bench cable curl with an EZ-bar attachment as a preferred bicep exercise because the cable keeps roughly constant tension through the range (unlike a barbell/dumbbell curl); trains it to full-range-of-motion failure (roughly 20-30 reps), then immediately continues into partial reps at the top of the range as an extension of the same set once full reps are no longer possible.', 'practice', 'weak', NULL, '{"reps_to_failure": "20-30"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — ABSOLUTE BEST Science-Based BICEPS Workout'),
('progression', 'ascending-then-descending drop set for curls', 'Runs dumbbell alternating curls as an ascending-then-descending drop set within one exercise block: starts at a lighter weight for 10 reps per side, increases the weight each round until failing to complete 10 reps, then descends back down through the same weight increments to the starting weight.', 'practice', 'weak', NULL, '{"reps_per_round": 10, "starting_weight_lb": 20}'::jsonb, 'Ryan Humiston (physique, exercise selection) — ABSOLUTE BEST Science-Based BICEPS Workout'),
('strength-accessories', 'mechanical drop-set bicep finisher across grips', 'Bicep finisher structured as a mechanical drop set across grip/angle changes within one all-out set: reverse-grip curl to failure, then without resting rotate to a supinated grip for a regular curl to failure, then finish with a drag curl — chaining exercises to keep loading the muscle past each sub-failure point.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — ABSOLUTE BEST Science-Based BICEPS Workout'),
('equipment', 'dumbbell-only leg training viability', 'When dumbbells are too light to match barbell loads, switching to higher reps taken close to failure can substitute for heavier low-rep work and still adequately stimulate the leg muscles; a full dumbbell-only leg session can be a legitimate substitute for a barbell session.', 'opinion', 'weak', NULL, '{"note": "reps flexible (e.g. 10-20) as long as sets are taken close to failure"}'::jsonb, 'Built With Science (Ethier) — The Best Science-Based DUMBBELL Legs Exercises For Size And Symmetry'),
('strength-accessories', 'split squat vs walking lunge for beginners', 'For non-resistance-trained beginners, stationary split squats allow a greater range of motion than walking lunges because balance is easier to maintain, making split squats the better starting lunge variation.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Science-Based DUMBBELL Legs Exercises For Size And Symmetry'),
('strength-accessories', 'narrow stance shifts split squat/lunge emphasis to quads', 'Narrowing the stance and keeping the torso upright during split squats/lunges (so the front knee travels further forward) shifts tension away from the hamstrings/glutes and onto the quads.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Science-Based DUMBBELL Legs Exercises For Size And Symmetry'),
('strength-accessories', 'Bulgarian split squat front-leg loading', 'The forward leg in a Bulgarian split squat (rear foot elevated) supports about 85% of bodyweight versus about 75% in a standard split squat/lunge, with slightly less hamstring activity — making it a good option to emphasize the quads specifically when only light dumbbells are available.', 'opinion', 'weak', NULL, '{"front_leg_load_bulgarian_pct": 85, "front_leg_load_split_squat_pct": 75}'::jsonb, 'Built With Science (Ethier) — The Best Science-Based DUMBBELL Legs Exercises For Size And Symmetry'),
('strength-accessories', 'single-leg RDL pairs with single-leg squat work', 'Pairing a single-leg Romanian deadlift with single-leg squat variations in the same session better isolates and activates the hamstrings than either alone, since the single-leg RDL adds strong hamstring/medial-glute stabilizer demand without needing much load.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Science-Based DUMBBELL Legs Exercises For Size And Symmetry'),
('strength-accessories', 'hip- vs knee-dominant exercises target different hamstring regions', 'Hip-dominant exercises (RDL) emphasize the upper hamstrings while knee-dominant exercises (lying leg curl) emphasize the lower hamstrings, because the short head of the biceps femoris crosses only the knee joint and can only be trained through knee flexion — so both movement types are treated as necessary for complete hamstring development.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Science-Based DUMBBELL Legs Exercises For Size And Symmetry'),
('tempo', 'controlled eccentric on leg curls', 'Controlling and lengthening the eccentric (downward) portion of the lying leg curl is emphasized for both athletic performance and hamstring-injury prevention.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Science-Based DUMBBELL Legs Exercises For Size And Symmetry'),
('periodization', 'rolling 2-on/1-off upper/lower split', 'Uses a continuous ''two days on, one day off'' upper/lower split rather than a fixed weekly split; because the cycle doesn''t align with a 7-day week, each muscle group''s weekly volume fluctuates and gets a periodic increase every third week when the rolling cycle lands 3 sessions in that week instead of 2.', 'practice', 'weak', NULL, '{"note": "upper and lower each trained roughly 2-3x per week depending on where the rolling cycle falls"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('volume-per-muscle', 'splitting weekly volume across two sessions to raise per-set force output', 'Splits total weekly sets per muscle across two separate sessions (e.g. 8 sets + 8 sets) rather than one large session (16 sets), reasoning that maximum force output per set declines across a session, so more of the total sets get done in a fresher state with higher mechanical tension.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('volume', 'contradiction: trains to failure despite citing RIR-equivalence research', 'States he personally always takes sets to failure, while explicitly acknowledging that the research shows training to failure and stopping a few reps shy (RIR-based) produce the same hypertrophy outcome — his stated personal practice conflicts with the equivalence finding he himself cites.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('volume', 'junk volume redefined as sets not taken near failure', 'Doesn''t treat indirect/incidental muscle work (e.g. triceps growth from heavy pressing) as ''junk volume'' — instead defines junk volume as any working set that isn''t taken close to failure, since hitting a fixed rep count without real effort ''wastes'' the set.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('strength-accessories', 'direct front-delt training changed his approach', 'Used to believe front delts didn''t need direct work because pressing hit them enough; after adding direct front-delt work found it was what gave a fuller, more rounded 3D shoulder look by tying the delt into the upper chest — now trains front delts directly every upper session.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('strength-accessories', 'elbows-tucked pressing for anterior delt isolation and shoulder comfort', 'Performs all pressing movements with elbows tucked in rather than flared, reporting more anterior-delt isolation and less shoulder pain than with elbows flared out to the side.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('tempo', 'exercise selection prioritizes deep-stretch loading', 'With limited sets per muscle in this split, selects exercises using two filters: does it allow an exaggerated/deep range of motion, and does it let you load the muscle heavily at long muscle lengths — e.g. prefers a press over a fly for chest because the press allows more load in the stretched position even though a fly may isolate better.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('strength-accessories', 'rear delt technique cue', 'For rear delts, pulls the arms back further than typical with hands turned inward, stopping right before the rear delt stops contracting and the movement ''jumps into the traps.''', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('strength-accessories', 'forearms/abs trained on nominal ''off'' days', 'Trains forearms and abs on what he still calls an off day, reasoning that the systemic fatigue from these is low enough that it doesn''t interfere with recovery from the main upper/lower split.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Science-Backed Workout Split For FASTER Muscle Growth! (My New Favorite)'),
('strength-accessories', 'sternum-angle test sets incline for pressing', 'Recommends testing individual chest-press incline by placing a phone flat against the sternum while lying down: if the phone points straight up the sternum is flat and a low incline (one notch from the bottom) should be used; if it angles back the sternum is steep and a higher incline (two notches from the bottom) should be used.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('strength-accessories', 'press in an ''arrow'' not a ''T'' shape', 'Cues pressing with shoulders tucked into an arrow shape (elbows closer to the torso) rather than flared into a T-shape, citing deeper achievable stretch and lower shoulder-injury risk with the arrow form.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('female', 'claims women tolerate higher reps better than men', 'Claims women have an advantage tolerating higher rep ranges better than men and recommends women default to 10-15 reps on pressing movements even as they advance, whereas men are advised to drop to 6-8 reps as they advance.', 'opinion', 'weak', NULL, '{"recommended_rep_range_women": "10-15", "recommended_rep_range_men_advanced": "6-8"}'::jsonb, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('progression', 'goblet squat load benchmark before moving to barbell', 'Recommends staying on goblet squats until able to perform 10 reps with a dumbbell equal to 50% of bodyweight before progressing to a barbell squat.', 'opinion', 'weak', NULL, '{"goblet_squat_progression_load_pct_bodyweight": 50, "reps": 10}'::jsonb, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('strength-accessories', 'squat foot stance varies by individual hip structure', 'Reports that across trainees, roughly half prefer a stance slightly wider than shoulder width with toes turned out, about a quarter prefer hip-width with toes straight, and the remainder do best going wider still with toes turned out further — recommends testing all three and keeping whichever feels most natural rather than prescribing one stance.', 'practice', 'weak', NULL, '{"note": "~50% prefer moderate-wide stance + toes out, ~25% prefer hip-width + toes forward, remainder prefer wide stance + toes way out"}'::jsonb, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('progression', 'pull-up progression pathway', 'Progresses pull-up-incapable trainees through: inverted rows to sets of 15 reps, then neutral-grip pull-ups (banded/assisted as needed) to sets of 10 unassisted, then overhand-grip pull-ups (expect reps to drop by about half initially) working to 5-8 strict reps, then adds external weight once able to exceed 8 reps, rebuilding to 8 reps before adding more weight each time.', 'opinion', 'weak', NULL, '{"inverted_row_target_reps": 15, "neutral_grip_pullup_target_reps": 10, "overhand_pullup_target_reps_range": "5-8", "add_weight_threshold_reps": 8}'::jsonb, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('guideline', 'pull-up rep standards by level (men)', 'Uses pull-up rep benchmarks: 0-1 reps = beginner, 2-5 = average, 6-12 = fit, 13-20 = advanced, 20+ = elite, with a separate lower scale given for women.', 'opinion', 'weak', NULL, '{"beginner_max": 1, "average_range": "2-5", "fit_range": "6-12", "advanced_range": "13-20", "elite_min": 20}'::jsonb, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('strength-accessories', 'RDL foot stance is more universal than squat stance', 'Unlike the squat, where preferred stance varies a lot by individual, almost everyone performs the RDL best with feet about hip-width and toes forward; recommends finding this stance by jumping and observing where the feet naturally land.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('tempo', 'RDL rep range kept moderate to manage fatigue', 'Prefers 6-10 reps per set on the RDL, avoiding the combination of high reps with heavy load because it is excessively fatiguing on the body.', 'opinion', 'weak', NULL, '{"reps": "6-10"}'::jsonb, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('tempo', 'partial-rep finisher to reach true back-muscle failure', 'After a lat pulldown/row set reaches failure on full reps, adds 3-5 extra partial ''shoulder blade squeeze'' reps at the contracted end range specifically to push the back muscles themselves to failure, since arm/other muscle fatigue otherwise limits the full-ROM set first.', 'opinion', 'weak', NULL, '{"partial_reps": "3-5"}'::jsonb, 'Built With Science (Ethier) — The ONLY Workout You Need For 2026 (Do This 3x/Week)'),
('strength-accessories', 'static lunge chosen over split squat to extend past failure', 'Prefers static (non-alternating) lunges over split squats for taking the quads to true failure, because on a split squat, failure ends the set entirely, whereas on a static lunge the lifter can shift more load onto the trailing leg to keep the working leg going past its own failure point.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get Bigger Legs! (PPL: Sets & Reps)'),
('tempo', 'static lunge cues to prevent cheating the top position', 'Cues avoiding a full lockout/rest at the top of static lunges (switching to a barbell-loaded version if prone to resting there) and avoiding shifting weight onto the back leg early, tilting slightly forward so the working front leg does most of the work.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get Bigger Legs! (PPL: Sets & Reps)'),
('strength-accessories', 'step-ups: same-leg-to-failure, exaggerated stretch, no lockout', 'Performs step-ups by staying on the same working leg to failure rather than alternating legs each rep, drops the trailing leg down off the platform to exaggerate the working leg''s stretch/range of motion regardless of box height, and avoids locking out or resting at the top to keep constant tension.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get Bigger Legs! (PPL: Sets & Reps)'),
('periodization', 'sequences quad-isolation before squats to redirect load onto glutes/hamstrings', 'Deliberately pre-fatigues the quads early in a leg session (leg extensions, static lunges, step-ups) so that by the time low-bar squats and walking lunges are performed, the quads can''t contribute much and the lifter is cued to sit into the bottom and drive through the glutes/hamstrings instead — using exercise order within a single session to redirect emphasis.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get Bigger Legs! (PPL: Sets & Reps)'),
('tempo', 'stiff-leg deadlift stopped short of lockout to protect lower back', 'On dumbbell stiff-leg deadlifts, comes up only about three-quarters of the way rather than to full lockout, to keep tension off the lower back.', 'practice', 'weak', NULL, '{"note": "rises to roughly 75% of full extension, not full lockout"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Get Bigger Legs! (PPL: Sets & Reps)'),
('equipment', 'leg extension viewed as a legitimate staple despite its reputation', 'Considers the leg extension a legitimate exercise he starts every leg day with when a machine is available, pushing back against a stigma among some lifters that it''s risky or ineffective.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get Bigger Legs! (PPL: Sets & Reps)'),
('strength-accessories', 'switched barbell to dumbbell bench press for individual arm path', 'Despite bench-press strength correlating with chest size on average, his own chest stayed underdeveloped on barbell bench because the fixed bar path didn''t match his shoulder structure; switching to dumbbells (free arm path) plus an individualized incline let him grow his chest where the barbell hadn''t.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Massive Chest'),
('tempo', 'deep partial reps in the stretch position for chest growth', 'Adopted a press form with upper arms dropping well below 90 degrees at the bottom and no lockout at the top, deliberately biasing reps toward the deep-stretch portion of the range of motion, on the premise (demonstrated in biceps/quad/calf studies, not yet directly tested on chest at time of filming) that half-reps in the stretch position drive more growth than half-reps at the top.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Massive Chest'),
('progression', 'dropped load substantially to prioritize stretch-focused form, took a year to rebuild', 'Deliberately dropped from 95 lb to 65 lb dumbbells to execute a deep-stretch pressing form correctly, and it took a full year of progressive overload to work back up into the 80s with the new form — treating the form change as a deliberate, extended-timeline reset rather than something to rush back from.', 'practice', 'weak', NULL, '{"starting_load_lb": 95, "reduced_load_lb": 65, "time_to_rebuild": "1 year to reach 80s"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Massive Chest'),
('strength-accessories', 'cable fly setup tweaks for chest-specific tension', 'Sets up a seated cable fly with three tweaks: a half foam roller behind the back to open the chest into a deeper stretch, cables set at shoulder height with the bench scooted forward so tension lines up with mid/lower chest, and keeps the forearms tracking in line with the cable path (not letting them drift) to keep tension off the front delts.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Massive Chest'),
('tempo', 'shoulder creep used as a failure signal on chest fly/press', 'Uses forward rounding of the shoulders (shoulders taking over from the chest) as the signal that true chest failure has been reached on the cable fly, and stops the set there rather than continuing to grind reps with the shoulders.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Massive Chest'),
('tempo', 'pec deck workaround: full reps to failure then stretch-position partials', 'When only a pec deck is available (no adjustable cable fly), recommends taking a set to failure on full reps first, then continuing with half-reps confined to the stretch position to still capture the stretch-emphasis benefit.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Massive Chest'),
('guideline', 'personal protein rule of thumb', 'Uses bodyweight in pounds x 0.8 as his personal daily minimum protein target (grams), treating it as a floor he ensures he hits via a protein source at every meal plus a protein-powder scoop.', 'practice', 'weak', NULL, '{"protein_g_per_lb_bodyweight": 0.8}'::jsonb, 'Built With Science (Ethier) — How to Build Muscle Twice As Fast (ACTUALLY WORKS)'),
('guideline', 'personal calorie rule of thumb for muscle gain', 'Estimates daily calorie needs for muscle gain as bodyweight in pounds x 16-18 depending on activity level, used as a rough starting point rather than a precise target.', 'practice', 'weak', NULL, '{"kcal_per_lb_bodyweight_range": "16-18"}'::jsonb, 'Built With Science (Ethier) — How to Build Muscle Twice As Fast (ACTUALLY WORKS)'),
('volume-per-muscle', 'raised chest volume specifically after cutting volume elsewhere', 'His own chronically stubborn chest only started growing once he reduced training volume for other muscle groups and raised chest-specific volume to about 16-20 sets/week — illustrating that the useful volume ceiling for a lagging muscle can be higher than a generic starting recommendation, and may require cutting volume elsewhere to afford the recovery cost.', 'practice', 'weak', NULL, '{"chest_weekly_sets_range": "16-20"}'::jsonb, 'Built With Science (Ethier) — How to Build Muscle Twice As Fast (ACTUALLY WORKS)'),
('volume', 'adapts proximity-to-failure vs set count based on client adherence', 'Coaches lower-adherence or less gym-tolerant clients (cites his fiancée) with fewer total sets taken all the way to failure rather than higher volume at moderate effort, as a way to get comparable results with less time in the gym.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Build Muscle Twice As Fast (ACTUALLY WORKS)'),
('volume', 'combining high volume and near-failure training broke down his own recovery within weeks', 'Personally tried combining both high training volume and taking most sets to true failure simultaneously; within a few weeks his body ''broke down'' and he couldn''t recover, illustrating that volume and proximity-to-failure trade off against a personal recovery ceiling rather than stacking freely.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Build Muscle Twice As Fast (ACTUALLY WORKS)'),
('tempo', 'mind-muscle connection cue example', 'Cues mind-muscle connection on the dumbbell chest press by thinking ''pull the arms together, drive the biceps into the chest'' on every rep rather than just moving the weight from point A to point B.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Build Muscle Twice As Fast (ACTUALLY WORKS)'),
('volume-per-muscle', 'calf training frequency', 'Trains calves before every upper-body session, resulting in calf work 4-5 days per week; calls this excessive by normal standards but reports it has worked for him.', 'practice', 'weak', NULL, '{"frequency_days_per_week": "4-5"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('strength-accessories', 'calf head bias via foot position', 'Alternates foot position (toes in vs toes out) between calf-training sessions to selectively bias the lateral vs medial gastrocnemius head, switching which head is targeted each session.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('strength-accessories', 'pre-chest warm-up targets mid/lower traps', 'Before chest training, warms up by engaging mid and lower traps (band pull-apart/scapular-retraction work) rather than only mobilizing the shoulders, so the traps can actively pull the shoulder blades back and down during pressing sets.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('tempo', 'stretch-under-load as primary chest growth driver', 'States the single most important factor for chest growth is maximizing length under load (a deep stretch through the eccentric) rather than a strong top-end squeeze; changed his elbow angle and pressing setup specifically to preserve pec tension through the stretch instead of chasing peak contraction.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('strength-accessories', 'pressing setup cue to protect pecs from anterior delt takeover', 'Uses a consistent pre-rep setup on every pressing movement — pinch shoulder blades back and down, flatten the back fully against the bench/pad, then pull the elbows back and flare them through the eccentric — to keep tension on the pecs and off the anterior delt.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('progression', 'proximity to failure valued over rep range', 'Varies rep ranges freely between sets on the same exercise (e.g. 10, 8, 8, 6, then 20) and states rep range itself doesn''t matter; the variable he holds constant for progress is training each set to true failure.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('smith', 'Smith machine bias for chest stretch/tension', 'Credits the Smith machine''s fixed bar path as a key reason his chest finally developed, because removing the need to balance/stabilize the bar lets him focus purely on pulling the elbows back and stretching the chest through the eccentric. Independently echoed by Will Tennyson (same batch), who says Smith-machine pressing lets him grind out more reps and more time under tension than free weights.', 'practice', 'moderate', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('tempo', 'loaded inter-set stretching to reduce set volume', 'Self-testing a protocol where each set ends with a 20-30 second loaded stretch in place of some rest time, on the hypothesis that the added time-under-tension from stretching lets him cut total set volume while keeping results similar; explicitly describes this as an untested, anecdotal experiment on himself, not an established practice.', 'practice', 'weak', NULL, '{"stretch_duration_seconds": "20-30"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Grow a BIGGER Chest (FULL WORKOUT!)'),
('strength-accessories', 'lower-lat bias in pulldowns', 'To bias the lower lats over the upper back/biceps on pulldowns, uses a shoulder-width neutral (or underhand) grip, keeps the elbows tucked tight to the torso throughout, and pulls by driving the elbows in a slight arc down toward the hips rather than pulling the bar straight down; says this fixed years of poor personal lat development.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Back (3 Exercises)'),
('strength-accessories', 'upper-lat bias in rows', 'To bias the upper lats on cable or dumbbell rows, uses a shoulder-width neutral grip, leans the torso forward slightly for a longer stretch, and keeps the forearm close to vertical while pulling the elbow down toward the hip, arguing that more upward forearm bend shifts the work into the biceps.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Back (3 Exercises)'),
('strength-accessories', 'wide grip for mid/upper-back thickness', 'For targeting traps, rhomboids and rear delts (back thickness) rather than the lats, uses a wide overhand grip (wider than shoulder width) on a cable row, leans back slightly, and pulls with the elbows flared out to the sides instead of tucked.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Back (3 Exercises)'),
('tempo', 'continuing sets with partial reps at end-range stretch', 'Once unable to complete full reps on lat pulldowns/rows, continues the set with half-reps performed only in the top stretched position rather than stopping, reasoning most of the growth stimulus in these lifts comes from the lengthened portion of the rep. Independently echoed by Will Tennyson''s comment (same batch) that the stretch at the top of the lat pulldown matters as much as the elbow path.', 'opinion', 'moderate', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Back (3 Exercises)'),
('strength-accessories', 'mechanical drop-set for traps', 'On a wide-grip row aimed at the traps, extends the set past full-rep and half-rep failure with a final phase of pure scapular-retraction reps (arms held straight, only opening and squeezing the shoulder blades) until the weight can no longer be moved at all.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Back (3 Exercises)'),
('guideline', 'back muscles need deliberately biased setups, not just more back exercises', 'Argues that because the back has many muscles of differing strength, a standard row or pulldown defaults to being dominated by the strongest/most-trained muscles (e.g. biceps, traps) unless grip, torso angle and pull path are deliberately set to bias the intended target muscle.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Back (3 Exercises)'),
('volume-per-muscle', 'contradiction: weekly glute set volume vs standard volume-landmark guidance', 'Bret Contreras recommends 36 hard sets of glute work per week, explicitly stating this exceeds what he characterizes as published research guidance (~20 sets/week), justifying the higher number by what he says top bikini/physique competitors and his best-responding clients actually do. This conflicts with the corpus''s strong-confidence volume-landmark guidance of roughly 10-20 sets per muscle per week for most lifters.', 'opinion', 'weak', NULL, '{"recommended_sets_per_week": 36, "note": "compared by the speaker against ~20 sets/week, which he attributes to published research"}'::jsonb, 'Built With Science (Ethier) — How to Get a Rounder Butt FAST (ft. Bret Contreras)'),
('volume-per-muscle', 'glute training frequency', 'Recommends training glutes 3x/week on an upper-lower-upper-lower-upper split (lower-body days sandwiching upper days) specifically to spread a high weekly glute volume across enough sessions to recover from it.', 'opinion', 'weak', NULL, '{"frequency_days_per_week": 3}'::jsonb, 'Built With Science (Ethier) — How to Get a Rounder Butt FAST (ft. Bret Contreras)'),
('strength-accessories', 'three-category glute exercise split', 'Splits glute volume into three exercise categories trained with different rep ranges: vertical hip extension (squats, split squats, lunges) at 6-12 reps, horizontal hip extension (hip thrusts, back extensions) at 8-20 reps, and hip abduction work at 12-30 reps — reasoning that vertical hip extension is most taxing and biases the lower glutes, horizontal hip extension hits upper and lower glutes with less fatigue cost, and abduction is least taxing and targets the glute medius.', 'opinion', 'weak', NULL, '{"vertical_hip_extension_sets_per_week": 12, "vertical_hip_extension_reps": "6-12", "horizontal_hip_extension_sets_per_week": 12, "horizontal_hip_extension_reps": "8-20", "abduction_sets_per_week": 12, "abduction_reps": "12-30"}'::jsonb, 'Built With Science (Ethier) — How to Get a Rounder Butt FAST (ft. Bret Contreras)'),
('strength-accessories', 'hip thrust top-position cue', 'Coaches the hip thrust so that at the top of the rep the shins are vertical (adjusting foot placement in or out until this is achieved), and holds the top position for 3 seconds before lowering.', 'practice', 'weak', NULL, '{"top_hold_seconds": 3}'::jsonb, 'Built With Science (Ethier) — How to Get a Rounder Butt FAST (ft. Bret Contreras)'),
('strength-accessories', 'torso lean and shin angle to bias glutes in squat-pattern lifts', 'For Bulgarian split squats and Smith machine reverse lunges, cues a forward torso lean to shift emphasis onto the glutes; for Romanian deadlifts, cues vertical shins with the hips sitting back so the glutes drive hip extension rather than the hamstrings/quads.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Get a Rounder Butt FAST (ft. Bret Contreras)'),
('periodization', '3-week wave block for pause bench press', 'Runs pause bench press in 3-week blocks with decreasing reps and increasing load each week (3x8, then 4x6, then 5x5), adding a fixed amount of weight each week within the block.', 'practice', 'weak', NULL, '{"week1_sets_reps": "3x8", "week2_sets_reps": "4x6", "week3_sets_reps": "5x5", "weekly_load_increase_lb": 5}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Bulking Diet & Training Routine'),
('periodization', 'top-set-plus-backoff wave for overhead press', 'Runs overhead press on a 3-week wave: week 1 a top set of 5 followed by 3 backoff sets of 10 at roughly 20-25% less weight; week 2 a top set of 3 plus 3x8; week 3 a heavy single at a training max (not a true 1RM attempt) plus 3x6.', 'practice', 'weak', NULL, '{"week1": "top set of 5 + 3x10 backoff at -20 to -25%", "week2": "top set of 3 + 3x8", "week3": "heavy single (training max) + 3x6"}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Bulking Diet & Training Routine'),
('volume', 'fewer, harder sets over total volume', 'Trains chest and back with only about 7 hard sets each, twice a week, distinguishing ''effective volume'' from total set count and stating that keeping a small number of sets close to true failure produced better size and recovery than doing more sets. Echoes Ryan Humiston''s emphasis (same batch) on proximity to failure over rep count/total volume.', 'practice', 'moderate', NULL, '{"hard_sets_per_muscle": 7, "frequency_per_week": 2}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Bulking Diet & Training Routine'),
('tempo', 'full stretch at top of lat pulldown/row matters', 'On chest-supported dumbbell rows and lat pulldowns, emphasizes reaching a full stretch at the top of the rep rather than half-repping, stating the stretch matters as much as pulling the elbows back. Independently echoed by Jeremy Ethier''s back-workout video (same batch), which specifically trains the lengthened/stretched position of pulldowns and rows past normal failure.', 'practice', 'moderate', NULL, NULL, 'Will Tennyson (experiments, self-testing) — My Bulking Diet & Training Routine'),
('smith', 'Smith machine for higher-rep, longer time-under-tension chest work', 'Prefers doing chest pressing movements on the Smith machine because the fixed path lets him grind out more reps and more time under tension than free weights allow. Independently echoed by Ryan Humiston (same batch), who credits the Smith machine''s fixed path for his own chest development.', 'practice', 'moderate', NULL, NULL, 'Will Tennyson (experiments, self-testing) — My Bulking Diet & Training Routine'),
('strength-accessories', 'posing cue for arm mind-muscle connection', 'Uses a cue picked up from IFBB pro Phil Heath — mentally flexing/posing on every rep of single-arm cable curls — as a mind-muscle-connection technique for arm training.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — My Bulking Diet & Training Routine'),
('guideline', 'longer warm-ups for stronger (enhanced) lifters', 'Argues lifters who are meaningfully stronger than natural baseline need longer, more gradual warm-ups because muscular strength can outpace tendon/connective-tissue strength, raising injury risk if load is added too quickly; recommends warming up on the actual lift itself with small graduated jumps rather than jumping straight to heavy plates.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Natural vs Enhanced || How To Maximize Muscle Growth'),
('guideline', 'moderate rep range as injury-risk compromise for stronger lifters', 'Recommends stronger/enhanced lifters avoid both very-low-rep max-effort sets (highest injury risk under heavy absolute load) and very-high-rep sets (which he says become disproportionately brutal once drug-driven pump/metabolite buildup is added), suggesting roughly 12-15 reps as a middle-ground compromise.', 'opinion', 'weak', NULL, '{"recommended_rep_range": "12-15"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Natural vs Enhanced || How To Maximize Muscle Growth'),
('tempo', 'controlled/paused reps to reduce injury risk', 'States that once he began using PEDs he stopped doing touch-and-go bench reps and instead always paused the bar briefly at the bottom, reasoning that avoiding the stretch-reflex bounce off the chest reduces injury risk under heavier loads while also adding time under tension.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Natural vs Enhanced || How To Maximize Muscle Growth'),
('guideline', 'deloads are still required regardless of PED use', 'Pushes back on the idea that being on PEDs removes the need for deloads, arguing that soreness, injury and burnout still require backing off training regardless of enhancement status, and that recovery timing should follow individual fatigue signals rather than drug status.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Natural vs Enhanced || How To Maximize Muscle Growth'),
('clinical', 'active contraction, not passive input, reverses sitting-induced back stiffness', 'Cites a study in which prolonged sitting caused back stiffness; a group given only a low-level (non-contracting) electrical stimulus stiffened up the same as an untreated control, while only the group whose back muscles were made to actively contract saw the stiffness largely reverse — used to argue the fix for sitting-related stiffness is actively moving/contracting the underused muscles, not passive stretching or input alone.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The PERFECT Mobility Routine to FIX YOUR SIT (3 Min/Day)'),
('strength-accessories', 'low-to-high row elbow angle for mid-back', 'Ethier cues a low-to-high cable/lat-pulldown-bar row with elbows angled out to roughly 45 degrees (an ''arrow'' shape) to bias mid-traps, rhomboids and teres, versus a lat-focused row done with elbows tucked to the sides.', 'practice', 'weak', NULL, '{"elbow_angle_deg": 45}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Thicker Back'),
('strength-accessories', 'grip choice for low-to-high row', 'Ethier prefers a wide grip on a lat-pulldown bar over a V-grip handle for cable rows, because the V-grip doesn''t let the elbows angle outward and is uncomfortable on the wrist at end range.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Thicker Back'),
('strength-accessories', 'scapular retraction cue to avoid ''arm pulling''', 'Ethier''s fix for rowing with the arms instead of the back: let the shoulder blades open up fully at the start of each rep, initiate the pull by driving the elbows back and out, and watch the shoulders actively move backward through the rep. Cues ''pull your chest to the bar'' instead of ''pull the bar to your chest,'' likening the motion to a breaststroke.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Thicker Back'),
('strength-accessories', 'incline bench row as cable-row substitute', 'Ethier replicates the low-to-high cable row with dumbbells by lying chest-down on a bench set to about 30 degrees, keeping the forearms directly under the elbows so the arms don''t take over the pull.', 'practice', 'weak', NULL, '{"bench_angle_deg": 30}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Thicker Back'),
('strength-accessories', 'steeper bench angle shifts row toward rear delts/upper traps', 'For rear-delt and upper-trap emphasis (scapular elevation) instead of retraction, Ethier uses the same chest-supported dumbbell row setup but raises the bench to about 60 degrees and flares the elbows wider, describing the motion as close to a reverse dip.', 'practice', 'weak', NULL, '{"bench_angle_deg": 60}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Thicker Back'),
('tempo', 'partial-rep finisher after row failure', 'Ethier finishes rowing sets by continuing past full-rep failure with elbows-straight partials, isolating just the scapular retraction (or just the shrug/elevation on the upper-back variant) for a further 4-5 reps. He does this after every set himself, and suggests beginners start by applying it only on their last set.', 'practice', 'weak', NULL, '{"note": "4-5 extra partial reps after full-rep failure, done every set"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Thicker Back'),
('volume-per-muscle', 'back-thickness dosing', 'Ethier''s stated dose for the two back-thickness rows he recommends is 3-4 sets of 8-12 reps, once or twice per week.', 'practice', 'weak', NULL, '{"sets": "3-4", "reps": "8-12", "frequency_per_week": "1-2"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Thicker Back'),
('strength-accessories', 'deadlift downgraded as a back-builder', 'Doucette rates the deadlift only a B for back development despite calling it a great total-body strength exercise: it doesn''t isolate the back well, is hard on many lifters'' lower backs, and competes with leg-day fatigue/recovery, so he doesn''t consider it essential in a back-focused session.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'chest-supported row as the must-do back exercise', 'Doucette rates any chest-supported row (T-bar or machine, any grip) S-tier and calls it a ''must include'' exercise: it lets him load heavy and progressively overload with a deep stretch and squeeze without stressing his lower back. He pairs it with a lat pulldown as the two exercises he does every back session.', 'practice', 'weak', NULL, '{"note": "does a chest-supported row + a lat pulldown variant every back workout"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'bilateral rows preferred over unilateral (one-arm) rows', 'Doucette consistently rates one-arm/unilateral row variants (half-kneeling one-arm pulldown, cross-body pulldown, Meadows row) lower than bilateral versions, even when he agrees the exercise itself is effective, because training one side at a time takes roughly twice as long, is harder to stabilize, and is less sustainable to stick to. He says he won''t do these every workout for that reason.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'wide-grip lat pulldown as a daily back-day staple', 'Doucette rates the wide-grip lat pulldown S-tier and says he performs it every single session he trains back, arguing machine pulldowns are easier to control and load consistently, tired or fresh, than bodyweight pull-ups.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'pull-up progression is a barrier for most lifters', 'Doucette notes wide/neutral-grip pull-ups are high quality but hard to progressively overload for most people since many can''t yet do a full set of 10-12 reps; he says he could only do 6 when he started.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'supinated grip biases biceps over lats', 'Doucette rates the supinated/chin-up grip lower than wide or neutral grip for back-focused pulldowns and pull-ups, arguing it shifts emphasis toward the biceps rather than the lats for many lifters.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'barbell and Pendlay rows downgraded for lower-back stress', 'Doucette rates the standard barbell row and standard Pendlay row only B/C tier, citing the high lower-back loading of a bent-over position as heavier weight is used; he attributes part of this to his own L4-L5 disc history but frames it as a general concern for back-pained lifters.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'Yates row downgraded for ego-lifting risk', 'Doucette rates the Yates row C-tier, arguing it''s too easy to ego-lift on: lifters load it heavy with loose technique that ends up looking more like a shrug than a row.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'deficit Pendlay row gives a deeper stretch', 'Doucette rates the deficit Pendlay row (standing on a raised platform) a tier above the standard Pendlay row because the added range of motion gives a deeper stretch, while noting it carries the same lower-back loading concern.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'one-arm dumbbell row limited by available dumbbell weight', 'Doucette says one-arm dumbbell rows become hard to progressively overload for very strong lifters because many gyms don''t stock dumbbells heavier than 100 lb, and heavy one-arm rows get difficult to stabilize and are harder on the lower back once loaded up.', 'opinion', 'weak', NULL, '{"note": "gym dumbbell racks commonly top out around 100 lb"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('tempo', 'lying face-down face pulls preferred over standing', 'Doucette rates standing face pulls only B because leaning back to counterbalance the cable is hard to stabilize for strong lifters, but rates the lying face-down face pull A: with no balance compensation needed he can control the weight, pause at the bottom, and use higher reps without needing to go heavy.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'cable straight-arm pullover as a light, high-rep finisher', 'Doucette does a cable lat pullover/straight-arm pulldown near the end of almost every back session, deliberately keeping the weight light and reps at 12 or more, treating it as a stretch-and-squeeze finisher rather than a primary loading exercise.', 'practice', 'weak', NULL, '{"reps_min": 12}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'cable pullover preferred over dumbbell pullover', 'Doucette prefers the cable version of the lat pullover to the dumbbell/bench version, saying the dumbbell version is less comfortable on his shoulders and loses tension at the top of the rep, while the cable keeps tension through the full range.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Best Back Exercises Experience Vs Science'),
('strength-accessories', 'narrow stance for glute-focused deadlift', 'Ethier uses a hip-width (not sumo) stance for glute-focused deadlifts, arguing a wider sumo stance shortens the range of motion and limits how far the glutes have to push the hips forward to complete the lift.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Glutes Workout To Grow Your Flat Butt (GYM OR HOME!)'),
('strength-accessories', 'pre-tension cue before the deadlift pull', 'Before initiating a glute-focused deadlift, Ethier cues squeezing the glutes hard and pushing the knees out against the elbows to ''turn on'' the glutes before driving the weight up.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Glutes Workout To Grow Your Flat Butt (GYM OR HOME!)'),
('strength-accessories', 'push-the-floor cue over pull-the-bar on deadlift', 'Ethier cues thinking about pushing the floor away and driving the hips forward, rather than pulling the bar up, to keep the glutes rather than the lower back doing the work of a deadlift.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Glutes Workout To Grow Your Flat Butt (GYM OR HOME!)'),
('tempo', 'deadlift descent range limited by lower-back rounding', 'On the eccentric of a glute-focused deadlift, Ethier cues pushing the hips back only as far as possible before the lower back starts to round, since going further shifts tension from the glutes to the lower back.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Glutes Workout To Grow Your Flat Butt (GYM OR HOME!)'),
('strength-accessories', 'walking lunge tweaks for glute bias', 'Ethier modifies walking lunges for more glute (less quad) involvement with three tweaks: lean the torso slightly forward while lunging, cue ''stepping forward through'' rather than ''stepping up,'' and at the bottom of each lunge manually push the front knee inward against your own hand resistance, then drive the knee back out against that resistance as you stand.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Glutes Workout To Grow Your Flat Butt (GYM OR HOME!)'),
('strength-accessories', 'glute medius superset with no rest between movements', 'Ethier pairs a slow, controlled cable/band hip-abduction ''heel sweep'' (heel swept back and roughly 30 degrees out to the side) with an elevated rear-foot-elevated split squat (about 80% of bodyweight on the front leg) as a superset with zero rest between the two exercises, for 3 rounds per leg, to target the glute medius.', 'practice', 'weak', NULL, '{"abduction_angle_deg": 30, "front_leg_weight_pct": 80, "rounds_per_leg": 3}'::jsonb, 'Built With Science (Ethier) — The Best Glutes Workout To Grow Your Flat Butt (GYM OR HOME!)'),
('tempo', 'top-contraction cue for hip extension/thrust', 'For 45-degree hip extensions or floor glute bridges, Ethier cues visualizing two points on each glute cheek at the top and bottom and squeezing them together to maximize the peak contraction, crediting the cue to glute researcher Bret Contreras.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Best Glutes Workout To Grow Your Flat Butt (GYM OR HOME!)'),
('strength-accessories', 'exercise selection biased toward stretched-position overload', 'Ethier says he deliberately picked exercises that challenge each muscle most in a lengthened/stretched position when his gains stalled — preacher curls and behind-the-body curls for biceps, overhead extensions for triceps, behind-the-body cable lateral raises for shoulders, seated leg curls for hamstrings, and Bulgarian split squats for glutes.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How I Built Muscle FAST (5 Science-Based Tips)'),
('tempo', 'reduced load to protect range of motion, added a pause', 'Ethier lightened the weight on almost all his lifts by about 10-20% so he could go as deep as possible with strict form, and added a half-second pause at the bottom on presses and squats, stating this mattered more for his renewed growth than exercise selection alone.', 'practice', 'weak', NULL, '{"load_reduction_pct": "10-20", "pause_sec": 0.5}'::jsonb, 'Built With Science (Ethier) — How I Built Muscle FAST (5 Science-Based Tips)'),
('volume', 'cut weekly training days after upping set intensity', 'Ethier reports he used to train 6, sometimes 7, days a week, but after starting to train much closer to failure he found that too much: he cut down to 5 days, then later to 4 longer sessions per week plus an occasional accessory day, and felt better recovered and more energized as a result.', 'practice', 'weak', NULL, '{"days_before": "6-7", "days_after": 4}'::jsonb, 'Built With Science (Ethier) — How I Built Muscle FAST (5 Science-Based Tips)'),
('progression', 'trained closer to true failure than he had been', 'Ethier says he had gotten comfortable stopping sets several reps short of failure without realizing it, and that renewed growth only came once he started deliberately pushing sets to within about 1-2 reps of true failure.', 'practice', 'weak', NULL, '{"target_rir": "1-2"}'::jsonb, 'Built With Science (Ethier) — How I Built Muscle FAST (5 Science-Based Tips)'),
('volume-per-muscle', 'Cutler trained each body part once every 5-7 days at very high per-session volume', 'Jay Cutler describes himself as a high-volume trainer during his competitive peak: roughly 20+ sets per body part, hit once every 5-7 days rather than twice a week, on the belief that a muscle needs about 72 hours before it should be trained again.', 'practice', 'weak', NULL, '{"sets_per_bodypart": "20+", "frequency_days": "5-7", "believed_recovery_hours": 72}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Jay Cutler On Training Frequency And Intensity'),
('volume-per-muscle', 'contrast: Coleman and Heath trained twice weekly at lower per-session volume', 'Cutler says training partners Ronnie Coleman and Phil Heath instead trained each body part twice a week doing about 9-12 sets per session (roughly 18-24 sets/week total), versus his own once-every-5-to-7-days high-volume approach — both frequency strategies coexisted among elite, enhanced competitors of the same era.', 'practice', 'weak', NULL, '{"sets_per_session": "9-12", "frequency_per_week": 2}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Jay Cutler On Training Frequency And Intensity'),
('volume-per-muscle', 'contradiction: recommends once-weekly per-muscle frequency for average/intermediate lifters', 'Asked what an average, non-enhanced intermediate trainee should do, Cutler recommends training each body part once per week rather than twice, explicitly reserving twice-weekly frequency for those chasing pro-level growth. This conflicts with our corpus''s higher-confidence finding that training a muscle roughly twice a week (volume matched) tends to produce equal or better hypertrophy than once-weekly ''bro split'' training.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Jay Cutler On Training Frequency And Intensity'),
('periodization', 'split groups hardest body parts before a rest day', 'Cutler structures his week as two days on, one day off, and deliberately schedules his rest day right after training back and after training legs, because he considers those his hardest-recovering body parts. His day split: back, legs, shoulders+triceps, chest+biceps.', 'practice', 'weak', NULL, '{"note": "2 days on / 1 day off cycle, rest day placed after back day and after leg day"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Jay Cutler On Training Frequency And Intensity'),
('guideline', 'very short inter-set rest even on heavy compound lifts', 'Cutler used only 45-60 seconds rest between sets even on heavy compound lifts (400-500+ lb squats, deadlifts, barbell rows, T-bar rows), which he credits for his cardiovascular conditioning and ability to stay lean without dedicated cardio. He contrasts this with Doucette''s own powerlifting-background habit of resting 5-6 minutes between sets — the same two speakers reporting opposite habitual rest-period norms for hypertrophy-oriented vs. strength-oriented training.', 'practice', 'weak', NULL, '{"rest_sec": "45-60", "contrast_rest_min": "5-6"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Jay Cutler On Training Frequency And Intensity'),
('guideline', 'never trains below an 8-rep floor', 'Cutler says he never used loads he couldn''t lift for at least 8 reps (''if I couldn''t do it eight times, I didn''t touch it''), preferring higher reps with heavy weight (e.g. around 20 reps with 500 lb on deadlift) over low-rep near-maximal singles, in explicit contrast to a powerlifting rep philosophy.', 'practice', 'weak', NULL, '{"min_reps": 8}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Jay Cutler On Training Frequency And Intensity'),
('volume-per-muscle', 'post-competitive current practice: full-body 3x/week', 'Cutler says that now that he''s focused on cycling rather than bodybuilding competition, he trains his whole body three times a week rather than using a body-part split, since he''s no longer chasing maximal muscle size.', 'practice', 'weak', NULL, '{"frequency_per_week": 3}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Jay Cutler On Training Frequency And Intensity'),
('tempo', 'full stretch at bottom position, no bouncing', 'Ethier recommends taking every exercise to a full stretch at the bottom (bench to the chest, full arm extension on curls, squat to at least parallel or below, dumbbells over barbells for deeper stretch) and controlling the weight down under tension rather than bouncing or cheating out of the bottom, treating the deep-stretch portion as the most important part of the rep for growth.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How To Build Muscle Almost 2x Faster (NEW RESEARCH)'),
('strength-accessories', 'exercise selection for stretch on biarticulate muscles', 'For muscles that cross two joints (hamstrings, triceps, biceps, glutes), Ethier recommends specifically choosing the variation that stretches the muscle furthest: seated leg curl over lying leg curl for hamstrings, overhead cable/rope extensions over pushdowns for triceps, incline or behind-the-body cable curls for the biceps long head, and RDLs/squats/split squats for glutes.', 'opinion', 'weak', NULL, '{"note": "applies specifically to bi-articulate muscles, not all muscle groups"}'::jsonb, 'Built With Science (Ethier) — How To Build Muscle Almost 2x Faster (NEW RESEARCH)'),
('tempo', 'length partials technique after failure', 'Ethier''s own technique, ''length partials'': on a safe isolation exercise (dumbbell press, flyes, leg extension, triceps extension, biceps curl), once full-ROM reps are exhausted, continue the set with half reps at the bottom stretched position until failure. He avoids this on big compounds (squat, deadlift, overhead press) and uses it sparingly, e.g. only on the last set of an exercise, because it is very fatiguing.', 'practice', 'weak', NULL, '{"note": "isolation exercises only, typically last set only, avoid on squats/deadlifts/overhead press"}'::jsonb, 'Built With Science (Ethier) — How To Build Muscle Almost 2x Faster (NEW RESEARCH)'),
('tempo', 'extended time-under-tension leg training style', 'Doucette trains legs with very long sets (roughly 1.5-3 minutes each) built from continuous tension and rest-pauses rather than heavy low-rep sets, going by feel instead of tracking absolute load. He switched to this style over the past 2-3 years after mixing it with heavier strength work previously, and reports it drove his best growth and also raises his heart rate enough to double as cardio.', 'practice', 'weak', NULL, '{"set_duration_minutes": "1.5-3", "note": "leg training specifically; does not track load, decides weight increases by feel"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow'),
('volume-per-muscle', 'isolated hamstring work added on quad-focused day', 'Doucette trains legs twice a week with one quad-focused day (heavier compounds) and one posterior/hamstring-focused day, but adds isolated hamstring exercises (seated leg curls, GHDs) even on the quad-focused day because hamstrings are a stubborn weak point for him specifically.', 'practice', 'weak', NULL, '{"leg_sessions_per_week": 2, "note": "quad day = Tuesday, posterior/hamstring day = Saturday, per his own schedule"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow'),
('strength-accessories', 'squat/leg-press depth prioritized over weight to maximize quad stretch', 'Doucette pushes for maximum comfortable squat/leg-press depth (limited by his own hip mobility, not by bottoming out against a hard stop) to maximize knee flexion and quad stretch, saying a rigid bottom stop decompresses tension and forces a jarring reload that he dislikes; he prefers constant tension through the full range.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow'),
('tempo', 'lean-forward hamstring curl for extra stretch', 'On seated hamstring curl machines, Doucette leans his torso forward during the rep (similar to a toe-touch stretch) to get more stretch on the hamstrings at the top of the movement, while keeping tension in the stretched position rather than letting the leg fully top out.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow'),
('volume-per-muscle', 'higher frequency/volume for calves than other muscle groups', 'Doucette trains calves with higher volume and frequency and long time-under-tension/peak-contraction squeezes rather than heavy low reps, reasoning that calves recover faster than muscles like the chest because they are already loaded daily by walking.', 'opinion', 'weak', NULL, '{"note": "reasoning: daily-use muscles (calves) tolerate more frequency/volume than muscles used only in training, e.g. chest"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow'),
('guideline', 'rest days placed immediately after hardest training day', 'Doucette takes exactly two full rest days per week, deliberately placed the day after each leg session (rests Wednesday after Tuesday leg day, Sunday after Saturday leg day) rather than spread evenly through the week.', 'practice', 'weak', NULL, '{"rest_days_per_week": 2}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow'),
('guideline', 'contradiction: combining cardio with resistance training in one session', 'Doucette does his cardio embedded within long-rest-period leg training (sustained elevated heart rate through slow, long sets) rather than as a separate session, explicitly stating ''the science will say separate your cardio and your workout'' but choosing not to, for time efficiency, since he will not go to the gym twice in a day.', 'practice', 'weak', NULL, '{"note": "he acknowledges this conflicts with standard advice to separate cardio from resistance training; framed as a personal time-efficiency tradeoff, estimated by him as only a small (~5%) disadvantage"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow'),
('strength-accessories', 'step-down preferred over lunges/squats/deadlifts for glute isolation', 'Bret Contreras (interviewed by Ethier) recommends the ''glute-focus step-down'' (single-leg step down off a platform, torso hinged forward, back leg trailing free) over walking lunges, reverse lunges, squats, and deadlifts for glute-specific growth, because those compound exercises let quads, lower back, or grip fail before the glutes do, and produce excessive next-day soreness (especially Bulgarian split squats) that limits how often glutes can be trained.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need to Fix Your Flat Butt'),
('volume-per-muscle', 'glute training frequency recommendation', 'Contreras recommends training glutes at least twice a week, up to three times a week if tolerated, in part because the low-soreness step-down allows more frequent glute-focused sessions than exercises like Bulgarian split squats.', 'practice', 'weak', NULL, '{"sets": "3", "reps": "8-12", "frequency_per_week": "2-3"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need to Fix Your Flat Butt'),
('strength-accessories', 'pairing a stretch-focused and a squeeze-focused exercise per muscle', 'Ethier and Contreras report that combining one stretch-focused exercise (e.g. the step-down, which challenges the glutes at the bottom stretched position and may bias the lower glutes) with one squeeze-focused exercise (the hip thrust, which challenges the glutes at end-range hip extension and may bias the upper glutes) produced the best overall glute development in their own testing.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need to Fix Your Flat Butt'),
('tempo', 'hip thrust foot placement determines quad vs hamstring emphasis', 'Contreras/Ethier''s hip thrust setup cues: upper back high on the bench for stability, and feet placed so the knees sit directly over the feet at the top of the rep; feet placed too close shifts emphasis toward the quads, feet placed too far away shifts emphasis toward the hamstrings.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need to Fix Your Flat Butt'),
('strength-accessories', 'scoop hip thrust variation for glute isolation and back-pain relief', 'Contreras''s ''scoop method'' hip thrust (chin tucked, eyes forward, let the lower back arch at the bottom, then posteriorly tilt the pelvis by squeezing the glutes at the top, moving from the chest down) requires less weight and worse leverage than the standard straight-line ''hinge'' method but, per Contreras, about 60% of his clients feel it targets the glutes better; he also uses the chin-tuck/scoop cue to let clients with recurring lower-back pain return to hip thrusting pain-free.', 'practice', 'weak', NULL, '{"clients_preferring_scoop_pct": 60, "clients_preferring_hinge_pct": 40}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need to Fix Your Flat Butt'),
('strength-accessories', 'rowing form: keep the bicep pre-tensioned instead of fully extending', 'Humiston coaches that rowing movements should not fully extend the arm at the stretch position, because that fully stretches and loads the biceps instead of the lats; instead, maintain near-static bicep tension throughout the rep and generate the pulling motion by opening and closing the shoulder rather than the elbow. He recommends single-arm cable rows (e.g. seated cable row) to learn this feel before applying it to bilateral rows.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get A BIGGER WIDER BACK (STOP DOING THIS!)'),
('progression', 'deadlift form breakdown fixed progressively with rack pulls', 'Humiston attributes deadlift form breakdown deep in the range to ankle/hip/thoracic-spine inflexibility or weak glutes/lower back, and coaches fixing it progressively with rack pulls: start the pin high, and gradually lower it (increasing range of motion) over time as strength and mobility improve, rather than trying to fix everything in the full range at once.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get A BIGGER WIDER BACK (STOP DOING THIS!)'),
('tempo', 'pullover form: stop at peak lat contraction', 'On dumbbell pullovers, Humiston coaches getting a deep stretch, then pulling only through the lat-dominant portion of the range and stopping at peak lat contraction, rather than continuing to pull all the way up into the range where the triceps take over.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get A BIGGER WIDER BACK (STOP DOING THIS!)'),
('strength-accessories', 'back-extension technique: dynamic flexion/extension instead of a static top hold', 'Humiston says he differs from most coaches on back extensions/hyperextensions: rather than holding a plate and doing a single static top contraction, he coaches controlled flexion and extension through the back''s range of motion, building the range up gradually with body weight first as comfort and control increase.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get A BIGGER WIDER BACK (STOP DOING THIS!)'),
('strength-accessories', 'vary grip, handle, and pull angle across a back workout', 'Humiston recommends deliberately varying hand position, grip (pronated/supinated), and pull angle across lat pulldowns and rows within a single back workout, because each variation shifts emphasis among lats, upper/mid/lower traps, rhomboids, rear delts, and spinal erectors; he coaches consciously checking off which sub-regions were hit each session rather than defaulting to the same grip every time.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Get A BIGGER WIDER BACK (STOP DOING THIS!)'),
('strength-accessories', 'behind-the-body cable lateral raise for stretch-biased side delt training', 'Ethier''s main side-delt exercise is the behind-the-body cable lateral raise (standing in front of and to the side of a low cable) because, unlike the standard dumbbell lateral raise (hardest at the top/contracted position, easiest at the bottom/stretched position), it loads the delt hardest while stretched; he sets the cable 2-3 notches above the lowest position so resistance is greatest early in the rep near the stretch.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Shoulders (3 Exercises)'),
('progression', 'fixed-load, rising-reps progression as an alternative to adding weight weekly', 'Ethier''s applied recommendation (based on an internally-run comparison of a load-progression group vs. a reps-progression group over 8 weeks) is to keep the same weight on lateral raises and add a couple more reps than the previous session, starting around 10 reps per set, and only increase the weight once 15-20 clean reps per set are achievable.', 'opinion', 'weak', NULL, '{"starting_reps": 10, "reps_before_load_increase": "15-20", "comparison_duration_weeks": 8, "reps_progression_observed_range": "16-20"}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Shoulders (3 Exercises)'),
('strength-accessories', '45-degree arm path for rear delt isolation', 'Ethier recommends matching arm path to rear delt fiber direction (about 45 degrees) on reverse cable flyes, reverse pec deck, or incline dumbbell rows, stepping further back from the cable to bias more resistance at the stretched starting position, and avoiding squeezing the shoulder blades together (which lets mid-back muscles take over) by instead pushing the arms forward to open the shoulder blades before pulling the elbows back.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Shoulders (3 Exercises)'),
('equipment', 'recline the bench on seated shoulder press to reduce shoulder mobility demand', 'Ethier recommends setting the seated dumbbell shoulder press bench back 1-2 notches from vertical rather than fully upright, because pressing straight overhead from a vertical bench requires around 90 degrees of external (''hands-back'') shoulder rotation, which a cited study of over 2,400 people found the average person can only reach to about 60 degrees; reducing the bench angle lowers the mobility demand and helps avoid pressing the weight forward or aggravating the shoulder.', 'opinion', 'weak', NULL, '{"bench_recline_notches": "1-2", "avg_achievable_external_rotation_deg": 60, "upright_press_required_rotation_deg": 90, "cited_study_n": 2400}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Shoulders (3 Exercises)'),
('smith', 'Smith machine squat rated highly by elite bodybuilders', 'Doucette rates the Smith machine squat A-tier (near-top) for quad training and notes that 5x Mr. Olympia Chris Bumstead uses it as his preferred squat variation instead of a free-bar squat; Doucette''s stated advantage is being able to push close to failure without a spotter or fear of falling over, though he still rates the free-bar squat slightly higher overall for most lifters.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises For The Quads'),
('strength-accessories', 'hack squat rated as an equally effective, lower-back-friendlier alternative to the barbell squat', 'Doucette rates the hack squat S-tier, equal to the barbell back squat for hypertrophy purposes in non-competitive lifters, citing his own L4-L5 disc herniation as the reason it matters to him personally: it is easier on the lower back, requires less stabilization, and allows faster setup between sets than a free-bar squat.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises For The Quads'),
('equipment', 'leg press: maximize backrest range of motion instead of ego-lifting more plates', 'Doucette recommends setting the leg-press backrest as far back as the machine allows to maximize range of motion, rather than moving it forward (which shortens the range and lets lifters load more plates). He personally reduced his working load from 13 plates/side for 10-15 reps in the past to 6-8 plates/side now, prioritizing a controlled eccentric with a pause at the bottom over maximum load.', 'practice', 'weak', NULL, '{"plates_per_side_before": 13, "plates_per_side_now": "6-8", "reps": "10-15"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises For The Quads'),
('strength-accessories', 'leg extension rated as a warm-up/finisher rather than a primary quad builder', 'Doucette rates the leg extension B-tier: useful as a warm-up before, or finisher after, S/A-tier compound work (or on days he wants to go easy on the legs), but not a primary quad builder, because the machine''s resistance curve is too easy at the bottom and too hard at the top, which causes most lifters to cheat reps by leaning back and using momentum unless a training partner manually assists the hardest (top) portion of the rep.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises For The Quads'),
('strength-accessories', 'single-leg exercises rated lower because lifters rarely push them to true failure', 'Doucette rates lunges (D-tier) and Bulgarian split squats (B-tier, not S despite acknowledging a strong quad stretch and unilateral balance benefit) lower than their popularity suggests, reasoning that because they are trained one leg at a time, most lifters (himself included) mentally hold back and do not push each leg to true failure the way they would on a bilateral exercise. He does rate Bulgarian split squats A-tier as a corrective option for someone with a unilateral injury or a specific left-right strength imbalance.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises For The Quads'),
('tempo', 'full stretch range of motion treated as the key growth driver, convergent across independent practitioners', 'Three independent channels in this batch all emphasize training through the fully stretched bottom/end position of a lift as the most important part of the rep for growth: Ethier cites stretch-mediated-hypertrophy research and applies full-ROM cues plus ''length partials''; Doucette seeks maximum stretch depth on squats and leans forward on hamstring curls for extra stretch; Humiston coaches ''exaggerating the stretch'' on rows and getting a ''nice deep stretch'' on pullovers before contracting.', 'practice', 'moderate', NULL, '{"note": "independent convergence across 3 distinct channels in this batch: Built With Science (Ethier), Greg Doucette, Ryan Humiston"}'::jsonb, 'Multiple: Built With Science (Ethier) — How To Build Muscle Almost 2x Faster (NEW RESEARCH); Greg Doucette (IFBB pro, coaching content) — This Will Make Your Legs Grow; Ryan Humiston (physique, exercise selection) — How To Get A BIGGER WIDER BACK (STOP DOING THIS!)'),
('volume-per-muscle', 'glute-day set/rep structure', 'Ethier structures his own glute-focused leg day as hip thrust (1-4 sets to failure, 10-20 reps, light weight, mind-muscle focus) into Bulgarian split squat (2-3 sets per side, 8-12 reps) into a light back squat done LAST (3 sets, 6-10 reps, slow/controlled), plus a hamstring curl accessory since none of the other three exercises train hamstrings directly.', 'practice', 'weak', NULL, '{"hip_thrust_sets": "1-4", "hip_thrust_reps": "10-20", "bss_sets_per_side": "2-3", "bss_reps": "8-12", "squat_sets": 3, "squat_reps": "6-10"}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Glutes (3 Exercises)'),
('strength-accessories', 'hip thrust foot placement', 'To maximize glute involvement in the barbell hip thrust, Ethier cues positioning the feet so that at the top of the rep the shins form a vertical line directly over the feet; feet too far away shifts load to hamstrings, feet too close shifts it to quads.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Glutes (3 Exercises)'),
('tempo', 'hip thrust ROM emphasis', 'Ethier trains hip thrusts through only the top half of the range of motion with a 1-2 second pause at full lockout, reasoning the glutes do little work in the bottom half of a hip thrust given the exercise''s resistance profile.', 'practice', 'weak', NULL, '{"pause_seconds": "1-2", "rom": "top half only"}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Glutes (3 Exercises)'),
('equipment', 'single-leg dumbbell hip thrust as barbell substitute', 'Ethier substitutes a single-leg dumbbell hip thrust (dumbbell across the working thigh, other leg lifted) for the barbell hip thrust, judging it trains the glutes just as well while taking about 30 seconds to set up versus roughly 10 minutes to rig a barbell hip-thrust station; the main fault to watch for is the hips dropping to one side, corrected by bracing the core.', 'practice', 'weak', NULL, '{"setup_time_barbell_min": 10, "setup_time_db_sec": 30}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Glutes (3 Exercises)'),
('strength-accessories', 'Bulgarian split squat foot position controls quad vs glute emphasis', 'Moving the working (front) foot farther away from the bench, so the shin stays vertical over the foot at the bottom instead of angled forward, shifts the Bulgarian split squat''s emphasis from quads toward glutes/hamstrings; leaning the torso forward through the descent further increases the stretch on the glutes at the bottom.', 'practice', 'moderate', NULL, '{"note": "moderate confidence: this same foot-position principle (farther-from-bench = more glute bias) is independently stated by Greg Doucette/Eric Janicky in a separate video rating BSS regressions for glutes vs quads — two independent channels converge."}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Glutes (3 Exercises)'),
('tempo', 'squat depth for glute growth', 'Ethier cites a study finding full-depth squats produced roughly 3x the glute growth of half squats, and applies this by cueing squatters to descend until the upper thighs are parallel to the floor.', 'opinion', 'weak', NULL, '{"depth_target": "thighs parallel to floor", "note": "cited multiplier ~3x glute growth vs half squat, from a 2019 study he references"}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Glutes (3 Exercises)'),
('volume-per-muscle', 'warm-up sets counted separately from working sets', 'Humiston prescribes two sets of 30 reps on lat pulldown purely as a warm-up/mind-muscle primer before the actual working drop sets, treating them as non-counting preparatory volume.', 'practice', 'weak', NULL, '{"warmup_sets": 2, "warmup_reps": 30}'::jsonb, 'Ryan Humiston (physique, exercise selection) — BEST Pull Workout For MASSIVE GROWTH! (Back/Biceps/Rear Delts)'),
('strength-accessories', 'single-arm row elbow lockout cue', 'Humiston cues keeping a slight bend in the elbow at full extension during single-arm dumbbell rows rather than fully straightening the arm, arguing full extension disengages the lat and shifts tension onto the bicep.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — BEST Pull Workout For MASSIVE GROWTH! (Back/Biceps/Rear Delts)'),
('strength-accessories', 'back-to-back grip-switch curl finisher', 'Humiston finishes a pull workout with reverse-grip straight-bar cable curls to failure, immediately flipped to a regular grip on the same cable for a second set to failure, followed by single-arm dumbbell curls with the off arm braced against the body as an improvised preacher curl.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — BEST Pull Workout For MASSIVE GROWTH! (Back/Biceps/Rear Delts)'),
('guideline', 'warm-up sets scale down across a workout, not per exercise', 'Doucette does 2-3 warm-up sets only for the first exercise of a muscle group in his one-workout-per-day full-body sessions; for every subsequent exercise on the same muscle he does at most one warm-up set (sometimes none, especially above ~15 reps), reasoning the muscle is already warm. He advises beginners and multi-day bro-split lifters to warm up more per exercise since they lack the mind-muscle connection built from continuous same-session training.', 'practice', 'weak', NULL, '{"first_exercise_warmup_sets": "2-3", "later_exercise_warmup_sets": "0-1"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does Shizzy Know How To Train Chest?'),
('volume-per-muscle', 'weekly set ceiling scales inversely with intensity', 'Doucette trains his whole body 2-3x/week and caps weekly volume per muscle at roughly 10-20 sets, stating that high volume and high intensity (training close to failure) cannot be combined without overtraining — the harder the sets, the fewer of them should be done.', 'practice', 'weak', NULL, '{"sets_per_muscle_per_week": "10-20", "frequency_per_week": "2-3"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does Shizzy Know How To Train Chest?'),
('tempo', 'no-momentum pause reps', 'Doucette coaches pausing the weight at the point of peak contraction and deliberately slowing the eccentric relative to the concentric, arguing that using momentum or bouncing the weight up and down takes work away from the target muscle and raises injury risk.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Does Shizzy Know How To Train Chest?'),
('smith', 'old-school lifters avoided the Smith machine for bench', 'Doucette states that historically, the biggest bodybuilders he trained around always used the free-weight bench press rather than the Smith machine for chest, though he adds the specific tool matters less than simply training harder than the previous session (progressive overload).', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Does Shizzy Know How To Train Chest?'),
('tempo', 'stretch-mediated hypertrophy for biceps', 'Ethier recommends training biceps through a full range of motion that emphasizes the fully stretched bottom position (citing a study where bottom-half-only preacher curls produced far more growth than top-half-only), favoring exercises that load the stretched position such as slight-incline dumbbell curls and behind-the-body cable curls, and adding bottom-half partial reps after reaching failure on full-ROM sets.', 'opinion', 'weak', NULL, '{"note": "cited study: bottom-half preacher curl produced almost 3x the biceps growth of top-half-only after 5 weeks"}'::jsonb, 'Built With Science (Ethier) — BIGGER BICEPS: 5 Techniques To Speed Up Growth'),
('volume-per-muscle', 'direct bicep volume upper limit', 'Ethier recommends working up toward roughly 15 weekly direct sets for biceps as a practical upper limit for most lifters, adding sets gradually from a current baseline rather than jumping straight to the ceiling, and splitting the sets across at least two sessions per week rather than doing them all at once.', 'opinion', 'weak', NULL, '{"weekly_set_upper_limit": 15, "sessions_per_week": ">=2"}'::jsonb, 'Built With Science (Ethier) — BIGGER BICEPS: 5 Techniques To Speed Up Growth'),
('strength-accessories', 'mind-muscle connection cueing', 'Ethier recommends actively focusing on feeling the biceps squeeze and thinking about pulling the weight into the body (rather than just lifting it) as a technique to increase gains from curls.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — BIGGER BICEPS: 5 Techniques To Speed Up Growth'),
('progression', 'isolation-exercise progression is slower and needs tracking', 'Ethier advises picking 2-3 fixed bicep exercises to track over time, logging weight and reps each session and aiming to beat the previous session by 1-2 reps or a small weight increase, noting that visible week-to-week progression on isolation exercises like curls is much slower than on big compound lifts.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — BIGGER BICEPS: 5 Techniques To Speed Up Growth'),
('guideline', 'rate exercises by hypertrophy stimulus-to-risk ratio, not by strength standards', 'Doucette and Janicky explicitly grade exercises for a body part by weighing muscle activation/stimulus against injury risk rather than by how much weight can be lifted or how ''compound'' the movement is — this is their stated reasoning for rating deadlifts low for glute/hamstring hypertrophy despite deadlifts being a top strength exercise.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('strength-accessories', 'deadlift rated low for glute/hamstring hypertrophy specifically', 'Both coaches rate the barbell deadlift only a ''C'' for building glutes/hamstrings, arguing that despite being an excellent overall-strength exercise, its high injury risk and low rep ranges (typically 1-8 reps) make it inferior for hypertrophy purposes to lower-risk alternatives such as the deficit RDL, seated hamstring curl, glute bridge, or Bulgarian split squat. They also note a lifter''s deadlift strength or deadlift-heavy training history does not prove the deadlift caused their glute/hamstring size, since genetics and other exercises confound the comparison.', 'opinion', 'weak', NULL, '{"rating": "C"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('strength-accessories', 'glute bridge rated top exercise for glutes, regardless of sex', 'Both coaches rate the barbell/Smith/machine glute bridge an ''A+'' for glute hypertrophy and consider it underused by men specifically because it is perceived as a ''female'' exercise; they argue hypertrophy stimulus does not depend on the lifter''s sex, so an exercise effective for one sex is effective for the other.', 'opinion', 'weak', NULL, '{"rating": "A+"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('tempo', 'glute bridge technique: hold and deep ROM over heavy loading', 'For the glute bridge, both coaches recommend holding a 2-4 second peak contraction at the top and using a box or elevated foot platform to increase range of motion and get a deeper stretch at the bottom, using lighter weight than lifters typically default to; loading very heavy for low reps without a pause or full ROM is described as ''ego-lifting'' that builds strength but not much glute size.', 'opinion', 'weak', NULL, '{"reps": "typically 12-15", "hold_seconds": "2-4"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('strength-accessories', 'Bulgarian split squat rated top glute/hamstring exercise, but separately rated low for quads', 'Both coaches rate the Bulgarian split squat an ''A'' for glute/hamstring hypertrophy — calling it possibly the single best compound hypertrophy movement — while in a separate quad-focused rating (referenced in the same conversation) they rate the same exercise a ''D'' for quads, illustrating that stance/foot cueing changes which muscle a given exercise variation actually trains.', 'opinion', 'weak', NULL, '{"rating_glutes_hams": "A", "rating_quads": "D"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('smith', 'Smith machine recommended for Bulgarian split squat stability', 'Doucette/Janicky recommend performing the Bulgarian split squat on a Smith machine rather than free weight, specifically to remove the balance/falling risk that causes many lifters to hold back, so effort can go toward hip extension and muscle tension instead of stability. Note: this is a context-dependent equipment recommendation from the same coach (Doucette) who elsewhere described elite lifters as traditionally avoiding the Smith machine for bench press — he applies it selectively where the fixed bar path solves a specific stability problem.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('tempo', 'Bulgarian split squat depth progression via elevated front foot', 'To deepen the stretch on the glutes/hamstrings without adding weight, the coaches recommend elevating the front foot on one or two small plates while lightening the load, allowing 2-3 extra inches of range of motion at the bottom of the Bulgarian split squat, plus slowing the reps down.', 'opinion', 'weak', NULL, '{"front_foot_elevation_plates": "1-2"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('strength-accessories', 'RDL rated moderate for glute/hamstring hypertrophy due to lower-back risk', 'Both coaches rate the RDL a ''B''/''B-'' for glute/hamstring growth — good stimulus but higher lower-back injury risk under load than alternatives like the seated hamstring curl — and recommend performing it in a deficit (standing on a small box) for extra range of motion, only reaching as low as hamstring mobility allows while keeping a flat/neutral spine and eyes forward, rather than rounding the back to touch the floor.', 'opinion', 'weak', NULL, '{"rating": "B/B-"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('strength-accessories', 'seated hamstring curl preferred over lying hamstring curl', 'The seated hamstring curl is rated ''A+'' versus a ''B-'' for the lying hamstring curl, because the seated version''s pad position over the quad mechanically prevents cheating with the lower back or arms, allows safe loading close to failure and on negatives, and — with a training partner pressing the leg pad down — can be set up so the stack never tops out, keeping constant tension for extra stretch-position stimulus.', 'opinion', 'weak', NULL, '{"rating_seated": "A+", "rating_lying": "B-"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Best Exercises To Build Your Glutes'),
('guideline', 'warm-up needs vary sharply between advanced lifters', 'Doucette''s own pre-training warm-up runs about 30 minutes, but his training partner (an elite natural bodybuilder) warms up with only about 5 minutes of light cardio/rotator work before going straight into working sets, illustrating that even among advanced lifters personal warm-up needs vary considerably.', 'practice', 'weak', NULL, '{"doucette_warmup_min": 30, "partner_warmup_min": 5}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Legs With Chestbrah And Alex Mendoza'),
('periodization', 'vacation deload guidance', 'Doucette''s advice for training while on vacation/travel is to take a deload week — train at moderate intensity rather than skipping training entirely, and explicitly not chase personal records during that week.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Legs With Chestbrah And Alex Mendoza'),
('volume', 'high intensity substituting for volume', 'A training partner in this session states that pushing sets well past failure (partial reps followed by forced lockout pulses mimicking a sprint effort) lets him get away with fewer total sets, framing effort/intensity and total volume as substitutes for each other rather than additive: you can do a lot of volume or a little more intensity, but not both at maximum.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Legs With Chestbrah And Alex Mendoza'),
('strength-accessories', 'training around a hip injury by limiting squat depth for a sport goal', 'One lifter with a history of hip surgery trains quads on the hack squat machine without going below parallel, on his doctor''s advice, specifically because his goal (bike racing) only requires quad strength through the top/mid portion of the pedal stroke rather than a deep squat range; he also trains with lighter weight than previously because ongoing cycling volume leaves his legs chronically sore.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Legs With Chestbrah And Alex Mendoza'),
('tempo', 'cross-video convergence on controlled reps over ego-lifting', 'Across this batch, multiple practitioners on different channels independently repeat the same core technique principle for hypertrophy: use a full or purpose-selected range of motion, pause at the point of peak muscle tension, and control the eccentric, rather than using momentum or heavier loads than can be controlled (''ego-lifting''). Each frames uncontrolled heavy partial reps as building strength/ego but not muscle size.', 'opinion', 'moderate', NULL, '{"note": "convergent across at least 3 videos / 2 channels in this batch: hip thrust bracing+pause (Ethier), pause-rep chest coaching (Doucette), glute bridge anti-ego-lifting technique (Doucette/Janicky)"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Does Shizzy Know How To Train Chest?'),
('strength-accessories', 'bench press elbow/hand tracking and injury risk', 'A practitioner (Eric Janicki, IFBB-affiliated coach) argues the standard barbell bench press forces the elbows to bow outward from the shoulders (especially under fatigue), loading the biceps, front delt, and pec minor and driving the sport''s high rate of pec/shoulder injuries; he prefers presses where the hand path keeps the elbow closer to a roughly 45-degree line from the torso, as on Hammer Strength-style machines, rather than a straight vertical bar path.', 'opinion', 'weak', NULL, '{"note": "elbow path ~45 degrees from torso vs. straight up on a flat barbell bench"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('strength-accessories', 'contradiction: bench press value for hypertrophy', 'One practitioner grades the barbell bench press an A+ as the best chest exercise for size, while a second (an injured ex-powerlifter turned bodybuilder) grades it a D and says his own chest grew exponentially after he stopped bench pressing 8 years ago in favor of flye/stretch-focused pressing. This is a live, unresolved disagreement between two practitioners rather than settled fact; the broader hypertrophy literature does not support any single exercise being innately superior once volume and proximity to failure are matched, so the practitioner''s dramatic before/after claim is more plausibly confounded by his injury history and added variety/effort than by the bench press itself being uniquely inferior.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('tempo', 'pause reps and controlled negatives to make bench press safer', 'A coach''s fix for lifters who want to keep bench pressing while reducing injury risk: pause the bar on the chest, use a slower negative, and train in higher rep ranges (10-15+) rather than chasing 1-5 rep maxes, which he says immediately reduces the load used and the injury risk.', 'practice', 'weak', NULL, '{"rep_range": "10-15+", "note": "pause at chest, slower eccentric, avoid low-rep 1RM-chasing sets"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('equipment', 'cambered bar for deeper chest stretch', 'A cambered bench bar is bent so it clears the chest, letting the lifter dig the elbows deeper than a straight bar allows; the practitioner uses it specifically to add range of motion and stretch on pressing movements he otherwise finds range-limited.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('smith', 'Smith machine press rated for safety over muscle-building value', 'Both practitioners independently rate the Smith machine incline/flat press only a C, below free-weight or machine alternatives, because its fixed vertical bar path removes the inward/converging hand path needed for peak chest contraction; both note it is nonetheless useful specifically for safely loading pause reps and negatives.', 'opinion', 'moderate', NULL, '{"note": "grade C from both speakers in the same video"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('strength-accessories', 'machine flye/pec deck rated highly for chest isolation and stretch', 'A practitioner rates the machine flye/pec deck A-minus, arguing pressing movements let the lats and triceps take over the load (he claims heavy bench pressers privately admit they are ''pressing with their lats, not their chest''), whereas a flye isolates the chest; he trains it with a 6-second negative and a 2-second hold in the fully lengthened position, using the full weight stack.', 'practice', 'weak', NULL, '{"eccentric_seconds": 6, "stretch_hold_seconds": 2, "note": "full stack (~300 lb) on pec deck flye"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('tempo', 'long time-under-tension stretch-position sets as a mobility substitute', 'A practitioner''s rationale for very long (up to roughly 2-minute), high-rep, stretch-emphasized sets on flyes and leg press is that holding the lengthened position under load during training substitutes for dedicated mobility/soft-tissue work during the week (''train long to remain long''), which he prefers given limited time.', 'opinion', 'weak', NULL, '{"note": "sets described as lasting up to ~2 minutes"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('tempo', 'convergence — training through a full stretch position drives extra hypertrophy', 'Two independent practitioners in this batch converge on loading the lengthened/stretched position as a deliberate technique choice rather than a side effect: one bodybuilder says his chest growth accelerated after switching to flye/press variations with multi-second eccentrics and holds at full stretch; a separate physique coach (Built With Science) independently designs lateral raise variations specifically to load the shoulder''s stretched bottom position rather than its mechanically strongest range, citing his own results.', 'practice', 'moderate', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('guideline', 'contradiction: heavier weight assumed to build more muscle than light weight', 'One practitioner asserts as fact that lifting heavier weight builds more muscle than lighter, higher-rep isolation work (''I don''t think you''re building as much muscle as the guy that has a heavier weight... it''s easier progressive overload''), offering no data. Within this same batch, a different practitioner''s own controlled 60-day unilateral self-experiment found no meaningful hypertrophy difference between 3-6 rep and 15-30 rep training taken to true failure. This is flagged as a direct in-batch contradiction between an unsupported ''heavy is better'' opinion and both a practitioner''s own tested experience and the wider load-equivalency evidence base.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Bench Press Is Not A Good Exercise'),
('guideline', 'agonist-antagonist supersets to cut session time', 'A coach structures chest/back sessions as agonist-antagonist supersets — one set of chest, then immediately a back exercise while the chest rests, alternating back and forth — to finish a full workout in about an hour instead of two, claiming more total work and calorie burn in less time.', 'practice', 'weak', NULL, '{"note": "back-and-forth chest/back sets; ~1 hour vs ~2 hours to complete equivalent work"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Chest Back Shoulders Biceps With Jesse James West PUSH PULL'),
('progression', 'set-by-set ramp with only the final set taken to true failure', 'A coach''s per-exercise set structure: an easy warm-up set, then one or two moderately hard ramp sets that are not all-out, saving effort for a final hardest working set which is pushed to failure and often extended with a drop set or partial reps (''failure and beyond'').', 'practice', 'weak', NULL, '{"note": "1 easy set + 1-2 moderate ramp sets + 1 all-out final set with drop set/partials"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Chest Back Shoulders Biceps With Jesse James West PUSH PULL'),
('progression', '5-10 rep window as the target for a hard working set', 'A coach selects working weight for a hard set by targeting failure somewhere in the 5-10 rep range: hitting more than 10 reps means the weight was too light, failing before 5 means it was too heavy, and a rep count landing in that window means the weight was chosen correctly.', 'practice', 'weak', NULL, '{"target_rep_range": "5-10", "note": "used as an autoregulation check for load selection on hard sets"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Chest Back Shoulders Biceps With Jesse James West PUSH PULL'),
('strength-accessories', 'bench press grip width shifts chest vs. triceps emphasis', 'A coach cues that a wider grip on the barbell bench press shifts emphasis toward the chest while a narrower grip shifts it toward the triceps; he also describes deliberately widening his grip on one side to unload an injured/weaker arm while still training through the injury rather than skipping the lift.', 'practice', 'weak', NULL, '{"note": "wider grip = more chest, narrower grip = more triceps"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Training Chest Back Shoulders Biceps With Jesse James West PUSH PULL'),
('strength-accessories', 'spotter should not touch the bar until the lift is clearly failing', 'A coach''s spotting technique: keep hands near the bar throughout a hard rep but do not make contact until the lifter has either completed the rep or is clearly stuck, since grabbing the bar early (e.g. with it three-quarters up) takes credit away from a rep the lifter could have finished alone.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Chest Back Shoulders Biceps With Jesse James West PUSH PULL'),
('guideline', 'convergence — chasing heavier numbers over form undermines training quality', 'Independently, one coach repeatedly warns against ''ego lifting'' and blocks his training partner from jumping to weight increments that break form, and a second coach identifies his beginner subject''s ''ego growing more than his muscles'' as an active problem during a training experiment, using EMG to show reps were being cut short. Both treat visible weight/rep numbers as a common distraction that leads lifters to sacrifice range of motion, control, or true failure for a bigger number.', 'practice', 'moderate', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Training Chest Back Shoulders Biceps With Jesse James West PUSH PULL'),
('volume-per-muscle', 'front delts get more incidental volume than side delts', 'A coach argues that because chest-pressing sets are typically counted as volume for both chest and front delts (given how much the front delt contributes to pressing), and shoulder pressing adds even more direct front-delt volume, most lifters accumulate far more weekly volume for the front delt than the side delt without intending to, leading to front-delt overdevelopment relative to the side-delt ''width'' most people actually want.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Wide Shoulders'),
('strength-accessories', 'dropping shoulder presses entirely to prioritize side-delt width', 'A coach reports he personally stopped doing any shoulder press for over a year and redirected that training time to side-delt lateral raise work specifically because widening the shoulders, not overall shoulder size, was his priority, and says that is when his shoulders visibly widened.', 'practice', 'weak', NULL, '{"note": "no shoulder pressing for 1+ year"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Wide Shoulders'),
('strength-accessories', 'scapular-plane arm path for lateral raises maximizes stretch', 'A coach''s cue for lateral raise technique: lock the elbow to the side and rotate the arm outward to wherever it naturally stops (the ''scapular plane'') — the arm path he says both maximizes side-delt tension and, on a cable where the arm can travel slightly behind the torso, gives the biggest stretch at the bottom of the rep.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Wide Shoulders'),
('equipment', 'raised cable pulley height shifts lateral-raise tension to the stretched position', 'Setting the cable pulley at a slightly raised position rather than at the floor for a lateral raise shifts the resistance so the most challenge occurs at the start/bottom of the rep, where the side delt is most stretched, instead of near the top/lockout where a standard dumbbell lateral raise is hardest and the delt is weakest.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Wide Shoulders'),
('strength-accessories', 'rear-side-delt-biased lateral raise variation', 'To bias the rear portion of the side delt specifically, a coach sets a cable at wrist height, grabs it in front of the body, rotates the torso about 45 degrees toward the cable, and raises the arm in a line that travels slightly behind the torso, accepting a shorter range of motion than a standard lateral raise; a chest-supported dumbbell version uses a bench set one notch below vertical, arms hanging straight down and raised out to the sides.', 'practice', 'weak', NULL, '{"torso_rotation_degrees": 45, "note": "cable at wrist height; dumbbell version uses bench one notch below vertical"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Wide Shoulders'),
('progression', 'micro-loading and rep targets for progressing small, load-sensitive lifts', 'Because a small fixed jump (e.g. 5 lb on a dumbbell, or one pin on a cable stack) is a much larger relative percentage increase on a light exercise like a lateral raise than on a heavy compound lift, a coach uses a rep range of 10-20, only increases load once 15+ controlled reps are achieved across all sets, and threads a 2.5-5 lb plate onto the cable pin for smaller-than-standard jumps.', 'practice', 'weak', NULL, '{"rep_range": "10-20", "add_weight_at_reps": 15, "microplate_lb": "2.5-5", "note": "used for cable/lateral-raise progression where standard pin jumps are too large"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Wide Shoulders'),
('guideline', 'heavy-low-rep vs light-high-rep produced no meaningful hypertrophy difference in a self-experiment', 'In a 60-day unilateral self-experiment (one side trained to failure at 3-6 reps, the other at 15-30 reps, equal total sets both sides, tracked via MRI/DEXA/ultrasound), the coach found essentially no meaningful difference in muscle growth between sides — the light/high-rep side trended slightly ahead in most muscles (chest showed the largest gap, roughly double the growth on the light side), but absolute differences were tiny (as little as 15 g) and, per the coach, nowhere near statistically significant. A same-protocol beginner subject showed the same no-clear-winner pattern.', 'practice', 'weak', NULL, '{"duration_days": 60, "heavy_failure_reps": "3-6", "light_failure_reps": "15-30", "note": "both sides equal total sets; N=1 experienced lifter + N=1 beginner; measured via MRI/DEXA/ultrasound"}'::jsonb, 'Built With Science (Ethier) — I Trained One Side HEAVY vs LIGHT (60 Day Experiment)'),
('progression', 'true failure required for light-weight sets to recruit the biggest motor units', 'Using EMG, the coach showed that on heavy loads, muscle activation is high from the very first rep, but on light loads, activation stays low and only ramps up as the set approaches true failure — meaning if a lifter stops a light-weight set before genuine failure (which most people are tempted to do once the burn sets in), the largest, most growth-relevant motor units are never recruited.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Trained One Side HEAVY vs LIGHT (60 Day Experiment)'),
('clinical', 'heavy low-rep loading produced more joint discomfort than light high-rep loading', 'During the same 60-day experiment, both the coach and his beginner training partner experienced joint pain specifically on their heavy, low-rep sides (knee pain on leg extension, elbow discomfort on overhead triceps extension) severe enough to discontinue those exercises on the heavy side, while the light, high-rep sides did not produce comparable joint pain.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Trained One Side HEAVY vs LIGHT (60 Day Experiment)'),
('clinical', 'asymmetric heavy unilateral leg training may have contributed to a later back injury', 'The coach observed that his hip-stabilizing iliopsoas grew larger only on the side trained heavy for unilateral leg work (and, by his account, shrank on the light-trained side), and he attributes a subsequent lower-back tweak during a return to heavy bilateral deadlifting partly to the asymmetry created by 60 days of one-sided heavy training. He frames this as a caution rather than a proven cause.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Trained One Side HEAVY vs LIGHT (60 Day Experiment)'),
('progression', 'prioritize adding reps over adding weight on light, high-rep work', 'Because a fixed weight increment is a much larger relative jump on a light load than a heavy one (the coach''s example: +5 lb on 100 lb is a 5% increase, but +5 lb on 50 lb is a 10% increase), he recommends progressing light/high-rep work primarily by beating the previous week''s rep count rather than trying to add weight at the same rate as on heavy sets.', 'practice', 'weak', NULL, '{"example_heavy_pct_increase": "5%", "example_light_pct_increase": "10%"}'::jsonb, 'Built With Science (Ethier) — I Trained One Side HEAVY vs LIGHT (60 Day Experiment)'),
('guideline', 'settled on a moderate 6-15 rep range as primary training zone after direct comparison', 'After directly comparing 3-6 rep and 15-30 rep training on himself, the coach''s stated conclusion is to make roughly 6-15 reps at moderate weight his primary training zone going forward (light enough to protect joints, heavy enough to not require extreme mental toughness every set), while still sprinkling in occasional very heavy and very light sets for their specific benefits.', 'opinion', 'weak', NULL, '{"primary_rep_range": "6-15", "note": "adopted after his own heavy-vs-light self-experiment"}'::jsonb, 'Built With Science (Ethier) — I Trained One Side HEAVY vs LIGHT (60 Day Experiment)'),
('tempo', 'eccentric control vs speed on presses', 'Doucette (critiquing Larry Wheels'' and Simeon Panda''s shoulder press form) argues that for hypertrophy, as opposed to an athlete training for strength/speed, lifters should slow the eccentric and control the weight through the full rep rather than speeding through it as Larry Wheels does; he also says warm-up sets should be performed with the same tempo and form as working sets, not rushed.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — Build Huge Delts Simeon Panda & Larry Wheels Shoulders workout.'),
('strength-accessories', 'overhead press range of motion', 'Doucette says the bar should be pressed to full lockout (even paused) at the top and lowered until it passes below the bottom of the ear; he criticizes Larry Wheels'' and Simeon Panda''s pressing for stopping around three-quarter extension, calling it an easier but shortened range of motion that lets lifters use more weight at the cost of muscle growth.', 'opinion', 'weak', NULL, '{"note": "lower until bar is below bottom of ear; observed stopping point ~3/4 extension"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Build Huge Delts Simeon Panda & Larry Wheels Shoulders workout.'),
('volume-per-muscle', 'rep range for isolation lateral raises', 'Doucette recommends 10-15 reps rather than sets of ~8 for isolation work like cable side laterals, on the grounds that if the first several reps of an isolation movement require cheating to complete, the weight is too heavy; his fix is to lower the weight, slow the eccentric, and squeeze at the top.', 'opinion', 'weak', NULL, '{"reps_isolation_recommended": "10-15", "reps_seen_as_too_heavy": 8}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Build Huge Delts Simeon Panda & Larry Wheels Shoulders workout.'),
('strength-accessories', 'front raise vs rear delt exercise priority', 'Doucette calls the front barbell raise one of the least valuable delt exercises because pressing already overdevelops the anterior delt; he estimates roughly 95% of lifters overtrain the front delt and undertrain the rear delt, and recommends prioritizing side laterals for width and bent-over rear delt raises instead of front raises or wide-grip upright rows (which he says function like a front raise).', 'opinion', 'weak', NULL, '{"note": "estimate ~95% of lifters overtrain front delt relative to rear delt"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — Build Huge Delts Simeon Panda & Larry Wheels Shoulders workout.'),
('guideline', 'resistance training vs stretching for flexibility', 'Ethier states that lifting weights through a full range of motion can improve flexibility about as much as dedicated stretching, framing resistance training itself as a mobility tool rather than something that must be offset by separate stretching work.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — PERFECT Posture Routine To Unlock Your Sh*t (10 Min/Day)'),
('clinical', 'hip flexor tightness and glute activation', 'Ethier relays that tight hip flexors (common from prolonged sitting) may inhibit glute activation, and recommends a half-kneeling hip flexor stretch (back knee near a wall/bench, hips leveled and squared forward) before glute-focused training.', 'opinion', 'weak', NULL, '{"note": "target stretch intensity ~4-5 out of 10"}'::jsonb, 'Built With Science (Ethier) — PERFECT Posture Routine To Unlock Your Sh*t (10 Min/Day)'),
('strength-accessories', 'glute bridge foot position changes emphasis', 'Ethier coaches that foot placement on a glute bridge shifts which muscle dominates: feet further from the body increases quad involvement, feet closer increases hamstring involvement; cue is to squeeze the glutes hard and drive the hips up without arching the lower back, holding the top ~5 seconds, progressing to single-leg to correct side-to-side imbalances.', 'practice', 'weak', NULL, '{"hold_seconds": 5}'::jsonb, 'Built With Science (Ethier) — PERFECT Posture Routine To Unlock Your Sh*t (10 Min/Day)'),
('strength-accessories', 'scapular position determines rear delt vs trap recruitment', 'Humiston argues high-elbow rows (''grip it and rip it'') primarily train mid-traps/rhomboids because that motion uses scapular retraction; to bias the rear delt specifically he coaches scapular depression and slight protraction instead, meaning the classic wide-elbow row form commonly recommended for rear delts is a poor choice for that goal.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Unf*#k Your Rear Delts (Backed by Science!)'),
('strength-accessories', 'straight-arm technique for rear delt shoulder-extension exercises', 'For shoulder-extension-pattern rear delt exercises (incline dumbbell rear delt raise, cable straight-arm pulls), Humiston coaches keeping the arm as straight as possible, since bending the elbow reduces external torque on the shoulder and shifts work to the lats/teres major, and reaching at least ~30 degrees of shoulder abduction at the top of the contraction to reduce the lats'' mechanical advantage.', 'practice', 'weak', NULL, '{"min_shoulder_abduction_deg": 30}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How to Unf*#k Your Rear Delts (Backed by Science!)'),
('strength-accessories', 'mind-muscle cue and grip for rear delt isolation', 'Humiston''s finishing cue for rear-delt shoulder-extension exercises is to ''push out the lat and externally rotate the shoulder'' at the top of the rep, and he finishes many variations with a supinated grip since supination can (though doesn''t guarantee) bias glenohumeral external rotation toward the posterior delt.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Unf*#k Your Rear Delts (Backed by Science!)'),
('strength-accessories', 'push-then-pull technique for reverse fly', 'For horizontal-abduction rear delt exercises (reverse flyes), Humiston avoids pulling straight into full scapular retraction because it recruits traps/rhomboids; his cue is ''push forward, then pull back'' — driving the arm away from the body through the first half of the rep, then pulling back into the rear delt on the second half while protracting rather than retracting the scapula.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Unf*#k Your Rear Delts (Backed by Science!)'),
('strength-accessories', 'bench-supported high-angle rear delt fly', 'Humiston uses an elevated/inclined bench to pin his scapula against a stable surface during rear delt flyes (his version of the high-angle ''Jay Cutler'' rear delt fly), saying the bench gives kinesthetic feedback that reduces trap involvement and makes the movement harder to perform incorrectly than the free-standing version.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Unf*#k Your Rear Delts (Backed by Science!)'),
('strength-accessories', 'unilateral row form to isolate rear delt', 'For rows aimed specifically at the rear delt, Humiston uses a strictly unilateral setup: rotate the torso toward the working side, pull the handle across and away from the body with the shoulder abducted at roughly 60 degrees, and keep the scapula slightly depressed and protracted rather than using a traditional high-elbow row.', 'practice', 'weak', NULL, '{"shoulder_abduction_deg": 60}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How to Unf*#k Your Rear Delts (Backed by Science!)'),
('progression', 'unilateral before bilateral for scapular control', 'Humiston recommends lifters who struggle to consciously control scapular retraction/depression start with unilateral rear-delt movements before progressing to bilateral versions, since single-arm work makes it easier to feel and control scapular position.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How to Unf*#k Your Rear Delts (Backed by Science!)'),
('volume-per-muscle', 'distributing sets across delt heads within one session', 'Humiston changed his own shoulder training from a traditional split (4-5 exercises x 3-4 sets each, finishing one delt head before moving on) to doing only 1-2 sets per exercise with minimal rest, jumping between anterior/lateral/posterior delt exercises within the same block (5-6 exercises in about 10 minutes) rather than grouping all sets for one head together.', 'practice', 'weak', NULL, '{"sets_per_exercise": "1-2", "exercises_per_block": "5-6", "block_time_min": 10}'::jsonb, 'Ryan Humiston (physique, exercise selection) — The BEST Shoulder Workout (Sets and Reps)'),
('strength-accessories', 'exaggerated-stretch rear delt fly on 45-degree bench', 'Humiston does a 45-degree incline-bench rear delt raise with a deliberately small range of motion that exaggerates the stretched position of the rear delt (arm starts straight out in front and contracts from there), using light weight and prioritizing stretch/contraction feel over load.', 'practice', 'weak', NULL, '{"bench_angle_deg": 45}'::jsonb, 'Ryan Humiston (physique, exercise selection) — The BEST Shoulder Workout (Sets and Reps)'),
('strength-accessories', 'cable angle micro-adjustments change delt targeting', 'Humiston treats small setup changes on cables (palm angle relative to the floor, or fully by the side vs supinated) as effectively different rear-delt exercises, and coaches experimenting with these small angle/grip tweaks to find the setup with the best mind-muscle connection.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Shoulder Workout (Sets and Reps)'),
('guideline', 'cue: target the delt head, not the weight', 'Humiston''s stated cueing principle for shoulder training is to think about which head of the deltoid is being used to move the weight, rather than simply thinking about driving the weight up — he says this mental shift changes execution more than swapping exercises does.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The BEST Shoulder Workout (Sets and Reps)'),
('strength-accessories', 'narrow/neutral grip pulldowns and pull-ups for lower lats', 'Ethier, biomechanist Kasim Hansen, six-time Mr. Olympia Dorian Yates, and natural pro Alberto Nunez all favor keeping the elbows tracking close to the torso (narrow, underhand, or neutral grip) on pulldowns/pull-ups rather than wide grip, arguing wide grip flares the elbows and shifts tension to the upper back/traps before the lats reach failure; Yates is quoted as never doing wide-grip pulldowns to grow his lats.', 'practice', 'moderate', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Wide Back'),
('strength-accessories', 'lower lat pulldown cue — shoulder depression not just elbow', 'Ethier''s cue for lower-lat pulldowns is to think ''push your shoulder down'' rather than ''pull your elbow down'' — the lower lats depress the scapula, and if only the elbow drops while the armpit stays in place, the rep is being pulled with the arm rather than the lat.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Wide Back'),
('strength-accessories', 'lat pulldown setup for a deeper stretch', 'For a deeper lat stretch on pulldowns, Ethier leans the torso back about 10-15 degrees, lets the shoulder rise fully toward the ear at the top before pulling, and pulls the elbow toward the hips rather than the chest to keep the biceps from dominating; done correctly he reports needing roughly half the load he used with his prior ''arm-pulling'' form.', 'practice', 'weak', NULL, '{"torso_lean_deg": "10-15", "note": "load dropped roughly 50% after switching to lat-driven pulling form"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Wide Back'),
('strength-accessories', 'upper lat rowing angle', 'For upper lats, Ethier says the row needs to pull at a high-to-low downward angle (single-arm dumbbell row on an incline bench, or a cable row done leaning forward rather than sitting upright) because upper lat fibers run diagonally rather than horizontally, and a flat horizontal row undertrains this region.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Wide Back'),
('strength-accessories', 'avoid trunk rotation on single-arm rows', 'Ethier and Hansen flag letting the torso rotate toward the working arm during a single-arm row as a common mistake — it reduces the lat stretch and shifts load onto the obliques/QL instead; their cue is to keep the chest level with the ground and let the shoulder, not the ribcage, travel forward.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Wide Back'),
('volume-per-muscle', 'back training set/rep scheme with half-rep back-off', 'Ethier programs lat pulldowns/rows for 3-4 sets of 10-15 reps, then extends each set past normal failure with 3-5 half-reps from the bottom of the range, and on pulldowns specifically continues further past that with shoulder-depression-only reps (arm held straight, just raising/lowering the shoulder) once even half-reps can''t be completed.', 'practice', 'weak', NULL, '{"sets": "3-4", "reps": "10-15", "half_reps_after_failure": "3-5"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For A Wide Back'),
('tempo', 'self-test for momentum on curls', 'Ethier''s self-test for excess curl momentum: perform a normal set of curls, then repeat with the back against a wall to eliminate swing; if the weight must drop substantially to complete the wall version, the regular curls were relying on lower-back momentum rather than biceps tension.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Bicep Curls Like This (5 Mistakes Slowing Your Gains)'),
('tempo', 'full range of motion at bottom of curl', 'Ethier coaches against cutting the range of motion short at the bottom of a curl; his cue is to fully extend the arm, flexing the triceps at the bottom, between reps so the biceps get a full stretch each rep.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Bicep Curls Like This (5 Mistakes Slowing Your Gains)'),
('strength-accessories', 'wrist position during curls', 'Ethier cues keeping the wrist extended/neutral (bent back in line with the forearm) throughout a curl rather than letting it flex; a flexed wrist shifts load onto the forearm flexors, causing forearm fatigue/cramping that can end the set before the biceps reach failure.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Bicep Curls Like This (5 Mistakes Slowing Your Gains)'),
('strength-accessories', 'elbow drift recruits front delts on curls', 'Ethier, citing biomechanist Kasim Hansen''s testing, says letting the elbow swing forward during a heavy curl (shoulder flexion) recruits the front delts instead of the biceps; his cue is to keep the elbow locked in place through the rep, allowing only a small amount of natural elbow drift.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Bicep Curls Like This (5 Mistakes Slowing Your Gains)'),
('strength-accessories', 'mind-muscle warmup technique for curls', 'Ethier''s pre-set technique for lifters who can''t feel their biceps working: flex the biceps hard with the arm at the side, then bring the arm up in front of the face while continuing to flex hard until it''s near-cramping, to learn what a genuine biceps contraction feels like before carrying that focus into actual curl sets.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Bicep Curls Like This (5 Mistakes Slowing Your Gains)'),
('strength-accessories', 'pull-in and supination cue for curls', 'Ethier''s execution cues for curls: think about pulling the bar or dumbbell into the body rather than lifting it, and drive the pinkies up toward the ceiling (extra supination) on the way up, for a stronger biceps contraction.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Bicep Curls Like This (5 Mistakes Slowing Your Gains)'),
('strength-accessories', 'tibialis raise as counterpart to calf raise', 'ATG (Kneesovertoesguy''s group) programs a tibialis raise as the standard counterpart to the seated calf machine, arguing most gym-goers train calves heavily but skip the tibialis anterior entirely, producing a strength imbalance; their standard is roughly 20% bodyweight for 15 full reps (e.g., ~35 lb for a 175 lb person).', 'practice', 'weak', NULL, '{"load": "20% bodyweight", "reps": 15, "example": "~35 lb load for a 175 lb person"}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('strength-accessories', 'split-squat hold used as a corrective standard', 'ATG uses an unassisted bodyweight split-squat hold (front heel may lift, back knee must stay off the floor, torso upright) as a diagnostic standard, and report that roughly 90% of new visitors fail it; the prescribed entry regression is simply holding the bottom position for 30 seconds.', 'practice', 'weak', NULL, '{"hold_seconds": 30, "reported_fail_rate_pct": 90}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('strength-accessories', 'bodyweight reverse-hamstring-curl strength standard', 'ATG''s standing reverse-squat/hamstring-curl exercise (leaning back against a strap and curling through a wide range) has a standard of roughly half bodyweight resistance for 20 reps in one set, used as a lower-body strength benchmark ''below the belt line.''', 'practice', 'weak', NULL, '{"load": "~50% bodyweight", "reps": 20}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('strength-accessories', 'Nordic curl standard modeled on an NHL longevity outlier''s technique', 'ATG''s Nordic hamstring curl standard (5 strict reps, hands held behind the back, glutes contracted first before finishing with the hamstrings) is explicitly modeled on hockey player Marty St. Louis, whom they credit as the only player among 20+ pros his trainer worked with who could do it; ATG reports that about 99% of people over 40 cannot pass this standard.', 'practice', 'weak', NULL, '{"reps": 5, "technique": "hands behind back, contract glutes first, then hamstrings finish", "reported_pass_rate": "~1% of people over 40"}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('strength-accessories', 'external-rotation prehab dosed relative to bench strength', 'ATG programs shoulder external-rotation work at roughly 10% of bodyweight (or ~10% of a lifter''s bench 1RM for those focused on benching) for 12 reps as a baseline shoulder standard, and describe a case where a lifter''s chronic bench-related shoulder pain resolved within about 3 weeks of doing a couple of sets before pressing.', 'practice', 'weak', NULL, '{"load": "10% bodyweight, or 10% of bench 1RM", "reps": 12, "case_resolution_weeks": 3}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('strength-accessories', 'contradiction: deliberately loaded spinal flexion used to bulletproof the lower back', 'ATG has trainees perform a slow eccentric loaded spinal-flexion ''bending'' exercise (rounding forward under light load, ~5-second descent) specifically to strengthen the lower back and improve tolerance of flexed positions from prolonged sitting, including with a former quarterback whose lower back was stiff and weak; this deliberately trains loaded spinal flexion, which runs counter to the common strength-coaching doctrine of always keeping the spine neutral/braced under load.', 'practice', 'weak', NULL, '{"eccentric_seconds": 5, "note": "conflicts with mainstream ''always brace/neutral spine'' cueing"}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('progression', 'one regression ladder scaled by ability across ages, not separate age-based programs', 'ATG runs the same movement-progression trees for all trainees regardless of age — an ATG staffer in his 40s and a trainee''s mother nearing 70 both work through identical progressions, just entering at different regression levels for their current ability — rather than prescribing fundamentally different programs by age bracket.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('detraining', 'tibialis weakness attributed to most adults ceasing sprinting after 30', 'ATG asserts that most adults stop sprinting entirely after about age 30, and frames this specific detraining of high-speed running (not an inherent structural weakness) as the reason the tibialis anterior becomes a weak point for most lifters.', 'opinion', 'weak', NULL, '{"note": "claimed ~90% of people never sprint again after age 30, uncited"}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Perfect Mobility Routine ft. Kneesovertoesguy'),
('strength-accessories', 'three-angle cable fly pre-exhaust before chest pressing', 'Humiston has lifters who struggle to feel their chest during pressing pre-exhaust with three angles of cable fly (low-to-high, mid-height, high-to-low) before the pressing movement; besides building mind-muscle connection, he notes this caps how much weight can be pressed afterward, reducing injury risk from overloading a poorly-connected press.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — PUSH WORKOUT For SERIOUS GROWTH! (Chest, Shoulders, Triceps)'),
('tempo', 'rest-pause bench press with a 2-second hold at both top and bottom', 'Humiston''s main incline pressing movement is programmed as rest-pause sets in which every rep includes a 2-second hold at both the bottom and the top, rather than continuous straight-set reps.', 'practice', 'weak', NULL, '{"pause_seconds_top": 2, "pause_seconds_bottom": 2, "set_structure": "rest-pause"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — PUSH WORKOUT For SERIOUS GROWTH! (Chest, Shoulders, Triceps)'),
('tempo', 'chest fly done with shortened top-range to keep tension on the stretch', 'After pressing, Humiston adds a chest fly (machine, bosu, or dumbbell) performed with a deliberately shortened range of motion at the top so tension stays concentrated on the stretched chest rather than being ''wasted'' at lockout, often finishing as a compound set with decline-angled push-ups.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — PUSH WORKOUT For SERIOUS GROWTH! (Chest, Shoulders, Triceps)'),
('volume-per-muscle', 'all three delt heads trained directly even after heavy pressing', 'Humiston has lifters train all three deltoid heads with dedicated dumbbell raises even on a day that already included heavy pressing, and only recommends skipping direct anterior-delt work specifically when pressing already produced clear front-delt fatigue.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — PUSH WORKOUT For SERIOUS GROWTH! (Chest, Shoulders, Triceps)'),
('strength-accessories', 'rear-delt grip chosen by feel rather than fixed', 'For rear-delt raises, Humiston has lifters pick whichever hand grip (pronated or supinated) gives the best mind-muscle connection for them individually, rather than prescribing one fixed hand position for everyone.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — PUSH WORKOUT For SERIOUS GROWTH! (Chest, Shoulders, Triceps)'),
('strength-accessories', 'triceps trained via same-day feel-based exercise/attachment selection to failure', 'For triceps, Humiston has lifters test which attachment or variation (rope vs. bar, partial reps at top or bottom, pronated vs. supinated, stepping back for a longer path) connects best on that specific day, then run 3-4 sets to complete failure on it, switching variation once performance stalls; he reports this can produce 10-12 total triceps sets in under 15 minutes.', 'practice', 'weak', NULL, '{"sets_per_variation": "3-4", "total_sets": "10-12", "time_minutes": 15}'::jsonb, 'Ryan Humiston (physique, exercise selection) — PUSH WORKOUT For SERIOUS GROWTH! (Chest, Shoulders, Triceps)'),
('strength-accessories', 'pelvic rock-back test used to individualize deadlift stance', 'McGill has lifters kneel on all fours and rock the hips back while watching the low back in a mirror, progressively widening knee and foot stance until the pelvis can rock back with the spine still neutral; the resulting foot width, plus checking foot turnout for knee tracking, is then used as the lifter''s deadlift stance rather than a single cue-based stance for everyone.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Deadlifts Like This (SAVE YOUR SPINE!) ft. Dr. Stuart McGill'),
('equipment', 'elevated-bar deadlift progression for lifters who cannot reach the floor without rounding', 'For lifters whose hip structure prevents a neutral-spine pull from the floor, Ethier/McGill recommend elevating the bar on blocks, pins, or extra plates, holding that height for about a month, then very gradually lowering the start position as mobility and strength allow — reverting to a higher start again if lowering the height reintroduces back pain.', 'practice', 'weak', NULL, '{"reassessment_interval": "~1 month", "note": "revert to higher start if pain returns"}'::jsonb, 'Built With Science (Ethier) — STOP Doing Deadlifts Like This (SAVE YOUR SPINE!) ft. Dr. Stuart McGill'),
('progression', '''broomstick-first'' loading rule for earning deadlift weight', 'They describe a ''Russian'' loading progression for the deadlift: start with an empty broomstick, then an empty bar, then small added plates — advancing to the next load only once perfect neutral-spine form is demonstrated at the current one, rather than loading by feel or ego.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Deadlifts Like This (SAVE YOUR SPINE!) ft. Dr. Stuart McGill'),
('strength-accessories', 'bracing sequence (''lifter''s wedge'') completed before the bar moves', 'McGill''s setup cue is to assume stance and turnout, hinge into a ''short-stop'' position, grip the bar, then push the hands into the bar to create a bending force that locks the low back and lifts the chest slightly — completing this brace fully before adding tension and beginning the pull, rather than bracing and pulling simultaneously.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Deadlifts Like This (SAVE YOUR SPINE!) ft. Dr. Stuart McGill'),
('guideline', 'post-session soreness pattern used to distinguish adaptation from lost bracing', 'Their rule of thumb: if low-back soreness after early deadlift sessions is simply the erectors adapting to a newly-braced position, it should decrease session over session; if soreness instead spikes on a particular day, that is read as a sign the neutral spine was lost during the lift and a cue to review technique before continuing to add load.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Deadlifts Like This (SAVE YOUR SPINE!) ft. Dr. Stuart McGill'),
('strength-accessories', 'contradiction: elite powerlifters intentionally round the back to lift more', 'Ethier states that rounding the back during the deadlift is ''actually a popular method that elite powerlifters often use to lift more weight,'' while still recommending a neutral spine as the safer default for non-elite lifters — i.e., practice at the top of the sport departs from the neutral-spine-only doctrine usually taught to general lifters.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — STOP Doing Deadlifts Like This (SAVE YOUR SPINE!) ft. Dr. Stuart McGill'),
('strength-accessories', 'dedicated lateral-head triceps exercise added after weak-point pressing', 'Ethier reports his own pressing has always been relatively weak and his lateral triceps head lagged behind the other heads; he fixed this by adding a dedicated lateral-head cable extension (arm across the body, cable over the opposite shoulder, elbow pinned in place) for about 10-15 reps, an exercise he sourced from a biomechanics coach rather than inventing himself.', 'practice', 'weak', NULL, '{"reps": "10-15"}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Arms (4 Exercises)'),
('tempo', 'stretch-position exercise choice for biceps', 'Ethier prefers preacher curls over incline curls for biceps growth because the preacher position loads the muscle hardest near full extension/stretch rather than mid-range, citing a study plus reported success from his own program members; he starts trainees light for 10-20 reps in this stretched position before progressing to heavier 8-12 rep work.', 'opinion', 'weak', NULL, '{"initial_reps": "10-20 (lighter)", "progressed_reps": "8-12 (heavier)"}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Arms (4 Exercises)'),
('strength-accessories', 'neutral-grip preacher-style curl to bias brachioradialis/brachialis', 'Ethier recommends performing hammer-style neutral-grip curls on a preacher bench (rather than standing) so the forearm muscles are trained in the same lengthened position emphasized for biceps, and suggests switching to behind-the-body cable hammer curls if the preacher version is too harsh on the elbow tendons even at light loads.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Arms (4 Exercises)'),
('strength-accessories', 'overhead position required to directly train the long head of the triceps', 'Ethier argues flat pressing and pushdowns train the lateral/medial triceps heads well but do little for the long head specifically, because the long head is the only head that crosses the shoulder joint; he recommends an overhead-position exercise (rope, single-arm cable, or Skull Crusher) as the dedicated long-head movement, choosing whichever variation is most comfortable on the elbows, for about 10-15 reps.', 'opinion', 'weak', NULL, '{"reps": "10-15"}'::jsonb, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Arms (4 Exercises)'),
('guideline', 'training/diet/sleep basics prioritized over exercise-selection optimization', 'Ethier states plainly that no amount of exercise-selection science matters if a lifter isn''t training hard enough, eating enough, and sleeping enough — and that fixing those basics will produce far bigger results than optimizing which specific exercises are chosen.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Arms (4 Exercises)'),
('strength-accessories', 'hip-elevating pad setup on the leg curl machine for a deeper hamstring stretch', 'Israetel sets up the prone/seated leg curl with two pads placed under the hips specifically to elevate them, increasing the hamstring stretch at the bottom of the rep compared to the standard machine setup.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Training Legs W/ Dr. Mike Israetel'),
('volume-per-muscle', 'myo-rep-style structure: one near-failure straight set, then mini-sets to match the rep total again', 'Israetel''s leg-curl protocol is a straight set taken to a specific rep count after warm-ups (e.g., 19 reps), followed on the next set by as many short rest-pause ''mini'' sets as needed to reach that same total again, rather than programming fixed straight sets throughout.', 'practice', 'weak', NULL, '{"target_reps": 19, "structure": "1 straight set to target, then myo-reps/mini-sets to re-reach the same target"}'::jsonb, 'Will Tennyson (experiments, self-testing) — Training Legs W/ Dr. Mike Israetel'),
('tempo', 'partial top range with a paused stretch position on leg press/lunge work', 'Israetel cues a controlled ~2-second pause at the bottom (stretched) position combined with stopping about 2/3 of the way up on leg press and reverse-lunge work, treating full lockout as unnecessary on this machine/pattern work in favor of continuous tension.', 'practice', 'weak', NULL, '{"pause_seconds": 2, "top_rom": "~2/3 range, no lockout"}'::jsonb, 'Will Tennyson (experiments, self-testing) — Training Legs W/ Dr. Mike Israetel'),
('strength-accessories', 'full-depth squats adopted after observing depth correlated with better leg development', 'Israetel says he switched from partial/half squats to full-depth (''ass to grass'') squats early in his lifting after seeing a much smaller lifter who squatted to full depth with a high-bar, upright-torso style carry noticeably more muscular quads than partial squatters; he reports the deeper squat also produced categorically more delayed-onset soreness for him personally.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Training Legs W/ Dr. Mike Israetel'),
('strength-accessories', 'strict form preferred over cheat reps, even on isolation exercises near failure', 'Israetel argues lifters should never intentionally break form (e.g., using body English on a barbell curl) even near failure, reasoning that recruiting other muscles (glutes, back) to move the weight takes tension off the target muscle and works against the goal of pushing that specific muscle to its limit; this runs counter to the common bodybuilding practice of allowing some momentum/cheat reps on isolation exercises to extend a set past strict failure.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Training Legs W/ Dr. Mike Israetel'),
('guideline', 'specificity: assistance-exercise strength doesn''t transfer 1:1 to the competition lift', 'Doucette (a former competitive powerlifter) explains his own squat 1RM underperformed relative to his general leg training because he had stopped practicing the free-bar squat itself, invoking the principle of specificity: ''if all you do is leg press and try to do a 1RM squat, you''re not going to be as strong as if you properly practice for the squat.''', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — My Strength Is Gone || Max Deadlift, Squat, And Bench With Will Tennyson'),
('smith', 'contradiction: heavy Smith-machine/hack-squat assistance work with reduced free-bar frequency associated with a stronger free-bar 1RM', 'Will Tennyson reports that the less he directly squats and benches with a free bar — building strength instead through hack squat and Smith-machine bench press — the stronger his actual free-bar squat and bench 1RM become; Doucette calls this counter to straightforward specificity logic but agrees that too much direct volume on a specific lift can itself make a lifter weaker at it (overtraining the pattern), so machine-based assistance work at reduced direct-lift frequency outperformed frequent heavy free-bar practice for his peak strength.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — My Strength Is Gone || Max Deadlift, Squat, And Bench With Will Tennyson'),
('progression', 'competition attempt-depth pacing: conservative depth early, riskiest depth on the last attempt', 'Doucette''s advice for powerlifting meet attempt selection: go slightly higher/more conservative on squat depth on the first (lightest) attempt since success is nearly assured, then go progressively lower (closer to true depth) as the weight increases on later attempts, saving the deepest, most technically demanding depth for the final, heaviest attempt when the lifter is willing to risk missing it.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — My Strength Is Gone || Max Deadlift, Squat, And Bench With Will Tennyson'),
('detraining', 'self-reported strength retention after years without competition-lift-specific practice', 'Doucette retested his 1RMs after roughly 4-5 years without specifically practicing the squat, bench, or deadlift (though he kept training the underlying muscles through other exercises), and reported retaining about 65% of his former squat max, 61% of his former bench max, and 70% of his former deadlift max, estimating he could recover to roughly 80% of his old numbers within one training cycle of resumed specific practice. He attributes the loss partly to this lack of specific practice and explicitly partly to a large reduction in anabolic drug use (from heavy PED use to doctor-prescribed TRT) and to aging into his mid-40s, so these percentages are confounded and should not be read as a clean detraining estimate.', 'practice', 'weak', NULL, '{"squat_retained_pct": 65, "bench_retained_pct": 61, "deadlift_retained_pct": 70, "years_since_specific_practice": "4-5", "est_recoverable_pct_with_resumed_practice": 80, "note": "confounded by concurrent large reduction in PED use and aging into mid-40s; not a clean detraining estimate"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — My Strength Is Gone || Max Deadlift, Squat, And Bench With Will Tennyson'),
('strength-accessories', 'grip width on bench shifts triceps demand, chosen partly around injury history', 'Doucette uses a wide powerlifting-style bench grip partly because of reduced triceps strength after having both triceps surgically reattached, while Tennyson uses a closer grip enabled by strong triceps; Doucette frames grip width as a lever for shifting how much of the bench''s sticking point is borne by the triceps versus the chest/shoulders.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — My Strength Is Gone || Max Deadlift, Squat, And Bench With Will Tennyson'),
('strength-accessories', 'squat pattern strength predicted to transfer more to sumo than conventional deadlift', 'Doucette speculates that a lifter with a very strong squat (like Tennyson) would likely be stronger at the sumo deadlift than the conventional deadlift if he trained sumo specifically, reasoning that the muscle recruitment pattern of a heavy squat overlaps more with sumo mechanics than with conventional pulling mechanics.', 'opinion', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — My Strength Is Gone || Max Deadlift, Squat, And Bench With Will Tennyson'),
('equipment', 'paused reps preferred over touch-and-go for 1RM safety testing', 'For his one-rep-max attempts, Doucette used a paused bench press (holding the bar motionless on the chest) rather than a touch-and-go rep, explicitly because pausing reduces the injury risk that comes from bouncing a heavy bar off the chest to use rebound momentum.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — My Strength Is Gone || Max Deadlift, Squat, And Bench With Will Tennyson'),
('tempo', 'convergence: lengthened/stretched muscle position emphasized as the priority load zone across independent practitioner channels', 'Across three independent channels in this batch — Built With Science/Ethier (preferring preacher curls and overhead triceps extensions because they load the stretched position), Ryan Humiston (shortening the top range of chest flys to keep tension on the stretch), and Dr. Mike Israetel''s team via Will Tennyson (elevating the hips on the leg curl machine specifically to deepen the hamstring stretch) — each independently designs or selects exercise variations to maximize loading in the lengthened muscle position, treating it as the priority training zone rather than the mid-range or peak-contraction position.', 'opinion', 'moderate', NULL, NULL, 'Built With Science (Ethier) — The #1 Workout That BLEW UP My Arms (4 Exercises)'),
('strength-accessories', 'core injury-prevention philosophy', 'Compound bracing exercises alone (sagittal plane) aren''t sufficient core training in his view — most low-back injuries come from twisting (transverse plane) or off-center lifting (frontal plane) that bracing doesn''t address, so after his own back injury he now programs dedicated exercises for the QL, psoas/iliacus, transversus abdominis and obliques in addition to bracing work.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Why Most People Are Training ABS WRONG! (BULLETPROOF CORE) Science Explained!'),
('strength-accessories', 'upper vs lower rectus abdominis targeting', 'To bias the upper abs, keeps the pelvis stationary and flexes the thorax (e.g. cable crunch); to bias the lower abs, keeps the thorax stationary and posteriorly tilts the pelvis (e.g. supported hanging leg raise, exaggerating the posterior pelvic tilt).', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Why Most People Are Training ABS WRONG! (BULLETPROOF CORE) Science Explained!'),
('tempo', 'rectus abdominis short range of motion', 'Treats the rectus abdominis as having a short true range of motion and deliberately shortens crunch/reverse-sit-up ROM to keep tension on the abs, rather than descending into a full sit-up or letting a cable crunch turn into an isometric hold at the bottom — argues full-ROM crunches instead recruit the hip flexors or obliques.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Why Most People Are Training ABS WRONG! (BULLETPROOF CORE) Science Explained!'),
('volume-per-muscle', 'isometric holds and oblique hypertrophy', 'Isometric holds (e.g. banded bird dog, unstable heel-supported bridge) produce meaningful hypertrophy in the internal obliques and transversus abdominis in his view, but not in the external obliques; still holds dynamic contractions as superior for rectus abdominis growth specifically.', 'opinion', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Why Most People Are Training ABS WRONG! (BULLETPROOF CORE) Science Explained!'),
('volume-per-muscle', 'core trained daily, not just on ab day', 'On non-ab training days still opens the session with two isometric core drills — banded bird dogs and a heels-in-TRX unstable bridge — treating core/back injury-proofing as daily maintenance rather than something confined to a dedicated ab day.', 'practice', 'weak', NULL, '{"hold_seconds": 30, "note": "roughly 30 seconds per set, a few sets, done on non-ab days"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Why Most People Are Training ABS WRONG! (BULLETPROOF CORE) Science Explained!'),
('volume-per-muscle', 'no rest between ab-circuit sets', 'Runs his ab circuit with no rest time between exercises, reasoning that abs recover faster than other muscle groups.', 'practice', 'weak', NULL, '{"rest_seconds": 0}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Why Most People Are Training ABS WRONG! (BULLETPROOF CORE) Science Explained!'),
('strength-accessories', 'dorsiflexor warm-up before leg day', 'Starts every leg day with a dorsiflexion warm-up, varying toe angle to bias different lower-leg muscles: toes-in targets the EDL, toes-out targets tibialis anterior; does it with a dumbbell between the feet or a kettlebell held unilaterally when no dedicated tib machine is available.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow Bigger LEGS | BRUTAL LEG DAY (FULL WORKOUT)'),
('strength-accessories', 'unilateral calf raise angle variation', 'After a calf tear forced him to isolate the injured leg, found that turning the toe in or out during unilateral seated/Smith single-leg calf raises let him preferentially feel different heads of the gastrocnemius; recommends experimenting with toe angle on single-leg calf work.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow Bigger LEGS | BRUTAL LEG DAY (FULL WORKOUT)'),
('strength-accessories', 'unilateral squat pattern to expose asymmetries', 'Programs a quad-dominant Bulgarian split squat at the start of every leg day because training one leg at a time exposes asymmetries (uneven ankle mobility, hip tightness, knee tracking, one side dropping into the hip for more glute than quad) that a bilateral squat hides; says fixing form unilaterally carries over to every other quad exercise.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow Bigger LEGS | BRUTAL LEG DAY (FULL WORKOUT)'),
('tempo', 'loaded-stretch rest-pause on leg curls', 'On seated hamstring curls uses a rest-pause set where, instead of releasing the weight between mini-sets, he holds the stretched (lengthened) position for a few breaths before continuing, keeping tension on rather than fully resting.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow Bigger LEGS | BRUTAL LEG DAY (FULL WORKOUT)'),
('tempo', 'heel elevation for quad stretch/bias', 'Elevates the heels (or backs the stance up) on squats and Smith squats to increase the stretch on the quads at the bottom and shift emphasis onto them; this matches Built With Science''s (Ethier) independent recommendation of the same heel-elevation approach for quad bias on squats, leg press and split squats — two independent channels converging on the same technique.', 'practice', 'moderate', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow Bigger LEGS | BRUTAL LEG DAY (FULL WORKOUT)'),
('strength-accessories', 'glute-biased RDL cue', 'To make an RDL train glutes rather than default to hamstrings, cues sitting back into the hips, pausing to feel the stretch under the glutes at the bottom, and driving the hips forward with an active glute contraction on the way up rather than just pulling the bar up.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — How To Grow Bigger LEGS | BRUTAL LEG DAY (FULL WORKOUT)'),
('strength-accessories', 'chest priming with cable/band flyes', 'Opens chest workouts with a cable or band fly-type movement specifically to prime the chest with blood flow before compound pressing, rather than as a finisher, saying this removes the need to consciously cue shoulder position on later sets.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — ABSOLUTE BEST CHEST WORKOUT (Sets & Reps!)'),
('volume-per-muscle', 'angle-cycling density sets on cable chest work', 'Instead of doing 3-4 straight sets of one cable/band chest exercise, changes the exercise angle every set (different handle height, or sliding a bench through incline-to-decline positions) with minimal rest between sets, and reports fitting roughly 7-8 sets into the time most people get through 3-4.', 'practice', 'weak', NULL, '{"typical_sets": "3-4", "his_sets": "7-8", "note": "achieved via minimal rest plus changing exercise angle each set rather than more straight sets"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — ABSOLUTE BEST CHEST WORKOUT (Sets & Reps!)'),
('strength-accessories', 'fixing anterior delt dominance on chest press', 'To stop the anterior delts taking over chest pressing, does a fly variation lying on a bench/floor with a foam roller or Bosu ball wedged into the upper back, actively contracting the rhomboids and traps for the whole set; the reduced ROM is intentional since losing that upper-back contraction is what lets the anterior delts creep back in, and he says it also builds scapular stabilizers over time so the shoulders sit back and down by default.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — ABSOLUTE BEST CHEST WORKOUT (Sets & Reps!)'),
('tempo', 'paused wide push-up finisher', 'Finishes chest workouts with wide-grip push-ups, hands slightly supinated to keep the shoulders back and down, holding the bottom (stretched) position for a 5-count each rep.', 'practice', 'weak', NULL, '{"hold_seconds": 5}'::jsonb, 'Ryan Humiston (physique, exercise selection) — ABSOLUTE BEST CHEST WORKOUT (Sets & Reps!)'),
('periodization', '3-day skill/strength/endurance push-up split', 'Structures a weekly push-up-only chest routine as three distinct stimulus days — a skill day (easier variation, technique practice), a strength day (a harder or eccentric-focused variation), and a muscular-endurance day (EMOM higher-rep work) — modeled on an undulating approach he says was tested in powerlifters, run 3x/week and meant to replace all other chest/triceps work while following it.', 'practice', 'weak', NULL, '{"days_per_week": 3, "note": "skill day / strength day / endurance day"}'::jsonb, 'Built With Science (Ethier) — How To Grow Your Chest With Only Push-Ups (FULL ROUTINE)'),
('tempo', 'max-effort slow eccentric for push-up strength', 'For the strength day in a push-up progression, prescribes 5 sets of just 1 rep of a maximal-effort slow eccentric push-up (lower as slowly as possible from the top), instructing lifters to slow the descent further as it gets easier over time.', 'practice', 'weak', NULL, '{"sets": 5, "reps": 1}'::jsonb, 'Built With Science (Ethier) — How To Grow Your Chest With Only Push-Ups (FULL ROUTINE)'),
('volume', 'EMOM structure for push-up endurance day', 'For a muscular-endurance day, prescribes EMOM push-ups at 50% of one''s max rep count, every minute for 5 minutes total, and increases the per-minute target once that total becomes easy.', 'practice', 'weak', NULL, '{"duration_min": 5, "reps_per_minute_pct_of_max": 50, "protocol": "EMOM"}'::jsonb, 'Built With Science (Ethier) — How To Grow Your Chest With Only Push-Ups (FULL ROUTINE)'),
('progression', 'retest cadence to graduate push-up difficulty tier', 'Has lifters retest their max push-ups every couple of weeks and move to the next difficulty tier once that number improves, rather than progressing on a fixed calendar schedule.', 'practice', 'weak', NULL, '{"retest_interval_weeks": 2}'::jsonb, 'Built With Science (Ethier) — How To Grow Your Chest With Only Push-Ups (FULL ROUTINE)'),
('smith', 'Smith/hack squat for quad isolation', 'Recommends the hack squat or Smith machine squat over free barbell squats specifically to reduce the stabilization demand on the lower back/core, so the quads — not the lower back — become the limiting factor and can be pushed closer to failure; frames this as a deliberate machine choice rather than defaulting to free weight as always superior, noting it matches his own experience of his lower back fatiguing before his quads on barbell squats.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — BIGGER QUADS: 5 Mistakes Keeping Your Legs Skinny'),
('strength-accessories', 'shin angle / knee travel for quad bias', 'A more forward shin angle (more knee travel over the toes) increases quad involvement relative to glutes/lower back; applies this with a low foot placement on leg press (versus standard or high placement) and by letting the knee/shin travel forward on lunges and Bulgarian split squats, especially with front-foot heel elevation — the same heel-elevation-for-quad-bias approach Ryan Humiston independently uses on squats.', 'practice', 'moderate', NULL, NULL, 'Built With Science (Ethier) — BIGGER QUADS: 5 Mistakes Keeping Your Legs Skinny'),
('tempo', 'controlled eccentric when shifting to quad-biased form', 'Warns that quad-biased form (heel elevation, forward shin angle) requires dropping the load substantially — e.g. from 2 plates per side to 1 plate per side on a squat — because the weaker, previously under-loaded quads now take on the work; pairs this with a deliberate 2-3 second eccentric and instructs against letting other muscles cheat the weight up.', 'practice', 'weak', NULL, '{"eccentric_seconds": "2-3", "note": "load typically drops from roughly 2 plates/side to 1 plate/side per leg when switching to quad-focus form"}'::jsonb, 'Built With Science (Ethier) — BIGGER QUADS: 5 Mistakes Keeping Your Legs Skinny'),
('volume-per-muscle', 'rectus femoris needs a hip-locked exercise', 'The rectus femoris (one of the four quad muscles) crosses the hip and is poorly recruited by squats/leg press since the hip doesn''t extend through those lifts; recommends adding a leg extension or sissy squat (knee-only movement, hips locked) at the end of leg day specifically to train it.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — BIGGER QUADS: 5 Mistakes Keeping Your Legs Skinny'),
('guideline', 'proximity to failure specifically on leg day', 'Argues lifters systematically under-push effort on leg day specifically — stopping at the first burn rather than the roughly 3-reps-from-failure mark — more so than on upper-body day, attributing it to how uncomfortable the blood flow into the legs feels.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — BIGGER QUADS: 5 Mistakes Keeping Your Legs Skinny'),
('progression', 'pull-up strength-bracket progression scheme', 'Prescribes a 3-bracket pull-up progression by current max reps: 0-4 reps uses angled inverted-row-style pulls plus assisted negatives with a hold at the top and bottom; 5-7 and 8-9 reps both use submaximal ''grease the groove'' sets (bodyweight or banded); the 8-9 bracket adds a small amount of load or reduces band assistance versus the 5-7 bracket.', 'practice', 'weak', NULL, '{"brackets": "0-4, 5-7, 8-9 reps", "added_weight_lb": 5}'::jsonb, 'Built With Science (Ethier) — Go From 0 to 10 Pull-Ups In A Row (FAST!)'),
('guideline', 'submaximal accumulation over max-effort sets for pull-up strength', 'Coaches never training pull-ups to failure while building strength — do sets of 2-5 reps kept at least 2 reps short of max, resting 30-90 seconds between sets, until 20+ total reps are accumulated (building toward 30), rather than max-effort AMRAP sets that fatigue quickly and yield less total volume; attributes the underlying method to Pavel Tsatsouline.', 'practice', 'weak', NULL, '{"reps_per_set": "2-5", "reps_short_of_failure": 2, "rest_seconds": "30-90", "target_total_reps": "20-30"}'::jsonb, 'Built With Science (Ethier) — Go From 0 to 10 Pull-Ups In A Row (FAST!)'),
('strength-accessories', 'pull-up weak-link accessory work', 'Prescribes a long-lever rocking plank (arms extended overhead, glutes squeezed, rocking the body forward and back) for the core, and a scapular-depression hang (relax the shoulders up to the ears, then pull the shoulder blades down without bending the arms, hold) for the lower traps, as accessory work specifically to remove weak links limiting pull-up strength.', 'practice', 'weak', NULL, '{"hold_seconds": 2}'::jsonb, 'Built With Science (Ethier) — Go From 0 to 10 Pull-Ups In A Row (FAST!)'),
('progression', 'retest cadence for pull-up strength brackets', 'Has lifters retest max pull-ups monthly and move to the next strength bracket once it improves.', 'practice', 'weak', NULL, '{"retest_interval_weeks": 4}'::jsonb, 'Built With Science (Ethier) — Go From 0 to 10 Pull-Ups In A Row (FAST!)'),
('guideline', 'individualize form to anthropometry', 'Argues there is no single ''correct'' squat torso angle, depth or stance — femur length, ankle mobility and hip socket shape determine what form is achievable and safe for a given lifter, e.g. long femurs plus tight ankles force more forward lean, while short femurs plus mobile ankles allow an upright deep squat — demonstrating this with two of his own coaches on camera and treating both as correct for their respective bodies.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('strength-accessories', 'squat stance experimentation', 'Has lifters test 3 squat stances under light load to find their individually comfortable position — narrow/toes-forward, moderate-width/toes-slightly-out, and wide/toes-further-out — noting the wider the stance, the less depth is achievable.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('strength-accessories', 'deadlift bottom-position fix for short arms', 'For lifters with short arms who round their lower back getting into the deadlift start position, recommends elevating the bottom position (e.g. blocks/rack pulls) or switching to a sumo stance.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('equipment', 'machine pivot/handle alignment to reduce joint stress', 'On leg extension/leg curl machines, aligns the machine''s marked pivot point with the knee joint to avoid extra stress above and below the knee; on chest press machines and pec deck, sets seat height so the handles line up with nipple height, which he says produces a more natural pressing path and less elbow/shoulder stress than handles set too high.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('strength-accessories', 'midback engagement cue for rows', 'Cues rows by pressing the shoulders down (not shrugging), pulling with the elbows, and pinching the shoulder blades together ''like trapping a pencil between them,'' then letting them fully open on the return — used on a real coaching client to stop the shoulders rolling forward and the arms doing all the work.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('strength-accessories', 'full scapular range of motion on pulldowns/pull-ups', 'On pulldowns/pull-ups, cues letting the shoulders relax and rise toward the ears at the top of the movement, then pulling with the elbows while driving the shoulders down and away from the ears on the way down, arguing that if only the arms move, the back is barely involved.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('strength-accessories', 'standing shoulder-prehab practice', 'Finishes every upper-body session with 3 sets of face pulls or prone arm circles, and does 10 wall slides every morning and any time he steps away from his desk, as ongoing shoulder-health maintenance rather than rehab after the fact.', 'practice', 'weak', NULL, '{"face_pull_sets": 3, "wall_slide_reps": 10, "frequency": "every morning plus every desk break"}'::jsonb, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('strength-accessories', 'free-rotating exercise per muscle group to offset carrying-angle stress', 'Because the elbow''s natural carrying angle means fixed straight-bar/machine grips force the wrists and elbows into an unnatural line, recommends including at least one exercise per muscle group that lets the hands/forearms rotate freely — dumbbell press for chest/shoulders, single-arm cable rows or pulldowns for back, dumbbell or single-arm cable curls for biceps, cross-body cable pushdowns for triceps — describing this as a fix he adopted after his own wrist-to-elbow-to-shoulder pain from an all-barbell routine.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('progression', 'earn load increases via recovery, don''t force PRs', 'Frames progression as ''earned, not forced'' — you challenge the muscle with a given load and it should come back stronger if recovery was adequate; explicitly advises against chasing a PR on days with poor sleep, missed meals, or general fatigue, citing his wife''s lower-back injury from pushing a squat PR while dehydrated and underslept after a work shift as a cautionary example, and treats matching last week''s reps with better form or less effort as valid progress on an off day.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('periodization', 'review/rotate program every 8-12 weeks for joint health', 'Recommends reviewing your program every 8-12 weeks and swapping out exercises that are starting to irritate a joint (e.g. a favorite chest press machine for a dumbbell press, or changing pull-up grip), reasoning that a single exercise done 2x/week for 3 sets of 12 accumulates roughly 4,000 reps a year, and that cumulative repetitive stress on a fixed movement path — not any one exercise being inherently bad — is what wears joints down.', 'practice', 'weak', NULL, '{"review_interval_weeks": "8-12", "example_annual_reps": 4000, "note": "based on 1 exercise x 2x/week x 3 sets x 12 reps"}'::jsonb, 'Built With Science (Ethier) — Workouts That WRECK Your Joints (I Wish I Knew This Sooner)'),
('strength-accessories', 'side delt exercise selection: stretch position vs standard lateral raise', 'Standard dumbbell lateral raises are hardest at the top (fully contracted) - the opposite of where stretch-mediated hypertrophy research suggests tension should be maximal. Switched primary side-delt exercise to a behind-the-body cable lateral raise, standing slightly in front of and to the side of the low pulley so the delt is under a deep stretch throughout the loaded range.', 'practice', 'weak', NULL, '{"note": "cable positioned so the delt is stretched at the start of the loaded rep, not just contracted at the top"}'::jsonb, 'Built With Science (Ethier) — How I Grew Wider Shoulders FAST (5 Science-Based Tips)'),
('volume-per-muscle', 'low weekly volume for side delts, trained twice weekly', 'Trained side delts only twice per week (not the 3-4x/week his own recovery research suggested was possible) - 4 sets of dumbbell lateral raise one day, 4 sets of cable lateral raise a few days later, 8 total sets/week - and reports this was enough to visibly grow the muscle when paired with a stretch-biased exercise and progressive overload.', 'practice', 'weak', NULL, '{"sets_per_week": 8, "sessions_per_week": 2, "sets_per_session": 4}'::jsonb, 'Built With Science (Ethier) — How I Grew Wider Shoulders FAST (5 Science-Based Tips)'),
('progression', 'double progression rule for lateral raises', 'Progressed lateral raise load only after being able to complete all sets with 15-20 controlled reps; at that point increased by 5 lb (or one notch on the cable stack) and repeated the process. Over 3 months this totaled only about a 5 lb dumbbell increase, framed as a large relative strength gain for that exercise (compared to ~+20 lb on a bench press) because of the longer resistance lever arm involved.', 'practice', 'weak', NULL, '{"rep_threshold_to_progress": "15-20 reps, all sets, good form", "increment_lb": 5, "period_months": 3}'::jsonb, 'Built With Science (Ethier) — How I Grew Wider Shoulders FAST (5 Science-Based Tips)'),
('strength-accessories', 'pushing isolation sets closer to true failure than perceived', 'After deliberately pushing lateral raise sets closer to true failure (within the ~3-5 reps of failure cited as needed for full muscle activation), was able to get about 5 more reps per set than his habitual stopping point despite years of training experience - his read is that most lifters, including experienced ones, stop well short of the effort needed for growth on isolation moves.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — How I Grew Wider Shoulders FAST (5 Science-Based Tips)'),
('strength-accessories', 'close-grip incline bench technique and grip-width individualization', 'Close-grip incline bench press (vs. regular-grip incline) distributes work more evenly across upper pecs, front delts, and triceps rather than being pec/front-delt dominant with triceps left out. Coaching cues: grip width is individualized to body size (larger lifters grip wider, smaller lifters grip narrower) rather than a fixed hand spacing; the form checkpoint is whether the bar touches the upper chest at the bottom of the rep; wrists stay stacked directly over the elbows for maximum pressing strength; the bar is pressed up and back toward the eyes/forehead rather than straight up.', 'practice', 'weak', NULL, '{"note": "grip width individualized by body size; bar-to-upper-chest touch is the form checkpoint"}'::jsonb, 'Built With Science (Ethier) — The 6 Exercises That Grow Every Muscle (ALL YOU NEED)'),
('strength-accessories', 'underhand pull-up for combined back/rear-delt/biceps work', 'Underhand (chin-up grip) pull-up used specifically to add more biceps involvement to a back exercise, hitting lats, rear delts, and biceps in one movement. Cue: full dead-hang at the bottom, letting the shoulders shrug up toward the ears for a complete lat stretch, then actively pulling the shoulders down as the first part of the pull, with a smooth, controlled descent to keep tension through the stretched position.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The 6 Exercises That Grow Every Muscle (ALL YOU NEED)'),
('tempo', '"reach" cue for chest exercises to deepen the stretch position', 'For any horizontal press or fly, cueing the lifter to actively reach the chest toward the bar/handles at the bottom of the rep (rather than letting the weight passively descend) increases stretch and tension at end range. Applied identically across barbell press, dumbbell press, machine press, and flyes, combined with a brief ~1 second pause at the bottom before pressing back up.', 'practice', 'weak', NULL, '{"pause_seconds_at_bottom": 1}'::jsonb, 'Built With Science (Ethier) — The 6 Exercises That Grow Every Muscle (ALL YOU NEED)'),
('strength-accessories', 'combined row + stiff-leg deadlift as a time-efficient multi-muscle exercise', 'Combining a barbell bent-over row with a stiff-legged deadlift into one continuous movement (lower into the SLDL bottom position with a neutral lower back and knees pushed back for hamstring tension, then row to the torso before standing) trains hamstrings, glutes, lower back, and upper back/rear delts in a single exercise. An overhand grip taken slightly wider than shoulder width biases the row toward rear delts and mid/upper back, deliberately complementing an underhand pull-up elsewhere in the same routine (which biases toward lats). Framed as a practical time tradeoff: hitting several muscles at partial effectiveness each beats not training them at all when exercise count or session time is limited.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The 6 Exercises That Grow Every Muscle (ALL YOU NEED)'),
('strength-accessories', 'high-bar vs low-bar back squat selection to balance a routine', 'Chose high-bar back squat (bar above the traps) over low-bar (bar below the traps, intersecting the rear delts) specifically because high-bar keeps the torso more upright and biases the quads more, which was needed to balance a routine that already emphasized the posterior chain via a row+deadlift combo exercise. Low-bar was noted as allowing heavier loads and more back/glute involvement, but judged redundant given the rest of the session.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The 6 Exercises That Grow Every Muscle (ALL YOU NEED)'),
('strength-accessories', 'dumbbell upright row for side delts + traps + forearm flexors, with individual joint-tolerance caveat', 'Used dumbbell upright row (not barbell) to combine side-delt, trap, and forearm-flexor work in one movement - cue is to drive the elbows as high as possible, hold briefly at the top, and control the descent. Path variation changes emphasis: dumbbells further from the body increase side-delt bias, dumbbells closer to the body (dragging up the torso) increase forearm-flexor/bicep involvement. Flagged that the exercise can be uncomfortable on the shoulder joint and traps for some lifters, in which case a standard lateral raise is the recommended substitute.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The 6 Exercises That Grow Every Muscle (ALL YOU NEED)'),
('periodization', 'two-day full-body split alternating heavy and light rep ranges', 'For a minimal 2-day/week full-body program built around 6 compound exercises, recommended structure is: day one all 6 exercises at 5-10 reps (heavier), day two mid-week the same 6 exercises at 10-15 reps (lighter). Rationale given is that alternating loads reduces tendon/joint stress and injury risk versus lifting near-max loads twice a week, and adds psychological novelty versus always chasing the same heavy numbers. Framed as sufficient (two ~1-hour sessions/week) to build a solid natural physique.', 'practice', 'weak', NULL, '{"days_per_week": 2, "day1_rep_range": "5-10", "day2_rep_range": "10-15", "session_length_min": 60}'::jsonb, 'Built With Science (Ethier) — The 6 Exercises That Grow Every Muscle (ALL YOU NEED)'),
('volume-per-muscle', 'individual frequency/volume threshold varies per muscle, not just per person', 'Cites a within-subject leg-training study where one leg trained 2-3x/week showed more growth in some participants than the contralateral leg trained 5x/week on the same person, despite the higher-frequency leg accumulating more total weekly volume. Takeaway applied: each muscle, not just each person, has its own frequency/volume sweet spot, and more training is not reliably better even within the same body.', 'opinion', 'weak', NULL, '{"note": "compared 2-3x/week vs 5x/week for the same muscle, within-subject, contralateral limbs"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Force Muscle Growth (Science Backed Method)'),
('volume-per-muscle', 'personal protocol for bringing up a lagging muscle: escalating frequency plus set reallocation', 'Describes his own protocol for a lagging body part (his case: forearms): train it every 3rd day regardless of whether that falls on an off day or a normal training day, run that for at least 8 weeks before judging results, then increase to 5x/week if progress is judged insufficient. To make room for the added frequency without a large weekly volume increase, sets are pulled (''stolen'') from muscles that already respond fast and need comparatively little stimulus to keep growing.', 'practice', 'weak', NULL, '{"initial_frequency": "every 3rd day", "min_weeks_before_reassessing": 8, "escalated_frequency_per_week": 5}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Force Muscle Growth (Science Backed Method)'),
('progression', 'don''t judge a new training frequency/volume stimulus before roughly 2-3 weeks', 'Argues the first 2-3 weeks of any new or increased training stimulus (new frequency, new volume, new exercise) produce little net hypertrophy because that window is dominated by muscle damage and repair rather than growth; the real hypertrophy signal only shows up once repeated-bout adaptation reduces the damage response. Practical guidance: expect heavy early soreness after a change and don''t treat it as a sign the change isn''t working - wait out the adaptation window before evaluating.', 'opinion', 'weak', NULL, '{"adaptation_window_weeks": "2-3"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — How To Force Muscle Growth (Science Backed Method)'),
('volume', 'veteran lifter reports volume increases still drive his best gains after 20 years', 'Dr. Eric Helms (natural bodybuilder and researcher) reports that every time in his own training career he has pushed his training volume higher, he has seen the fastest muscle gains of that period - including after 20 years of lifting - offered as personal evidence against the idea that volume responsiveness only applies to younger or less-trained lifters.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — Why Some Guys Build Muscle 3x Faster (How You Can Too)'),
('volume-per-muscle', 'tiered guidance for adding volume based on current weekly sets per muscle', 'Recommends tiering volume increases by where a lifter currently sits: under 12 sets/muscle/week, add roughly 20-30% more volume for the biggest expected benefit; 12-20 sets/muscle/week, only add more if form, effort, and recovery are already fully dialed in, since returns shrink; above 20 sets/muscle/week, additional volume is judged not worth the added fatigue cost.', 'opinion', 'weak', NULL, '{"low_tier_sets_per_week": "<12", "low_tier_increase_pct": "20-30", "mid_tier_sets_per_week": "12-20", "high_tier_sets_per_week": ">20"}'::jsonb, 'Built With Science (Ethier) — Why Some Guys Build Muscle 3x Faster (How You Can Too)'),
('volume-per-muscle', 'muscle-group specialization block: ramp focus muscle up, drop everything else to maintenance', 'Describes running a specialization block on his own shoulders (chosen because narrow clavicles left him near a 1:1 shoulder-to-waist ratio vs. an aesthetic target around 1.6): pick 1-2 lagging muscles, start their volume around 10 sets/week trained at least twice weekly, add about 2 sets/week until reaching roughly 20-30 sets/week, and run the block for a few months before reassessing. All other muscle groups are dropped to maintenance during the block: 8-12 sets/week for normal muscles, and as low as 4-6 sets/week for muscles that are already a personal strength.', 'practice', 'weak', NULL, '{"focus_muscle_start_sets_per_week": 10, "focus_muscle_frequency_per_week": 2, "focus_muscle_end_sets_per_week": "20-30", "focus_muscle_weekly_increment": 2, "block_length": "a few months", "maintenance_normal_muscle_sets_per_week": "8-12", "maintenance_strong_muscle_sets_per_week": "4-6"}'::jsonb, 'Built With Science (Ethier) — Why Some Guys Build Muscle 3x Faster (How You Can Too)'),
('female', 'high-volume, high-frequency glute specialization commonly applied to female clients', 'Glute specialist coach Brett Contreras is reported to train clients'' glutes up to 3x/week, with weekly volume sometimes reaching 30-40 sets during specialization phases. The presenter reports training his own (female) partner the same way, describing visible glute growth beyond what she believed her genetics allowed. Presented as a female-client-specific application of the general muscle-specialization-block approach.', 'practice', 'weak', NULL, '{"sets_per_week": "30-40", "frequency_per_week": 3}'::jsonb, 'Built With Science (Ethier) — Why Some Guys Build Muscle 3x Faster (How You Can Too)'),
('progression', 'first-year and long-run natural muscle-gain magnitudes by responder tier', 'Relays a researcher''s (Eric Trexler''s) modeled estimates of natural muscle-gain trajectories by FFMI (fat-free mass index) responder tier: an average responder starting around FFMI 18-19 gains roughly 8-10 lb of muscle in year one, about 5 lb in year two, and progressively less afterward, capping out near FFMI 22-23; a low responder gains roughly half that pace, capping near FFMI 20-21; a high responder can gain 20+ lb in year one and keep gaining steadily for years, eventually exceeding 40 lb over a lifetime and reaching FFMI 24+.', 'opinion', 'weak', NULL, '{"avg_responder_year1_gain_lb": "8-10", "avg_responder_year2_gain_lb": 5, "avg_responder_ffmi_cap": "22-23", "low_responder_ffmi_cap": "20-21", "high_responder_year1_gain_lb": ">20", "high_responder_lifetime_gain_lb": ">40", "high_responder_ffmi_cap": "24+"}'::jsonb, 'Built With Science (Ethier) — Why Some Guys Build Muscle 3x Faster (How You Can Too)'),
('strength-accessories', 'glute training exercise-selection framework', 'Bret Contreras trains glutes for growth using four movement patterns in a session: a lower-body press (squat variant), a lower-body hinge, a squeeze (hip thrust variant), and an abduction/isolation movement.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('strength-accessories', 'squat variant for glute bias', 'To bias a squat toward the glutes rather than the quads, keep shins mostly vertical and push the hips back with more forward torso lean (a ''glute-dominant'' box squat); a more upright torso with knees driving forward biases the quads instead.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('strength-accessories', 'single-leg RDL cue for glute bias', 'On single-leg dumbbell RDLs, keeping the working knee slightly bent rather than locking out to full standing keeps tension on the glutes instead of shifting it to the hamstrings.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('strength-accessories', 'hip thrust technique to avoid low-back pain', 'The most common cause of low-back pain on barbell hip thrusts is hyperextending the spine at lockout; Contreras coaches a ''scoop'' cue — tuck the chin, lead the lockout from the chest down, and tilt the pelvis up by squeezing the glutes — which shortens top-end range slightly but removes the lumbar hyperextension.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('volume', 'low-fatigue accessory volume (''penalty-free volume'')', 'Contreras treats machine hip abduction as ''penalty-free volume'' — an exercise that adds hypertrophy stimulus without meaningfully adding fatigue or soreness, useful for stacking extra volume without hurting recovery from harder lifts.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('clinical', 'exercise selection rule for lifters with low-back pain', 'Contreras''s rule of thumb when programming around a back injury: if a movement feels off or produces any pain during the rep itself, skip it and substitute rather than pushing through.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('volume-per-muscle', 'contradiction: very high weekly glute set volume for advanced growth', 'Contreras says clients chasing maximum glute growth train up to 30-40 hard sets per week for glutes; this is well above the roughly 10-20 sets/week per muscle typically cited as the upper range in mainstream hypertrophy volume guidance, though glutes may tolerate more volume than smaller muscle groups.', 'practice', 'weak', NULL, '{"sets_per_week": "30-40", "note": "Contreras''s stated ceiling for clients chasing maximum glute growth; conflicts with the lower weekly-volume ceilings usually cited for most muscles"}'::jsonb, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('volume-per-muscle', 'training frequency increase for advanced glute growth vs injury risk', 'Moving a trainee from 2x/week to 3x/week glute sessions produced faster visible growth but also enough cumulative fatigue/tightness to trigger a back flare-up in a previously injured lifter; the coaching decision was to hold at 2x/week rather than 3x/week, trading some growth rate for durability.', 'practice', 'weak', NULL, '{"note": "2x/week held as the safer frequency vs 3x/week after a back-tightness flare-up in a trainee with a prior back injury"}'::jsonb, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('female', 'sex difference in lower-body training recovery', 'Contreras reports observing, across his client base, that women tend to recover faster from lower-body training than men and can tolerate more glute training volume and frequency.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('periodization', 'specialization by reducing competing volume', 'Ethier states that when he wanted to grow his shoulders, cutting volume everywhere else and concentrating it on shoulders produced his fastest shoulder growth ever, reasoning that fewer competing muscle-group priorities lets the body direct more recovery resources to one area; he explicitly notes this hasn''t actually been studied.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('detraining', 'short layoff causes flatness, not muscle loss', 'A week or two off training makes muscles look flatter due to reduced glycogen (and the water it pulls into the muscle), not actual muscle loss; he cites research suggesting it takes at least 3 weeks of no training before real muscle loss begins.', 'opinion', 'weak', NULL, '{"weeks_before_muscle_loss": "3+"}'::jsonb, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('strength-accessories', 'hip thrust vs squat for glute growth', 'Contreras cites his own 2023 study comparing squats to hip thrusts: squats produced more quad and inner-thigh growth, but the two exercises produced equal glute growth.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — I Transformed My Wife''s Body In 90 Days'),
('strength-accessories', 'elbow angle for chest-dominant pressing', 'To keep tension on the chest rather than the front delts during pressing, tuck the elbows to roughly a 45-60 degree angle from the torso on the way down so the bar drifts down and back toward nipple level, instead of flaring the elbows out; a grip about 1.5x shoulder width helps prevent flare.', 'practice', 'weak', NULL, '{"elbow_angle_deg": "45-60", "grip_width_x_shoulder_width": 1.5}'::jsonb, 'Built With Science (Ethier) — THICKER CHEST: 4 Mistakes Keeping You Small'),
('strength-accessories', 'shoulder setup cue for chest-dominant bench press', 'Before pressing, pull the shoulders down away from the ears and retract the shoulder blades (cue: pinch a pencil between them) to create a thoracic arch that keeps the chest, not the front delts, in the loaded position; maintain the retraction on the way down, allowing slight opening at the top as long as the shoulders don''t roll forward or shrug up.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — THICKER CHEST: 4 Mistakes Keeping You Small'),
('strength-accessories', 'pre-press mobility/activation drills for chest', 'Before pressing, 2 sets of 5-10 band pull-aparts (or overhead arm extensions behind the back) plus a prone W-Y-T mid-back activation drill for 6 reps helps open a rounded/hunched chest position and wake up the mid-back muscles that support upright pressing posture.', 'practice', 'weak', NULL, '{"pull_apart_sets": 2, "pull_apart_reps": "5-10", "wyt_reps": 6}'::jsonb, 'Built With Science (Ethier) — THICKER CHEST: 4 Mistakes Keeping You Small'),
('strength-accessories', 'mind-muscle connection cue for chest pressing', 'Cueing pressing as ''pulling the arms together'' (horizontal adduction — bringing the bicep toward the inner pec) rather than ''pushing the weight up'' is used to increase felt chest activation during bench press, dumbbell press, and push-ups.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — THICKER CHEST: 4 Mistakes Keeping You Small'),
('progression', 'form-based autoregulation cue for chest pressing load', 'If the elbows want to flare out uncontrollably during a chest-focused press despite cueing them tucked, that is treated as a sign the load is too heavy for the chest to control at that setup and should be lowered, rather than letting the shoulders/triceps take over the rep.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — THICKER CHEST: 4 Mistakes Keeping You Small'),
('strength-accessories', 'shoulder press angle for anterior delt stretch', 'Standard vertical shoulder presses (dumbbell, barbell, or Smith, pressing straight overhead) don''t load the anterior delt at a long muscle length and are considered a weak anterior-delt exercise regardless of range of motion used; pressing on an incline bench around 60 degrees with a close grip, elbows tucked, and stopping the press once triceps take over instead gives a much better anterior-delt stretch and is his preferred setup.', 'practice', 'weak', NULL, '{"incline_bench_angle_deg": "~60"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Science-Backed Shortcut for Massive Side and Front Delts!'),
('strength-accessories', 'front raise variation for anterior delt isolation', 'A standard dumbbell front raise mostly trains the clavicular head of the pec, not the anterior delt, because the pec fibers are the better flexor along that line of pull; using a cable at roughly 45 degrees with the forearm externally rotated/supinated is described as isolating the anterior delt much better.', 'practice', 'weak', NULL, '{"cable_angle_deg": "~45"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Science-Backed Shortcut for Massive Side and Front Delts!'),
('strength-accessories', 'lateral raise hand rotation for delt bias', 'Internally rotating the humerus (pronating the palms, thumbs pointed down) during a side lateral raise reduces involvement of the supraspinatus (rotator cuff) and shifts more load onto the lateral deltoid fibers compared to the standard neutral-palm lateral raise.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Science-Backed Shortcut for Massive Side and Front Delts!'),
('strength-accessories', 'scapular protraction cue for lateral raise stretch', 'Protracting the scapula (flaring the lat) before starting a lateral raise rep is used as a ''wedge'' that skips the initial rotator-cuff-dominant range of the movement and gives a deeper stretch on the lateral deltoid fibers at the start position.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Science-Backed Shortcut for Massive Side and Front Delts!'),
('strength-accessories', 'unilateral vs bilateral machine lateral raise', 'Performing machine lateral raises one arm at a time lets the lifter internally rotate the arm, lean the torso back, and angle into the scapular plane more effectively than the standard bilateral setup, which he says produces a much stronger delt stimulus from an otherwise ordinary machine.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — Science-Backed Shortcut for Massive Side and Front Delts!'),
('tempo', 'contradiction: capping lateral raise range of motion below full abduction', 'He caps lateral raises at roughly 90 degrees of abduction and argues raising higher mostly recruits the traps rather than the delt in lifters without fine scapular control — a stance he explicitly contrasts with other coaches who train laterals through a fuller overhead range on the reasoning that the delt can produce more force around 120 degrees of abduction.', 'opinion', 'weak', NULL, '{"lateral_raise_rom_cap_deg": "~90"}'::jsonb, 'Ryan Humiston (physique, exercise selection) — Science-Backed Shortcut for Massive Side and Front Delts!'),
('strength-accessories', 'shoulder press variation with best EMG activation', 'The program he followed cites standing dumbbell shoulder press as having the best EMG delt activation among standing barbell, seated barbell, and seated dumbbell shoulder press variations, even though it doesn''t allow the most weight to be lifted.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — World''s Most Productive Day To Build Muscle (Science Says)'),
('tempo', 'paused reps to break a bench press plateau', 'Adding a dead-stop pause at the bottom of the flat bench press removes the stretch reflex and forces re-engagement each rep, which requires reducing the working weight initially; building back up to touch-and-go loads after a block of paused training is used as a way to break through a stalled bench press.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — World''s Most Productive Day To Build Muscle (Science Says)'),
('progression', 'set count scaling by training experience', 'In the program followed, working sets for main lifts were prescribed as a range (e.g. 3-4 sets), with beginners directed to the low end and more advanced lifters to the high end of the same exercise.', 'practice', 'weak', NULL, '{"beginner_sets": 3, "advanced_sets": 4}'::jsonb, 'Will Tennyson (experiments, self-testing) — World''s Most Productive Day To Build Muscle (Science Says)'),
('clinical', 'reverse wall angel regression for weak mid-back', 'In the reverse wall angel drill (kneeling at a wall, arms sweeping overhead in a circle), if the movement is felt in the upper traps rather than the mid-back, that is treated as a sign the mid-back muscles aren''t yet strong enough to control the movement upright, and the drill should be regressed to lying on the floor or a bench until it is felt in the correct muscles.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The PERFECT 5 Minute Posture Routine To Increase Your Height'),
('clinical', 'deep neck flexor strengthening for forward head posture', 'A small, controlled chin-tuck exercise (pulling the chin straight back without tilting the head, holding for 1 second, optionally adding a downward chin tuck at the end) is used to strengthen the deep neck flexors; he cites a 2021 review in which every study on deep neck flexor strengthening reported improvement in forward head posture.', 'opinion', 'weak', NULL, '{"hold_seconds": 1}'::jsonb, 'Built With Science (Ethier) — The PERFECT 5 Minute Posture Routine To Increase Your Height'),
('guideline', 'dosing for a corrective mobility routine', 'The prescribed dosing for this posture/mobility routine is 1 minute per exercise, done 1-2 times per day, with an emphasis on slow, controlled quality reps over rep count.', 'practice', 'weak', NULL, '{"minutes_per_exercise": 1, "sessions_per_day": "1-2"}'::jsonb, 'Built With Science (Ethier) — The PERFECT 5 Minute Posture Routine To Increase Your Height'),
('strength-accessories', 'bench press elbow angle and bar path', 'Recommends a tucked, ''arrow-shaped'' elbow angle (roughly 60 degrees, individually variable) rather than flared elbows on the bench press, arguing this lets the bar travel deeper and better matches chest fiber direction while a wide/flared angle shifts tension to the shoulders. Recommends self-checking elbow angle via bar path rather than measuring angle directly: the bar should travel slightly forward on the way down and slightly back on the way up, touching the lower chest/nipple line.', 'opinion', 'weak', NULL, '{"elbow_angle_deg": 60, "note": "individual variation expected; judge by bar path, not a fixed angle"}'::jsonb, 'Built With Science (Ethier) — The Worst Bench Press Mistakes Everyone Makes (Avoid These)'),
('smith', 'Smith machine bench press bar path and setup', 'On an angled Smith machine, recommends facing the direction the bar path is angled so the bar moves down-and-forward like a free-weight bench and touches the lower chest/sternum; on a purely vertical (non-angled) Smith machine, recommends positioning so the bar lands higher, around mid-chest, since no forward bar-path can be created mechanically.', 'opinion', 'weak', NULL, '{"note": "angled Smith: touch point = lower chest/sternum; vertical Smith: touch point = mid chest"}'::jsonb, 'Built With Science (Ethier) — The Worst Bench Press Mistakes Everyone Makes (Avoid These)'),
('strength-accessories', 'bench press grip width self-test', 'Recommends finding grip width by resting the bar at the lower-chest touch point: if forearms angle inward the grip is too narrow (more triceps involvement), if forearms angle outward it is too wide (less chest involvement, and in his experience associated with higher shoulder-injury risk, common in powerlifting-style wide grips). Correct width is where wrist, forearm, and elbow stack vertically under the bar at the bottom.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Worst Bench Press Mistakes Everyone Makes (Avoid These)'),
('strength-accessories', 'bench press chest-dominant execution cues', 'To keep the chest (not the front delts) doing the work, cues: create a proud/up chest before unracking, pull the bar down as if performing a row while retracting the shoulder blades, then on the ascent think of squeezing the biceps together (horizontal adduction) rather than punching straight up. Ran an informal self/partner EMG comparison (n=2) finding this cue set increased chest activation and reduced front-delt activation versus letting the chest cave and shoulders roll forward.', 'practice', 'weak', NULL, '{"note": "informal EMG comparison on 2 subjects (self + training partner), proper vs improper form at matched relative load"}'::jsonb, 'Built With Science (Ethier) — The Worst Bench Press Mistakes Everyone Makes (Avoid These)'),
('equipment', 'bench press substitution when shoulder pain persists', 'If bench press aggravates the shoulder even after technique fixes, recommends switching to chest machines, dumbbells, or a shortened range of motion (stopping an inch or two short of the chest) rather than forcing full-ROM barbell bench, citing a 2023 meta-analysis and a separate 2023 study finding no significant hypertrophy difference between free weights and machines (e.g. Smith machine).', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Worst Bench Press Mistakes Everyone Makes (Avoid These)'),
('strength-accessories', 'preacher curl grading and injury caution', 'Greg Doucette rates the barbell/EZ-bar preacher curl highly (A), doing it every workout for full-stretch control and because it doesn''t aggravate his lower back like standing curls. Co-host Eric rates it lower (B+), citing elevated injury risk at the fully-stretched bottom position under heavy load (referencing a viral case of someone tearing both biceps simultaneously during a heavy preacher curl), and recommends using lighter loads with a controlled ~6-second negative and pause at the bottom instead of going heavy.', 'practice', 'weak', NULL, '{"eccentric_seconds": 6, "note": "recommended for preacher curl safety at the stretched position"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Barbell Curl Is A BAD Biceps Exercise'),
('tempo', 'slow eccentric and full range of motion on isolation curls', 'Both speakers independently emphasize a slow, controlled eccentric (Eric specifies roughly 6-second negatives) paired with a full stretch and a hard peak squeeze as core to their bicep training and to injury avoidance, particularly on preacher and incline curls. Doucette states as a general principle that adding a slower negative and more range of motion to virtually any exercise helps hypertrophy.', 'practice', 'moderate', NULL, '{"eccentric_seconds": 6}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Barbell Curl Is A BAD Biceps Exercise'),
('strength-accessories', 'neutral-grip vs supinated curl preference', 'Both speakers independently rate dumbbell hammer curls (neutral grip) lower than supinated dumbbell curls for bicep hypertrophy, reasoning that the neutral grip limits achievable range of motion (less bottom stretch, less peak-contraction squeeze) and shifts emphasis toward forearm/brachialis thickness rather than the biceps peak; both prefer supinated variations, especially on an incline, as their go-to bicep builder.', 'practice', 'moderate', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Barbell Curl Is A BAD Biceps Exercise'),
('strength-accessories', 'incline pinned-elbow supinated curl', 'Greg Doucette''s favorite bicep exercise is a seated incline dumbbell curl performed with the elbows pinned behind the torso and held stationary through the whole rep (''biceps on an island''); says this removes front-delt involvement because the elbow can''t travel forward into a front-raise-like pattern, and reports doing this near-daily as one of his training staples.', 'practice', 'weak', NULL, '{"note": "performed almost every session"}'::jsonb, 'Greg Doucette (IFBB pro, coaching content) — The Barbell Curl Is A BAD Biceps Exercise'),
('strength-accessories', 'standing barbell curl vs lying cable curl', 'Greg Doucette rates the standing barbell curl low (C), arguing that at the top of the rep the bar sits well in front of the body, creating a long lower-back-loading moment arm during a heavy eccentric; he prefers a lying (floor) cable curl, which keeps constant tension from below with no lower-back involvement, an easier full-stretch eccentric hold, and no usable momentum, and says he uses it specifically to manage his own recurring low-back issues. Co-host Eric partially disagrees, noting the standing barbell version lets most lifters push harder effort-wise (''ego load'') than a cable curl, which requires more mental effort to reach the same intensity.', 'practice', 'weak', NULL, NULL, 'Greg Doucette (IFBB pro, coaching content) — The Barbell Curl Is A BAD Biceps Exercise'),
('progression', 'novice linear progression with microplates', 'Recommends beginners add 5 lb to every major lift every week (novice linear progression) until progress stalls, then switch to fractional microplates (1.25 lb per side instead of 2.5 lb) to slow the rate of increase and extend how long linear progression can continue.', 'opinion', 'weak', NULL, '{"weekly_increment_lb": 5, "microplate_increment_lb_per_side": 1.25}'::jsonb, 'Will Tennyson (experiments, self-testing) — Beginner''s Gym Survival Guide'),
('guideline', 'beginner full-body compound program', 'Recommends beginners train full-body, compound-lift-focused, 3 days per week (e.g. Monday/Wednesday/Friday) with a rest day between sessions, working in a 5-8 rep range, and avoiding isolation/machine exercises while still building a base.', 'opinion', 'weak', NULL, '{"days_per_week": 3, "rep_range": "5-8"}'::jsonb, 'Will Tennyson (experiments, self-testing) — Beginner''s Gym Survival Guide'),
('volume', 'low training volume for novice lifters', 'Recommends low volume for novice lifters (e.g. only 3 sets for the main back/row exercise per session), based on his own early-training experience that doing more volume did more harm than good; argues a beginner focusing on a few effective compound exercises at low volume will progress and look better than one doing high-volume routines.', 'practice', 'weak', NULL, '{"sets": 3, "note": "main row/back exercise for a novice lifter"}'::jsonb, 'Will Tennyson (experiments, self-testing) — Beginner''s Gym Survival Guide'),
('volume-per-muscle', 'pull-to-push volume ratio for posture and bench stability', 'Recommends beginners perform roughly double the pulling volume relative to pushing volume (upper back and rear delt work) to counteract chest/shoulder-dominant training habits, improve posture, and build the stabilization needed for a stronger bench press.', 'opinion', 'weak', NULL, '{"pull_to_push_ratio": "2:1"}'::jsonb, 'Will Tennyson (experiments, self-testing) — Beginner''s Gym Survival Guide'),
('strength-accessories', 'squat as sole beginner lower-body exercise', 'Argues a beginner needs only the squat as their main lower-body movement to build the entire lower body, rather than adding multiple leg-isolation exercises to an early program.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Beginner''s Gym Survival Guide'),
('progression', 'workout logging for progressive overload', 'Reports he made much faster progress once he started logging every workout (weights and reps, phone notes or a notepad) to track progressive overload; says he trained for years without logging early in his career and regrets it, seeing a near-immediate jump in results once he began tracking.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Beginner''s Gym Survival Guide'),
('strength-accessories', 'leg press foot placement for glute vs quad emphasis', 'Recommends placing the feet higher on the leg press platform and stopping each rep around 90 degrees of knee flexion to keep the shin more vertical and increase hip extension, shifting more work to the glutes; a lower foot placement increases quad activation instead. Cites muscle-activation studies comparing foot stances as the basis.', 'opinion', 'weak', NULL, '{"knee_angle_deg": 90, "note": "higher foot placement favors glutes, lower placement favors quads"}'::jsonb, 'Built With Science (Ethier) — ROUNDER GLUTES: 5 Mistakes Keeping Your Butt Flat'),
('strength-accessories', 'torso and shin angle for glute-dominant squats and split squats', 'A more forward-leaning torso combined with a more vertical shin (versus an upright torso with a forward-traveling shin) increases hip extension and shifts squats, lunges, and Bulgarian split squats toward glute dominance over quad dominance. Recommends a wider stance with a forward hip-hinge (neutral spine) to bias Bulgarian split squats toward the glutes.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — ROUNDER GLUTES: 5 Mistakes Keeping Your Butt Flat'),
('strength-accessories', 'Romanian deadlift depth cue for glute emphasis', 'On the RDL, recommends stopping the descent where the hips stop moving backward (the personal limit of hip mobility) rather than using a fixed range of motion — going lower causes the lower back to round and shifts tension off the glutes onto the spine. Also recommends allowing some knee bend, since fully locked straight legs shift emphasis toward the hamstrings and away from the glutes.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — ROUNDER GLUTES: 5 Mistakes Keeping Your Butt Flat'),
('volume-per-muscle', 'pairing stretch-position and shortened-position exercises', 'Recommends pairing exercises that load a muscle at end-range stretch (for glutes: squats, RDLs, Bulgarian split squats, leg press, all of which have little tension at lockout) with at least one exercise that loads the muscle at full contraction/shortened position (hip thrusts, 45-degree hip extensions), reasoning that training across both ends of the length-tension curve may produce more complete regional growth than a stretch-only approach.', 'opinion', 'weak', NULL, '{"note": "suggested split: 1-2 stretch-position exercises plus 1 shortened-position exercise per glute session"}'::jsonb, 'Built With Science (Ethier) — ROUNDER GLUTES: 5 Mistakes Keeping Your Butt Flat'),
('strength-accessories', 'pre-training glute activation work', 'Recommends dedicated low-load glute activation exercises before the main workout to improve neural recruitment/mind-muscle connection of the glutes during compound lifts, aimed particularly at people who sit a lot and struggle to feel their glutes working during squats and hip hinges.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — ROUNDER GLUTES: 5 Mistakes Keeping Your Butt Flat'),
('volume-per-muscle', 'training frequency and effort during a fat-loss phase', 'To maximize the odds of building muscle while in a calorie deficit (body recomposition), recommends training each muscle group at least twice per week with sufficient volume, and taking most sets to within about 3 reps of failure (possibly closer, citing an unreviewed pre-print) — i.e. the same frequency/effort standards as a normal muscle-building phase, not a different protocol.', 'opinion', 'weak', NULL, '{"min_frequency_per_week": 2, "proximity_to_failure_reps": 3}'::jsonb, 'Built With Science (Ethier) — How to Lose Fat AND Gain Muscle At The Same Time (Step By Step)'),
('guideline', 'load/rep range equivalence when effort is matched', 'Cites a study of 130 trained subjects finding heavy-weight/low-rep and light-weight/high-rep training produced similar fat loss and similar (small) muscle gain during a calorie deficit, provided effort (proximity to failure) was equated between groups — concludes that rep-range/load selection matters less than total effort and volume.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Lose Fat AND Gain Muscle At The Same Time (Step By Step)'),
('periodization', 'bulk/cut cycling vs recomposition among physique athletes', 'Observes that no professional bodybuilder, natural or enhanced, tries to build their physique through body recomposition — they instead cycle discrete bulking and cutting phases and improve year over year — implying recomp is not the periodization strategy of choice once maximizing muscle growth is the priority, even though recomposition is physiologically achievable for beginners, detrained lifters, or higher-bodyfat individuals.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — How to Lose Fat AND Gain Muscle At The Same Time (Step By Step)'),
('detraining', 'faster muscle regrowth after a training layoff', 'Claims muscle lost during a break from training regrows faster than it originally took to build (''muscle memory''), such that someone returning from a layoff can simultaneously add back muscle and lose fat (recomposition) within the first couple of months, even with little net change in bodyweight — illustrated with an anecdotal coaching-client case, not a controlled study.', 'opinion', 'weak', NULL, '{"note": "anecdotal single case, roughly first 2 months back after a layoff"}'::jsonb, 'Built With Science (Ethier) — How to Lose Fat AND Gain Muscle At The Same Time (Step By Step)'),
('strength-accessories', 'bench grip width and strength/muscle bias', 'Ryan Humiston (natural competitive powerlifter/bodybuilder) uses a wider-than-shoulder bench grip; widening the grip by even 1-2 inches shortens the range of motion and can instantly increase bench press load by roughly 5-10%, with wider grip biasing pec involvement and narrower grip biasing triceps — he suggests picking grip width to match individual strengths (e.g. a lifter with strong triceps may benefit from going narrower) rather than using one fixed grip.', 'practice', 'weak', NULL, '{"grip_width_increase_in": "1-2", "bench_load_increase_pct": "5-10"}'::jsonb, 'Built With Science (Ethier) — The Fastest Way to Blow Up Your Bench (Using Science)'),
('strength-accessories', 'bench sticking-point-specific accessory selection', 'Elite bencher Ryan Humiston diagnoses where a lifter fails on bench (off-the-chest, mid-range, or lockout) and pairs the weak point with a specific accessory: off-chest/bottom weakness gets dips plus explosive ''speed bench'' work; mid-range weakness gets overhead/shoulder pressing plus a pause bench (pause on the chest, pause again partway up, then lock out); lockout weakness gets close-grip bench press or a partial ''spoto press''-style movement to isolate the triceps through a longer range of motion.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Fastest Way to Blow Up Your Bench (Using Science)'),
('strength-accessories', 'powerlifting arch trade-off vs hypertrophy work', 'A large competition-style bench arch shortens the bar path from top to bottom the same way a wider grip does, boosting the max weight that can be pressed, but at the cost of reduced chest range of motion; Ryan Humiston offsets this by pairing his heavy flat-arch bench work with separate bodybuilding-style chest accessories (incline dumbbell press, cable flys, dips) done through a fuller range of motion specifically to drive chest size that the competition bench technique doesn''t provide.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — The Fastest Way to Blow Up Your Bench (Using Science)'),
('volume-per-muscle', 'contradiction: bench frequency for advanced lifters', 'Ryan Humiston, benching 400+ lb, now does his heavy top-set bench only once per week, saying that at his load level a single hard bench session takes roughly two weeks to fully recover from and that benching more often was ''bearing down on my joints'' and killing his enjoyment of training. This conflicts with the more common strength/hypertrophy finding held elsewhere at higher confidence that per-lift/per-muscle training frequencies of 2-3x/week outperform 1x/week even for experienced lifters; his own video concedes beginner research shows higher frequency doubles strength gains, and frames his low-frequency approach as something advanced lifters should self-test (e.g. 6 weeks high-frequency vs 6 weeks low-frequency) rather than assume.', 'practice', 'weak', NULL, '{"frequency_per_week": 1, "recovery_time_at_near_max_load_weeks": 2}'::jsonb, 'Built With Science (Ethier) — The Fastest Way to Blow Up Your Bench (Using Science)'),
('progression', 'sustaining motivation under slow strength progression', 'At his current strength level, Ryan Humiston considers +1 lb of bench progress per month a good outcome; to stay motivated despite the main lift progressing slowly, he tracks and chases PRs on secondary movements (dips, presses, flys) every session so there is almost always something progressing even on weeks the main bench lift doesn''t move.', 'practice', 'weak', NULL, '{"target_progress_lb_per_month": 1}'::jsonb, 'Built With Science (Ethier) — The Fastest Way to Blow Up Your Bench (Using Science)'),
('clinical', 'self-directed shoulder impingement exercises', 'For a shoulder that felt ''jammed'' in certain positions and didn''t respond to standard internal/external rotation cuff work, Ryan Humiston found relief with two self-devised movements: a light ''flat shoulder press'' (lying on a flat bench, pressing a light dumbbell overhead and letting it pull the elbow down into a pec/rotator-cuff stretch, starting as light as 5 lb) and a behind-the-back triceps extension (hands positioned behind the back, forcing internal rotation while extending the elbow) aimed at opening up tight posterior shoulder muscle.', 'practice', 'weak', NULL, '{"note": "start with about 5 lb dumbbell on the flat shoulder press"}'::jsonb, 'Built With Science (Ethier) — The Fastest Way to Blow Up Your Bench (Using Science)'),
('strength-accessories', 'rear delt cueing — protraction not elevation', 'When trying to put the rear delt at a long, stretched length during flies/rows, cue scapular protraction (visualized as wrapping the scapula around the rib cage) rather than scapular elevation; letting the shoulder blade elevate hands the movement off to the upper traps instead of the posterior delt.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The Science-Backed Shortcut to Boulder Shoulders – It''s Insane!'),
('strength-accessories', 'rear delt exercise selection — bent arm to bias delt over lat', 'Keeping the arm bent and close to the torso during rear-delt raises/rows (rather than straight-armed) biases the posterior delt over the lat/teres major, because a straight arm increases the lat''s mechanical advantage at that joint angle; his top-rated rear delt movement is a chest-supported/incline single-arm variation with the arm kept close and bent, reaching out for a stretch at the bottom and squeezing back — done as a length-focused partial rather than a full range-of-motion rep.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The Science-Backed Shortcut to Boulder Shoulders – It''s Insane!'),
('strength-accessories', 'avoid raising the arm above shoulder height for rear delt work', 'High cable rear-delt flies, where the arm is raised above the head/shoulder line, force heavy trap involvement because the traps have to tilt the scapula upward at that height; he avoids this exercise entirely and keeps rear delt raises at or below roughly shoulder height (about 90 degrees of arm elevation) to keep the traps out of it.', 'practice', 'weak', NULL, '{"max_arm_elevation_deg": 90}'::jsonb, 'Ryan Humiston (physique, exercise selection) — The Science-Backed Shortcut to Boulder Shoulders – It''s Insane!'),
('strength-accessories', 'lat pullover arm bend', 'Doing straight-arm pullovers to target the lats can instead load the teres major/shoulder joint uncomfortably; bending the arms more during pullover-style lat work shifts the emphasis more effectively onto the lats and off the smaller shoulder stabilizers.', 'practice', 'weak', NULL, NULL, 'Ryan Humiston (physique, exercise selection) — The Science-Backed Shortcut to Boulder Shoulders – It''s Insane!'),
('strength-accessories', 'biceps exercise selection — reverse/lying preacher curl for full length-tension coverage', 'Multiple bodybuilding coaches (pro natural bodybuilder Alberto Nunes and researcher/coach Daniel Plainview) favor a reverse/lying preacher curl — leaning back on a wide preacher bench so the upper arm sits near or behind the torso midline — because it combines the deep stretch position of incline curls with the demanding bottom-position load of a standard preacher curl, and the arm support also prevents using body momentum to cheat the rep.', 'practice', 'moderate', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Massive Arms'),
('strength-accessories', 'flat-bench dumbbell curl for maximum stretch loading', 'Dr. Mike Israetel''s top biceps pick is a flat-bench-supported lying dumbbell curl performed for maximum stretch at long muscle length under load — he compares the sensation to a stiff-leg deadlift for hamstrings; the trade-off is it needs more shoulder mobility and offers less stability than a preacher bench, so lighter loads are used (e.g. about 30 lb vs about 55 lb on standard curls) and a side-lying/bench-supported variation is used as a more stable regression.', 'practice', 'weak', NULL, '{"note": "use notably lighter load than standard curls, e.g. ~30 lb vs ~55 lb"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Massive Arms'),
('strength-accessories', 'overhead triceps extension preferred over pushdowns', 'Multiple coaches (Alberto Nunes, Daniel Plainview, Dr. Mike Israetel, and an unnamed biomechanics coach) independently named some form of overhead cable or dumbbell triceps extension as their single go-to triceps exercise over pushdowns/close-grip presses, reasoning that it''s the movement that stretches the long head of the triceps under load; they differ on the exact variation (rope, straight bar, or single-arm dumbbell) mainly based on which feels most comfortable on their own elbow/shoulder.', 'practice', 'moderate', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Massive Arms'),
('clinical', 'elbow wear from behind-the-neck skull crushers', 'In coaches'' experience, full bar-behind-the-head skull crushers are associated with elbow joint wear over years of use; most lifters past their early 30s move away from that variation toward cable-based triceps extensions specifically to protect their elbows.', 'opinion', 'weak', NULL, NULL, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Massive Arms'),
('volume-per-muscle', 'dosing for top arm accessory exercises', 'Recommended dosing for the top bicep/triceps picks (reverse preacher/lying curl and overhead triceps extension) is 3 sets of 10-15 reps, performed 1-2x per week, added on top of existing pressing and pulling work rather than replacing it.', 'opinion', 'weak', NULL, '{"sets": 3, "reps": "10-15", "frequency_per_week": "1-2"}'::jsonb, 'Built With Science (Ethier) — The ONLY 2 Exercises You Need For Massive Arms'),
('volume-per-muscle', 'preference for 2x/week frequency over a bro split', 'Will Tennyson trains each muscle group twice per week rather than following a classic once-per-week ''bro split''; in his experience, a true once-per-week split tends to mean that muscle group eventually gets skipped or missed altogether rather than reliably trained hard once.', 'practice', 'weak', NULL, '{"preferred_frequency_per_week": 2}'::jsonb, 'Will Tennyson (experiments, self-testing) — I Paid A Stranger $13 To Make Me A Diet & Workout Program'),
('progression', 'conservative loading on unfamiliar high-volume programming', 'When handed a program with noticeably more volume per session than he''s used to (multiple exercises with 4-5 sets across wide rep ranges per muscle group), he deliberately uses lighter loads than his normal working weight on the first pass through it, reasoning that going all-out immediately under unfamiliar volume isn''t something you can sustain for the whole session.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — I Paid A Stranger $13 To Make Me A Diet & Workout Program'),
('strength-accessories', 'deadlift as a whole-back builder despite short ROM', 'In an informal EMG test across 4 lifters of varying experience (including a beginner and a lighter-loading female lifter), deadlifts produced very high activation across every measured back muscle (traps, lower traps, upper and lower lats), ranking as one of the top two overall ''back builder'' movements alongside bent-over rows — despite the limited range of motion and largely isometric role of the back muscles during the lift — even though most viewers had predicted deadlifts would rank near the bottom for back activation.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — We Tested 17 Back Exercises, These Are Best For Growth'),
('strength-accessories', 'row grip affects which back region is emphasized', 'In the same test, bent-over rows done with an overhand grip produced more mid-back/trap activation, while an underhand grip with the elbows tucked close to the sides produced more lower-lat activation — so grip choice can be used to bias which back region a row targets.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — We Tested 17 Back Exercises, These Are Best For Growth'),
('strength-accessories', 'mid/upper back exercise ranking', 'For mid/upper back, wide-grip seated cable rows and dumbbell chest-supported rows (elbows flared out wide, shoulder blades squeezed together at the finish) produced the highest activation among loaded exercises tested; bodyweight inverted rows scored highest of all but mainly for the beginner and the female lifter, with the two more experienced male lifters showing comparatively lower activation on it — suggesting inverted rows are especially useful for beginners, or as a fatigue-focused finisher for advanced lifters rather than a primary loaded movement.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — We Tested 17 Back Exercises, These Are Best For Growth'),
('strength-accessories', 'lower trap isolation via Y-raise', 'A bodyweight incline prone Y-raise produced the highest lower-trap activation of anything tested; because the lower traps are easy to neglect but important for shoulder health and posture, they recommend including at least one dedicated lower-trap movement like this at the end of a back session.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — We Tested 17 Back Exercises, These Are Best For Growth'),
('strength-accessories', 'forward-lean ''lat focus row'' outperforms standard pulldowns', 'A ''lat focus row'' technique (credited to coach Casim of N1 Training — leaning the torso forward and keeping the elbows tucked close to the sides, making a row behave more like a pulldown) produced higher lat activation in testing than standard lat pulldowns and pull-ups, and worked well even for lifters trying the movement for the first time.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — We Tested 17 Back Exercises, These Are Best For Growth'),
('strength-accessories', 'muscle-up technique: false-grip transition', 'Calisthenics coach teaches the false-grip ring muscle-up: take a false grip on the rings before pulling so the shoulders roll over the rings into support during the pull, rather than transitioning after finishing the pull.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — BUILD MUSCLE WITH BODYWEIGHT EXERCISES (Calisthenics Workout)'),
('tempo', 'controlled eccentric tempo for straight-arm pressing progression', 'Coach prescribes a 3-0-X-0 tempo (3s controlled lowering, explosive push, no pauses) on a straight-arm/pike push exercise used to build shoulder pressing strength for beginners on rings.', 'practice', 'weak', NULL, '{"eccentric_sec": 3, "concentric": "explosive", "reps": "6-8"}'::jsonb, 'Will Tennyson (experiments, self-testing) — BUILD MUSCLE WITH BODYWEIGHT EXERCISES (Calisthenics Workout)'),
('strength-accessories', 'archer push-up as unilateral pressing progression', 'Archer push-ups (wide base, shifting weight onto one straight arm while the other extends out) are used as a unilateral pressing progression toward one-arm pressing strength, sequenced directly after straight-arm support work in the same session.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — BUILD MUSCLE WITH BODYWEIGHT EXERCISES (Calisthenics Workout)'),
('strength-accessories', 'scapular pull as pulling-session warm-up', 'Before loaded pulling work, coach has the athlete hang from a bar and perform scapular depression/retraction pulls as an activation drill, then repeats the retraction-protraction pattern standing before starting the main pulling exercises.', 'practice', 'weak', NULL, '{"hang_reps": "5-6", "floor_reps": 8}'::jsonb, 'Will Tennyson (experiments, self-testing) — BUILD MUSCLE WITH BODYWEIGHT EXERCISES (Calisthenics Workout)'),
('strength-accessories', 'asymmetric-load row as a one-arm-chinup progression', 'To build toward a one-arm chin-up, coach has the athlete row/pull with weight shifted mostly onto one arm while the other arm assists lightly, rather than training a strict one-arm hang directly.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — BUILD MUSCLE WITH BODYWEIGHT EXERCISES (Calisthenics Workout)'),
('progression', 'double progression on a fixed one-set full-body routine', 'Following a routine of one working set of 10-15 reps per exercise, he recommends progressing by adding one rep per week within the range, then resetting to the bottom of the range at a higher load and repeating the cycle, applied to every exercise in the program.', 'opinion', 'weak', NULL, '{"rep_range": "10-15", "note": "+1 rep/week within range, then add load and reset to bottom of range"}'::jsonb, 'Will Tennyson (experiments, self-testing) — I Tried The World''s Strictest Diet (According To Science)'),
('volume', 'single working set judged insufficient for physique goals', 'Judges a professionally-designed routine of one set of 10-15 reps (not to failure) per exercise as workable for a general-health or travel/time-crunched full-body routine, but explicitly ''nowhere near enough volume'' for someone training to build a physique.', 'opinion', 'weak', NULL, '{"sets_in_routine": 1, "reps": "10-15", "to_failure": false}'::jsonb, 'Will Tennyson (experiments, self-testing) — I Tried The World''s Strictest Diet (According To Science)'),
('volume', 'fewer, higher-quality sets vs. more mediocre sets', 'Doing 2 sets instead of the article''s prescribed 1 per exercise made him focus more on executing each set well; he states ''two good sets is better than four mediocre sets,'' i.e. per-set effort/quality can substitute for raw set count.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — I Tried The World''s Strictest Diet (According To Science)'),
('volume', 'capping working sets per exercise at three', 'States his programming will ''never go beyond three sets'' per exercise, reasoning that if every set and rep is maximally effortful, three sets is all that''s needed for a given exercise.', 'practice', 'weak', NULL, '{"max_sets_per_exercise": 3}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Cut Is Over | Chest & Back Workout + Night Routine'),
('progression', 'banking reserve capacity instead of chasing a lucky set', 'On an 8-10 rep incline bench target, when the first set comes easier than expected (e.g. could have hit 12 instead of 10), he does not chase the higher number on that set — he adds 1-2 reps on the following sets instead and saves the rest of the capacity for load progression the following week, rather than maxing out a single set.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Cut Is Over | Chest & Back Workout + Night Routine'),
('equipment', 'gym-to-gym equipment variance changes realized strength', 'The same load that was easy at his home gym (215 lb incline bench for 3x12) felt much harder at a different gym (3x10 near-max); he attributes this to differences in barbell whip/stiffness, bench padding, and incline angle between gyms, and advises not to be discouraged by strength appearing lower away from one''s usual equipment.', 'practice', 'weak', NULL, '{"load_lb": 215, "home_gym_reps": "3x12", "away_gym_reps": "3x10 (near-max)"}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Cut Is Over | Chest & Back Workout + Night Routine'),
('strength-accessories', 'dead-stop one-arm row to remove momentum and grip limitation', 'Uses a one-arm dumbbell row from a dead stop (dumbbell returns to the floor between reps) instead of a continuous/swinging row, stating this lets him overload the movement more and removes the stretch-reflex assistance that lets lifters cheat the concentric; he also straps in because grip fails before the back does.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Cut Is Over | Chest & Back Workout + Night Routine'),
('strength-accessories', 'pairing a vertical pull and a row to target lats vs. upper back separately', 'Structures back training with one vertical pulldown-style movement targeted deliberately at the lats and one row targeted deliberately at the upper back (pulling toward the upper chest/collarbone), treating the two pulling patterns as covering different regions of the back rather than being redundant.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — The Cut Is Over | Chest & Back Workout + Night Routine'),
('volume', 'proximity to failure varies by exercise role', 'Keeps roughly 1-2 reps in reserve on main compound lifts (chest, back) but pushes arm and accessory/isolation movements (e.g. lateral raises) close to or at failure (self-rated RPE 9-10) on every set.', 'practice', 'weak', NULL, '{"compound_reps_in_reserve": "1-2", "accessory_RPE": "9-10"}'::jsonb, 'Will Tennyson (experiments, self-testing) — The Cut Is Over | Chest & Back Workout + Night Routine'),
('volume', 'two all-out top sets on main compound lifts after ascending warm-ups', 'For main compound lifts (e.g. squat) does 3-4 ascending ''builder'' warm-up sets followed by only 2 all-out working sets of 6-8 reps, resting 3-5 minutes between them; reports this format is more motivating per set and that he has progressed strength faster since limiting himself to 2 top sets rather than more.', 'practice', 'weak', NULL, '{"builder_sets": "3-4", "top_sets": 2, "top_set_reps": "6-8", "rest_min": "3-5"}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Cutting DIET & ROUTINE | Healthy Recipes + Workout'),
('volume-per-muscle', 'prioritizing lateral raise volume over overhead pressing for shoulders', 'Deliberately programs more direct lateral raise volume (4 sets of 12-15 reps) than overhead pressing volume for shoulder development, stating he ''prioritizes them over a normal press.''', 'practice', 'weak', NULL, '{"lateral_raise_sets": 4, "lateral_raise_reps": "12-15"}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Cutting DIET & ROUTINE | Healthy Recipes + Workout'),
('strength-accessories', 'leaning lateral raise variation to remove cheating', 'Performs lateral raises leaning forward against an incline bench to remove the ability to use body momentum, stating this variation ''keeps me locked in and honest with my form.''', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — My Cutting DIET & ROUTINE | Healthy Recipes + Workout'),
('tempo', 'light-load, hold-the-contraction rear delt fly', 'Trains rear delt fly deliberately light, stating ''it''s all about the contraction and the hold at the top'' rather than the load moved.', 'practice', 'weak', NULL, '{"reps": "12-15"}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Cutting DIET & ROUTINE | Healthy Recipes + Workout'),
('strength-accessories', 'non-competing superset pairing late in a session', 'Supersets dumbbell RDL (hamstrings) with a bench-supported rear delt fly to pair two non-competing muscle groups back-to-back for time efficiency toward the end of a session.', 'practice', 'weak', NULL, '{"RDL_sets": 3, "RDL_reps": "8-10", "rear_delt_sets": 3, "rear_delt_reps": "12-15"}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Cutting DIET & ROUTINE | Healthy Recipes + Workout'),
('strength-accessories', 'Bulgarian split squat retained despite dislike, for VMO emphasis', 'Keeps Bulgarian split squats in leg programming specifically for vastus medialis (inner-quad, near-knee) emphasis, despite openly disliking the exercise.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — My Cutting DIET & ROUTINE | Healthy Recipes + Workout'),
('volume', 'contradiction: fewer near-maximal sets vs. weekly-volume dose-response', 'Practitioner caps himself at 2-3 sets per exercise (2 all-out top sets for compound lifts, a self-imposed 3-set ceiling generally) and reports faster strength progress since cutting set count, arguing near-maximal per-set effort substitutes for additional sets. This conflicts with the meta-analytic evidence this corpus holds at strong confidence that weekly training volume has a dose-response relationship with hypertrophy (more total sets per muscle per week, not just per-set effort, drives more growth up to roughly 10-20 sets/week); his self-report also does not include rigorous RIR tracking to confirm the sets are truly maximal.', 'practice', 'weak', NULL, '{"his_sets_per_exercise": "2-3"}'::jsonb, 'Will Tennyson (experiments, self-testing) — My Cutting DIET & ROUTINE | Healthy Recipes + Workout'),
('volume-per-muscle', 'daily direct training of a small muscle group', 'In a 30-day self-experiment, training the forearms with direct isolation work (3 sets to failure per sub-region: flexors, extensors, brachioradialis) every single day produced visible size growth and grip-strength gains, with a temporary strength dip around week 3 that recovered by day 30. The presenter had assumed daily training of the same muscle would prevent recovery/growth but did not find that to be the case for this small muscle group.', 'practice', 'weak', NULL, '{"sets_per_region": 3, "set_type": "to failure", "frequency": "daily", "duration_days": 30}'::jsonb, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('strength-accessories', 'biasing brachioradialis over biceps during curls', 'To shift curl emphasis from the biceps onto the brachioradialis, use a neutral (hammer) grip; placing the arm on an incline bench or in a preacher position puts the biceps at a mechanical disadvantage and forces the brachioradialis to work harder. Reverse-grip curls were also used to target this muscle.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('strength-accessories', 'cable vs. dumbbell for forearm/brachioradialis work', 'Switching brachioradialis and wrist-extension exercises from dumbbells to cables resolved wrist/elbow joint irritation that the dumbbell versions caused, while still allowing full engagement of the target muscle.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('equipment', 'lifting straps blunting forearm development', 'Chronic use of lifting straps on deadlifts and all back/biceps pulling work was identified, in hindsight, as a likely cause of underdeveloped forearms — the straps removed the grip demand from those exercises. Deliberately reducing strap use and relying more on raw grip was part of what improved forearm size and strength over the 30-day period.', 'practice', 'weak', NULL, '{"note": "straps had been used on deadlifts plus all back/biceps exercises, not just max-effort pulls"}'::jsonb, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('strength-accessories', 'grip training is modality-specific across grip types', 'In a 3-person, 30-day comparison, a dedicated hand-gripper protocol (crush-grip training) did not improve single-arm dead-hang time at all (support grip actually looked worse on retest), while a grip-endurance task (daily rice-bucket stirring, which mainly builds sustained sub-maximal grip) produced the largest dead-hang improvement of the three groups. Crush grip, support grip (dead hang), and pinch grip behaved as largely separate qualities that responded to different training methods.', 'practice', 'weak', NULL, '{"note": "gripper protocol: 100 reps/day with a hand gripper only; grip-endurance protocol: daily rice-bucket stirring with resistance progressively added"}'::jsonb, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('volume-per-muscle', 'forearm sub-region growth differs by training method', 'Across three different 30-day forearm protocols, hypertrophy localized to different regions of the forearm depending on method: a standard gym routine (wrist curls/extensions plus brachioradialis-biased curls) grew the upper and middle forearm with no change in the lower/wrist area; a hand-gripper protocol grew the middle and lower forearm most with little upper-forearm change; a grip-endurance (rice-bucket) protocol produced only modest upper-forearm growth and none in the middle or lower forearm.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('strength-accessories', 'forearm strength gains may carry over to curl performance in trained lifters', 'After 30 days of one-arm-only forearm training, the experienced lifter''s biceps-curl rep performance improved more on the forearm-trained arm than on the untrained control arm. The same effect was not seen in an untrained beginner who did only hand-gripper training — his curl performance on the trained side was unchanged — suggesting any transfer from forearm strength to curl performance may depend on overall training status.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('strength-accessories', 'farmer''s carry as an accessory finisher', 'Recommends adding farmer''s carries as a finisher at the end of a workout as a low-effort, high-value way to build grip/forearm strength, calling it especially useful for beginners.', 'practice', 'weak', NULL, NULL, 'Built With Science (Ethier) — 3 Guys Train Forearms Everyday - Only 1 Was Worth It'),
('strength-accessories', 'lat activation warm-up before pulldown working sets', 'Before working sets of lat pulldown, does a warm-up ''lat hold-out'' drill: sit with the lats pre-stretched, keep the elbows locked, and pull through a partial range using only the lats (not a full range of motion) to prime lat engagement before loading the full movement.', 'practice', 'weak', NULL, '{"warmup_sets": 2, "warmup_reps": 10}'::jsonb, 'Will Tennyson (experiments, self-testing) — Following an IFBB FIGURE PRO''S 1 Week Out Diet & Training | 1,200 Calories + Back Workout'),
('strength-accessories', 'single-arm drop-set finisher after each lat pulldown set', 'After every working set of lat pulldown, adds a quick single-arm drop-set variation (driving the elbow down and back, torso stationary, arm kept straight, alternating sides) to further fatigue the lats before moving on.', 'practice', 'weak', NULL, '{"reps_per_side": 10}'::jsonb, 'Will Tennyson (experiments, self-testing) — Following an IFBB FIGURE PRO''S 1 Week Out Diet & Training | 1,200 Calories + Back Workout'),
('strength-accessories', 'machine row cue for rhomboids/lower traps', 'On machine (mid) rows targeting the lower traps and rhomboids, cues keeping the torso parallel to the floor and letting any rotation come purely from the shoulder rather than an oblique/torso twist, emphasizing that the exercise ''isn''t about the weight, it''s about the contraction.''', 'practice', 'weak', NULL, '{"sets": 4, "reps": "10-15"}'::jsonb, 'Will Tennyson (experiments, self-testing) — Following an IFBB FIGURE PRO''S 1 Week Out Diet & Training | 1,200 Calories + Back Workout'),
('strength-accessories', 'preference for unilateral back work to prevent dominant-side compensation', 'Deliberately programs a lot of unilateral (single-arm) back exercises specifically to prevent a stronger/more dominant side from overpowering and compensating during bilateral pulling movements.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Following an IFBB FIGURE PRO''S 1 Week Out Diet & Training | 1,200 Calories + Back Workout'),
('strength-accessories', 'mind-muscle cue for seated cable rows', 'On seated cable rows, cues pulling with the lats rather than the arms, and recommends rehearsing the pulling pattern a few times before adding load/arm engagement, to reinforce a lat-driven pull.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Following an IFBB FIGURE PRO''S 1 Week Out Diet & Training | 1,200 Calories + Back Workout'),
('strength-accessories', 'sequencing band-assisted pull-ups last to avoid grip becoming the limiter', 'Places band-assisted pull-ups as the final exercise of a back session specifically because, by that point, grip and forearms are already fatigued from prior pulldowns/rows; doing pull-ups last (with band assistance) lets the lifter keep driving with the lats/chest instead of failing on grip.', 'practice', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — Following an IFBB FIGURE PRO''S 1 Week Out Diet & Training | 1,200 Calories + Back Workout'),
('volume', '20-set single-session back volume', 'A single back session of roughly 20 total working sets across 5 exercises (4 sets x 10-15 reps each) was described by an experienced lifter as unusually high volume he hadn''t done in about a decade, leaving him extremely fatigued and sore for an extended period afterward.', 'practice', 'weak', NULL, '{"total_sets": 20, "exercises": 5, "reps_per_set": "10-15"}'::jsonb, 'Will Tennyson (experiments, self-testing) — Following an IFBB FIGURE PRO''S 1 Week Out Diet & Training | 1,200 Calories + Back Workout'),
('equipment', 'cable-stack pulley ratios distort the displayed load on functional trainers', 'Some functional-trainer stations run the cable through pulley ratios (e.g. roughly 3:1 or 4:1) specifically to increase cable travel and smooth the movement for athletic exercises; as a side effect, a stack reading like ''45 lb'' can represent only about a third to a quarter of that as actual resistance. A reviewer flagged this as partly a deliberate design choice and partly ''vanity'' (makes the number look more impressive than the real load).', 'opinion', 'weak', NULL, '{"note": "example ratio cited: roughly 3:1, so a 300 lb stack yields about 1/4 (75-100 lb) of actual resistance at some settings"}'::jsonb, 'Will Tennyson (experiments, self-testing) — I Transformed My Basement into a Professional Gym!'),
('equipment', 'functional trainers not well suited to pull-ups', 'A gym-equipment reviewer specifically advised against doing pull-ups on a cable functional trainer, implying the cable/pulley setup on these machines is not a good substitute for a dedicated pull-up station or bar.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — I Transformed My Basement into a Professional Gym!'),
('equipment', 'T-bar row plate placement affects lat stretch', 'On a T-bar row where the loaded end sits far from the pivot point, the increased lever distance was noted (by both the lifter and a reviewer) to produce a noticeably deeper lat stretch at the bottom of the rep compared to a standard T-bar row setup.', 'opinion', 'weak', NULL, NULL, 'Will Tennyson (experiments, self-testing) — I Transformed My Basement into a Professional Gym!');
